window.__D("text/likkutei-sichot/c019",{"p":[[1301670154,"שגם המאורעות דל\"ז<sup data-n=\"801\">3</sup> שנים אלו השפיעו עליו והותירו רושמם בו, באופן של \"בא בימים\".\nואדרבה: יש לומר, שדוקא בימים אלו היו מאורעות חשובים ומכריעים בחיי אברהם עוד יותר מהמאורעות בשנות חייו הקודמים — לידת יצחק (ש\"ביצחק יקרא לך זרע\"<sup data-n=\"832\">30</sup>), עד לעקידת יצחק ופטירת שרה וכו'.\nו. על פי פירוש זה ב\"בא בימים\" (שימי האדם הם באופן ש\"נכנס\" בהם ופו­עלים עליו רושם כו') — יובן היטב פירוש הזהר<sup data-n=\"833\">31</sup> ב\"בא בימים\" — שכל ימי חייו היו שלמים בעבודת השם, שלא החסיר מלע­בוד את השם אפילו יום אחד מימי חייו.\nלפי הנ\"ל מובן, שפירוש הזהר אינו ע\"ד הרמז בלבד, אלא הוא מיוסד על הפירוש הפשוט ב\"בא בימים\", שלא הי' יום אצל אברהם שרק חלף ועבר, אלא אברהם בא ונכנס ב\"ימיו\", לעבוד את השם בכל יום ויום כפי שהי' נדרש בכל יום לפי ענינו.\nכלומר: הענין ד\"בא בימים\" לפי פשו­טו של מקרא (הנ\"ל), קאי על חייו הגש­מיים של אברהם, שמאורעות כל יום ויום השפיעו עליו וכו'; ואילו בזהר, פנימיות התורה, מודגש התוכן הפנימי של חיי אברהם, שהם חיי הנשמה ועבודת השם שלו, שהם חיי אברהם האמיתיים [ובלשון רבינו הזקן<sup data-n=\"834\">32</sup> \"שחיי הצדיק אינם חיים ב­שרים כי אם חיים רוחניים\"], ולכן מפרש, דזה שאברהם בא ונכנס בכל יום ויום (עד שהי' ניכר עליו הרושם של כל ימי חייו), היינו לפי שכל ימיו היו ממולאים בעבודת השם, באופן שכל יום ויום הי' יום \"חי\".\n(משיחת ש\"פ חיי שרה תשמ\"ח)\n{*} {*} {*}\nז. ע\"פ הנ\"ל בביאור דברי הזהר בפי­רוש \"בא בימים\", יש לבאר גם כן לשון הכתוב בתחילת פרשתנו \"ויהיו חיי שרה מאה שנה גו' שני חיי שרה\", דלכאורה יש לדייק: בדרך כלל, כשנאמר סכום שני חיי אדם בתורה, לשון הכתוב היא<sup data-n=\"835\">33</sup> \"ויהיו ימי. . \" או \"(ימי) שני חיי גו'\", וא\"כ גם כאן הול\"ל \"ויהיו ימי שרה\" או \"ויהיו שני שרה\" — ומהו הלשון \"ויהיו חיי שרה\"?\nויש לומר הביאור בזה:\nעיקר החידוש בכתוב זה הוא להודיע שכל ימי שרה היו ממולאים בעבודת השם בתכלית השלימות, בלשון המדרש<sup data-n=\"836\">34</sup> \"כ­שם שהן תמימים כך שנותם תמימים\", ועד (כפרש\"י<sup data-n=\"837\">35</sup>) ש\"כולן שוין לטובה\", שמדת ה\"טוב\" של כל שנותי' היתה באופן שווה.\nולכאורה הדברים תמוהים: כיצד אפשר לומר שכל קכ\"ז השנים של שרה היו \"שוין לטובה\"? הרי מובן, שאין ל­השוות את מעמדה ומצבה בהיותה באור כשדים, וכן בחרן, לגבי מעמדה ומצבה לאחרי שבאה \"אל הארץ אשר אראך\"<sup data-n=\"838\">36</sup>, ולאידך — בקכ\"ז שנה אלו נכלל גם הזמן שהיתה בבית פרעה וכן בבית אבימלך וכו'.",[["801","3","כ\"ה בכלי יקר. ולכאורה צ\"ע, שהרי הי' בערך מ\"א שנה, כי \"ואברהם ושרה זקנים גו'\" הי' שנה לפני לידת יצחק, ו\"אברהם זקן גו'\" דפרשתנו הי' קצת קודם נישואי יצחק ורבקה, ו\"יצחק בן ארבעים שנה בקחתו את רבקה\" (תולדות כה, כ). — וראה אברבנאל (השאלה הא') ועוד פרשתנו."],["832","30","וירא כא, יב."],["833","31","ראה זהר פרשתנו קכט, א. זהר ויחי רכא, ב ואילך. רכד, א. וראה תו\"א פרשתנו טז, א. משפטים עט, ב. ועוד. לקו\"ש ח\"ד ע' 1194. ח\"כ ע' 315 ואילך. וש\"נ."],["834","32","תניא אגה\"ק ביאור לסי' ז\"ך בתחלתו (קמו, ב)."],["835","33","ראה לדוגמא בדורות שנמנו בס\"פ ברא­שית; נח ט, כט; ס\"פ נח; סוף פרשתנו (כה, ז. שם, יז). ועוד."],["836","34","ב\"ר ריש פרשתנו."],["837","35","ריש פרשתנו."],["838","36","ר\"פ לך לך."]]],[1301670155,"אך הביאור בזה — בפשטות<sup data-n=\"839\">37</sup>: \"חיי שרה\" פירושו — הענינים שבהם חייתה שרה, ו\"חיי שרה\" היו \"שוין לטובה\", ב­משך כל שנותי' [ע\"ד הנ\"ל מזהר בפירוש \"בא בימים\" שנאמר אצל אברהם, שכל יום ויום הי' שלם בעבודת ה'].\nדהנה מובן, שהמשמעות האמיתית ד­\"חיי שרה\" לא היו חיי הגוף שלה (אכילה ושינה וכיו\"ב) — דלא בענינים אלו \"חיי­תה\" שרה אמנו. ופשיטא, כאשר היתה ב­בית פרעה או בבית אבימלך, הרי הצד הבלתי­רצוי שבזה לא הי' חלק מ\"חיי שרה\" [שהרי אדרבה, היותה סגורה בבית פרעה ובית אבימלך גרם לה צער גדול].\nאלא \"חיי שרה\" הם החיים הרוחניים שלה, החל מג' המצוות המיוחדות לנשי ישראל, כמובא בפרש\"י פרשתנו<sup data-n=\"840\">38</sup> \"נר דלוק מערב שבת לערב שבת, וברכה מצוי' בעיסה, וענן קשור על האהל\" (כמבואר במפרשים<sup data-n=\"841\">39</sup> שהם כנגד ג' ה­מצוות דהדלקת נר שבת, חלה ונדה).\nוחיים אלו היו \"שוין לטובה\" כל רגע ורגע בהיותה עלי אדמות<sup data-n=\"842\">40</sup>.\nוזוהי ההדגשה \"ויהיו חיי שרה גו'\" — דאף שימי ושני שרה, כללו הרבה חילו­קים ושינויים במעמדה ומצבה, אבל \"חיי שרה\" היו באופן שוה במשך כל ימי חיי', \"כולן שוין לטובה\"<sup data-n=\"843\">41</sup>.\n<span data-k=\"q\">(משיחת ש\"פ חיי שרה תשמ\"ג)</span>",[["839","37","הביאור ע\"פ פנימיות הענינים — ראה לקו\"ש ח\"ה ע' 352 ואילך. ח\"כ ע' 325 ואילך. ועוד."],["840","38","כד, סז."],["841","39","חזקוני, גו\"א ועוד שם. וראה לקו\"ש חט\"ו ע' 172. ועוד."],["842","40","גם בהיותה בבית פרעה כו'."],["843","41","ופירוש סיום הכתוב \"שני חיי שרה\" (שממנו נלמד \"כולן שוין לטובה\") — שבמשך כל שנותי', היו חיי' שוין לטובה."]]],[1301670156,"<h3>שיחה ג</h3>\nא. \"ויוסף אברהם ויקח אשה ושמה קטורה ותלד לו גו'\"<sup data-n=\"844\">1</sup>.\nוידועה התמי' בזה: בכמה כתובים קודמים מפורש, שלידת יצחק בהיות אברהם בן מאה היתה דבר נסי (לא רק בגלל גילה של שרה אלא גם) כיון ש­אברהם הי' בגיל שע\"פ טבע אינו יכול להוליד:\n\"ויפל<sup data-n=\"845\">2</sup> אברהם על פניו ויצחק ויאמר בלבו הלבן מאה שנה יולד (ואם שרה הבת תשעים שנה תלד)\"; \"ואברהם<sup data-n=\"846\">3</sup> ושרה זקנים באים בימים גו' ותצחק שרה בקרבה לאמר אחרי בלותי היתה לי עדנה ואדוני זקן\"; \"ותאמר מי מלל לאברהם גו' כי ילדתי בן לזקוניו\"<sup data-n=\"847\">4</sup>, ועד \"שהיו ליצני הדור אומרים מאבימלך נתעברה שרה\"<sup data-n=\"848\">5</sup>.\nע\"פ זה יש להבין מדוע כשנולדו לאברהם עוד ששה בנים, ארבעים שנה לאחרי לידת יצחק, כשהי' בן ק\"מ שנה<sup data-n=\"849\">6</sup>, לא נתפרש בכתוב שזהו דבר נסי ומופ­לא וכו'.\nוהנה הרמב\"ן<sup data-n=\"845\">2</sup> כתב אודות לידת יצחק שאין הפלא בבן ק' שיוליד<sup data-n=\"851\">7</sup>, ומביא ראי' מהנ\"ל — ש\"אחרי זה מ' שנה הוליד בנים רבים מקטורה\". אבל אין לפרש כן שיטת ודעת רש\"י, שהרי מ­פשטות הכתובים הנ\"ל לא משמע כן, ואם ס\"ל לרש\"י הכי הי' לו לפרשו, ויתרה מזה מפירושו גופא<sup data-n=\"845\">2</sup> משמע ל­היפך, שכתב \"אע\"פ שדורות הראשונים היו מולידין בני ת\"ק שנה בימי אברהם נתמעטו השנים כבר ובא תשות כח בעולם וצא ולמד מעשרה דורות שמנח ועד אברהם שמיהרו תולדותיהם בני ס' ובני ע'\"<sup data-n=\"853\">8</sup>.\nואפילו את\"ל שאצל אברהם<sup data-n=\"854\">9</sup> לא הי­תה תשות כח עד היותו בן מאה<sup data-n=\"855\">10</sup> [או ש(לאחר זמן ד\"ואברהם<sup data-n=\"856\">11</sup> ושרה זקנים\") חזר לנערותו והוליד בהיותו בן מאה<sup data-n=\"857\">12</sup>], הרי לאחרי זה נאמר בפרשתנו (עוד פעם) \"ואברהם זקן בא בימים\"<sup data-n=\"858\">13</sup>, היינו",[["844","1","פרשתנו כה, א."],["845","2","לך יז, יז."],["846","3","וירא יח, יא­יב. וראה שם, יג."],["847","4","שם כא, ז."],["848","5","לשון רש\"י ר\"פ תולדות."],["849","6","ראה רש\"י פרשתנו (כד, סב) שבעת שחזר יצחק מהליכתו להביא את הגר לאברהם שישאנה פגש את רבקה כו', ויצחק נשא את רבקה בהיותו בן ארבעים שנה (תולדות כה, כ)."],["845","2","לך יז, יז."],["851","7","וראה גם רמב\"ן ויגש מו, טו."],["845","2","לך יז, יז."],["853","8","ראה גם ראב\"ע לך שם. אלא שממשיך \"וכ­אשר תסתכל ותרא כי דבר שרה נפלא מדבר אברהם\"."],["854","9","ראה בארוכה במפרשי רש\"י לך שם. ולדעת כמה (הרא\"ם ועוד) לא הי' שום נס בזה שאברהם הוליד. אבל ראה גו\"א ובאר בשדה שם (ועוד), שגם בזה שאברהם הוליד הי' נס, כדיוק לשון הכתובים הנ\"ל. וראה הערה הבאה."],["855","10","ראה בארוכה לקו\"ש ח\"כ ע' 80 ואילך. אבל גם בפרש\"י יש לפרש בכמה אופנים. ובפרט שברש\"י אין בירור גמור, ע\"ד שרש\"י עצמו ב­פשש\"מ מביא כמ\"פ ב' (ויותר) פירושים בכתוב.\nועוד, דאפילו את\"ל (כנ\"ל) דאצל אברהם לא הי' נס מאחר שלא היתה אצלו תשות כח מתחילה, הרי זה גופא הוא פלא וחסד — ראה פרש\"י לך שם."],["856","11","וירא יח, יא."],["857","12","ראה ב\"ר פנ\"ג, ט \"מלל. . מוליד למאה שנה. . יבשה ונעשה מלילות\". וראה ב\"ר שהובא בסמוך בפנים."],["858","13","כד, א. — וראה לעיל ע' 89 ואילך."]]],[1301670157,"שהי' אצלו זיקנה שנוסף לאח\"ז, וא\"כ הרי הולדת בני קטורה בהיותו בן ק\"מ היא דבר נסי.\nוכמובן מדברי המדרש<sup data-n=\"859\">14</sup> על הכתוב \"ואברהם זקן גו'\" — \"אמר ר' יוחנן כבר כתיב ואברהם ושרה זקנים מה ת\"ל ואב­רהם זקן אלא שהחזירו הקב\"ה לימי נערותיו צריך לכתוב פעם שני' ואברהם זקן, רב אמי אמר כאן זקנה שיש בה לחלוחית ולהלן בזקנה שאין בה לח­לוחית\"<sup data-n=\"860\">15</sup> — הרי שאפילו את\"ל שלידת יצחק היתה נס מצד אברהם (שזקנה ותשות כח השייכת להולדה לא שלטה עליו), מ\"מ צריך לנס בשביל הולדת הבנים מקטורה שהיתה לאחרי שכבר נאמר עוה\"פ \"ואברהם זקן בא בימים\"<sup data-n=\"861\">16</sup>.\nב. ויש לומר נקודת הביאור בזה:\nבסיפור לידת יצחק נאמר<sup data-n=\"862\">17</sup> \"ותאמר שרה צחוק עשה לי אלקים כל השומע יצחק לי\", ופרש\"י<sup data-n=\"863\">18</sup> \"הרבה עקרות נפק­דו עמה, הרבה חולים נתרפאו בו ביום, הרבה תפלות נענו עמה, ורב שחוק הי' בעולם\", הרי שהנס דלידת יצחק הי' באופן כזה שגרם ישועה והצלה בכל העולם, עד שהביא ששמחה ורב שחוק הי' בעולם.\nובזה יובן מ\"ש רש\"י שם עה\"פ<sup data-n=\"847\">4</sup> היניקה בנים שרה — \"מהו בנים לשון רבים, ביום המשתה הביאו השרות את בניהן עמהן והניקה אותם, שהיו אומרות לא ילדה שרה אלא אסופי הביאה מן השוק\"<sup data-n=\"865\">19</sup>, וכן בפרשת לך לך<sup data-n=\"866\">20</sup> פרש\"י \"ובהנקת שדים כשנצרכה לכך ביום מש­תה של יצחק שהיו מרננים עליהם שה­ביאו אסופי מן השוק ואומרים בננו הוא והביאה כל אחת בנה עמה ומניקתה לא הביאה והיא היניקה את כולם\".\nדלכאורה, אם טעם הדבר הי' רק כדי להוכיח ששרה ילדה את יצחק ואינו אסופי מן השוק, הי' מספיק שכולם יראו שמניקה את יצחק, או שתניק עוד כמה בנים, אבל למה הוצרכה להניק את \"כולם\"? אלא שהי' בזה ענין נוסף, שהנס דלידת יצחק גרם לכו\"כ עניני השפעה ועד ל\"רב שחוק. . בעולם\", ולכן בא זה לידי ביטוי גם בזה שהניקה בניהם של כל השרות.\nועפ\"ז י\"ל, שכשם שמצינו אצל שרה, שהנס דלידת יצחק גרם לעוד כמה נסים אצלה ובזכותה, ונסים שהביאו ישועה והצלה בעולם (\"הרבה עקרות נפקדו עמה. . נענו עמה\", ועד להניק בניהם של כל השרות) — עד\"ז הוא בנוגע לאברהם, שהנס דלידת יצחק גרם לעוד נסים אצלו, שנולדו לו עוד בנים בדרך פלא ונס (לאחרי ש\"אברהם זקן בא בימים\"), ובנים אלו אינם בני ישראל אלא מאומות העולם (ע\"ד הנ\"ל בשרה).\nג. אלא שטעמא בעי: מהו הטעם שהנס דלידת יצחק גרם לעוד נסים שיהי' \"שחוק. . בעולם\"?\nוגם יש להבין השינוי בזה בין אב­רהם לשרה:\nא) אצל שרה היתה פעולה זו בעולם",[["859","14","ב\"ר פמ\"ח, טז."],["860","15","ראה בארוכה מפרשי המדרש."],["861","16","וראה בארוכה נזר הקודש (השלם) לב\"ר שם (וראה גם באר בשדה לך שם). וראה פי' מהרז\"ו שם. ועוד."],["862","17","וירא כא, ו."],["863","18","והוא בב\"ר פנ\"ג, ח. וראה פסיקתא רבתי פ' מב (מג) — וה' פקד. פסיקתא דר\"כ פ' כב — שוש אשיש."],["847","4","שם כא, ז."],["865","19","מב\"מ פז, א. ב\"ר שם, ט. ובכ\"מ. וראה פדר\"א פנ\"ב. פסיקתא דר\"כ שם."],["866","20","יז, טז. ומסיים: בראשית רבה רמזו במקצת."]]],[1301670158,"תיכף ומיד, \"הרבה עקרות נפקדו בו ביום\", וכן זה שהניקה בנים שרה, ואילו אצל אברהם הי' זה משך זמן רב — ארבעים שנה — אחר לידת יצחק.\nב) אצל שרה בא זה כתוצאה ממילא מלידת יצחק, בלי פעולה מיוחדת מצד שרה, משא\"כ אצל אברהם הי' זה כענין בפ\"ע, הולדת בנים — אוה\"ע (מקטורה) באופן נסי.\nויש לומר, שבזה נרמז ענין עיקרי ויסודי בהשפעת בני ישראל באומות העולם.\nדהנה מצינו שקודם לידת יצחק הי' צ\"ל שינוי שמם של אברהם ושרה, כ­פרש\"י<sup data-n=\"867\">21</sup> \"אברם אין לו בן אבל אברהם יש לו בן, וכן שרי לא תלד אבל שרה תלד\". שהטעם הוא לפי ש\"אני קורא לכם שם אחר וישתנה המזל\". ביחד ע\"ז מסתבר לומר, שלידת יצחק שייכת ל­תוכן ב' השמות החדשים: \"אברהם\" ו\"שרה\".\nולכאורה תמוה: תוכן השמות \"אב­רהם\" ו\"שרה\" (ביחס ל\"אברם\" ו\"שרי\") מורה על השליטה על כל העולם — \"אב המון גוים נתתיך\"<sup data-n=\"868\">22</sup>, לא רק \"אברם\" — \"אב לארם\" אלא \"אב לכל העולם\"<sup data-n=\"868\">22</sup>, ו\"שרה\" פירושו (כפרש\"י<sup data-n=\"870\">23</sup>) \"[לא] שרי (דמשמע) לי ולא לאחרים כי שרה סתם שמה שתהא שרה על כל\"; ומהי ה­שייכות בין שינוי השמות האלה ללידת יצחק, שהוא התחלת עם ישראל, \"כי ביצחק יקרא לך זרע\"<sup data-n=\"871\">24</sup>?\nומשמע מזה, שענין עיקרי בלידת יצחק (ועם ישראל) הוא הפעולה (וה­שליטה) על אומות העולם.\nועפ\"ז יש לומר, שזהו תוכן ענין הנסים שבאו בהמשך ללידת יצחק שגר­מו שיהי' \"רב שחוק. . בעולם\", שעי\"ז הודגש ענין השררה שלהם על העולם כולו, שהם הגורמים שתהי' ישועה בעולם; ובזה גופא היו שני סוגים — הנסים השייכים לשרה והנסים דאברהם (הולדת בני קטורה) — בהתאם להחילוק בין ענינו של אברהם וענינה של שרה, כדלקמן.\nד. ויובן זה בהקדם דברי הרמב\"ם<sup data-n=\"872\">25</sup> אודות חיוב ז' מצות בני נח: \"צוה משה רבינו מפי הגבורה לכוף את כל באי העולם לקבל מצות שנצטוו בני נח\", \"כל המקבל שבע מצות ונזהר לעשותן הרי זה מחסידי אומות העולם ויש לו חלק לעולם הבא והוא שיקבל אותן ויעשה אותן מפני שצוה בהן הקב\"ה בתורה והודיענו על ידי משה רבינו כו' אבל אם עשאן מפני הכרע הדעת. . אינו מחסידי אומות העולם\".\nוצ\"ע, הרי \"משה רבינו לא הנחיל התורה והמצות אלא לישראל\"<sup data-n=\"873\">26</sup>, ומהי השייכות דב\"נ למ\"ת ולבנ\"י ועד שבנ\"י צריכים לכוף את כל באי העולם לקבל מצות שנצטוו בני נח, והם יעשו אותן מפני שצוה הקב\"ה כן בתורה?\nונתבאר בזה כמ\"פ<sup data-n=\"874\">27</sup> ע\"פ מחז\"ל<sup data-n=\"875\">28</sup> שכל הבריאה היא בשביל ישראל שנק' ראשית ובשביל התורה שנקראת ראשית,",[["867","21","לך טו, ה."],["868","22","שם יז, ה ובפרש\"י."],["868","22","שם יז, ה ובפרש\"י."],["870","23","שם יז, טו."],["871","24","וירא כא, יב."],["872","25","הל' מלכים פ\"ח ה\"י וי\"א."],["873","26","רמב\"ם שם ריש הלכה יו\"ד."],["874","27","ראה לקו\"ש ח\"כ ע' 140 ואילך. וש\"נ."],["875","28","פרש\"י ר\"פ בראשית. וראה תנחומא בא­בער שם יו\"ד. אותיות דרע\"ק אות ב'."]]],[1301670159,"היינו שאין זה דבר נוסף על מציאות הבריאה, אלא זה קשור עם עצם מצי­אותה<sup data-n=\"876\">29</sup>. ולכן, לאחרי לידת עם ישראל ונתינת התורה, אי אפשר שיהי' איזה ציווי ה' לעולם מבלי אמצעות התורה וישראל — ולכן תלוי קיום שבע מצות ב\"נ בתורה ובישראל.\nויש לדייק ברמב\"ם הנ\"ל, אשר שני הפרטים הנ\"ל (א) \"צוה משה רבינו מפי הגבורה לכוף את כל באי העולם לקבל מצות שנצטוו בני נח\", (ב) שצריך לעשות אותן \"מפני שצוה בהן הקב\"ה בתורה והודיענו על ידי משה רבינו\" — כתבם הרמב\"ם בשתי הלכות נפרדות.\nולכאורה, מזה שלא הזכיר הרמב\"ם בהמשך להחיוב \"לכוף את כל באי העולם לקבל מצות שנצטוו\" שחיוב זה כולל שקבלת המצוות שלהם תהי' מפני שצוה בהן הקב\"ה בתורה, וכתב תנאי זה (\"והוא שיקבל כו'\") בהלכה בפני עצמה בהגדרת \"חסידי אומות העולם\", מובן, שדין זה (\"והוא שיקבל אותן. . מפני ש­צוה בהן הקב\"ה בתורה\") הוא דין בפ\"ע [וצ\"ע אם יש חיוב על בנ\"י לכוף את כל באי העולם שיהיו חסידי אוה\"ע].\nאבל מזה שהביא הרמב\"ם גם תנאי זה בהמשך לחיוב דישראל לכוף כו', מש­מע, שאף שאין זה חלק מהחיוב הא', מ\"מ, שלימות הקבלה של הבן נח (שתח­לתה באה ע\"י כפיית ישראל), שמקבל המצוות מחמת ציווי הקב\"ה בתורה, יש ג\"כ לה קשר עם בני ישראל<sup data-n=\"877\">30</sup>.\nואולי י\"ל, שיש ב' אופנים בפעולות בנ\"י על אוה\"ע: א) השפעה ע\"י כפי' (אם כפשוטה<sup data-n=\"878\">31</sup> או ע\"י כפיית דברים<sup data-n=\"879\">32</sup>) — לקבל מצות שנצטוו ב\"נ, ב) פעולה ב­עקיפין, שבהמשך לכפי' זו באים אוה\"ע לידי הכרה שצריכים לקבל המצוות \"מפני שצוה בהן הקב\"ה בתורה והודיענו על ידי משה רבינו כו'\"<sup data-n=\"880\">33</sup>.\nה. ויש לומר, ששני אופנים אלו מרומזים גם בסיום ב' הפרקים האח­רונים<sup data-n=\"881\">34</sup> של ספר הרמב\"ם<sup data-n=\"882\">35</sup>, בסוף הל' מלכים (ומלחמותיהם<sup data-n=\"883\">36</sup>):",[["876","29","וראה גם פרש\"י שם א, לא (משבת פח, א. ע\"ז ג, א)."],["877","30","ראה בארוכה בכ\"ז לקו\"ש חכ\"ו ע' 132 ואילך."],["878","31","כשיד ישראל תקיפה."],["879","32","תוי\"ט אבות פ\"ג מי\"ד. וראה בארוכה לקו\"ש שם."],["880","33","וכן ישנם ב' אופנים אלה בפעולת בנ\"י על אוה\"ע במשך הדורות: א) ע\"י מלחמה לכבוש ארצם, שאז דינם ש\"יהיו לך למס ועבדוך\" (שופטים כ, יא), שיקבלו עליהם שבע מצות שנצטוו בני נח והרי הם למס (רמב\"ם הל' מלכים רפ\"ו), ב) כמו שהי' בימי שלמה ד\"וישב שלמה על כסא ה'\" (דה\"א כט, כג), ולא הוצרך למלחמה אלא מלכת שבא הביאה כו' ל­שלמה (מ\"א י, א ואילך. דה\"ב ט, א ואילך) [ובסגנון תורת החסידות, בירור בדרך מלחמה או בירור ב­דרך מנוחה — ראה לקו\"ת במדבר ג, ד ואילך. וראה סה\"מ תרנ\"ט ע' קסב ואילך. סה\"מ תש\"ד ע' 106 ואילך. ועוד]."],["881","34","ובהכותרת לפרקים אלו פרק יא וי\"ב בד­פוס וינציאה (רפד. שי) הוא \"הלכות מלכים ומל­חמות ומלך המשיח\"."],["882","35","בשבוע זה<sup data-n=\"e28\">*</sup> ביום כ\"ד מרחשון הוא סיום המחזור הששי של לימוד הרמב\"ם ג\"פ ליום (וכן סיום המחזור השני של לימוד הרמב\"ם פרק אחד ליום), וביום כ\"ה מר­חשון היא התחלת לימוד הרמב\"ם מחדש — מחזור השביעי (דג\"פ ליום), וכל השביעין חביבין (ומחזור השלישי — דבתלתא זימני הוי חזקה — דפרק א' ליום)."],["883","36","זהו השם המלא כבהקדמת הרמב\"ם (ב\"מנין המצות על סדר הלכות הרמב\"ם\") ובהכותרת בספר שופטים והל' מלכים."],["e28","*","בשנת תש\"נ — כשי\"ל הליקוט בפעם הא'. המו\"ל."]]],[1301670160,"בסוף פרק יא מסיים הרמב\"ם \"וקבץ נדחי ישראל. . ויתקן את העולם כולו לעבוד את ה' ביחד שנאמר<sup data-n=\"884\">37</sup> כי אז אה­פוך אל עמים שפה ברורה לקרוא כולם בשם ה' ולעבדו שכם אחד\", ובסוף פרק יב מסיים \"ובאותו הזמן לא יהי' שם לא רעב כו' שהטובה תהי' מושפעת הרבה כו' ולא יהי' עסק כל העולם אלא לדעת את ה' בלבד ולפיכך יהיו ישראל חכמים גדולים ויודעים דברים הסתומים וישיגו דעת בוראם כפי כח האדם שנאמר<sup data-n=\"885\">38</sup> כי מלאה הארץ דעה את ה' כמים לים מכסים\".\nכלומר: בסוף פרק יא מדובר אודות פעולת משיח ובנ\"י באוה\"ע, \"ויתקן<sup data-n=\"886\">39</sup> את העולם כולו כו'\", ואילו בסוף פי\"ב מד­בר אודות הנפעל באוה\"ע בדרך ממילא, דפשטות הלשון \"ולא יהי' עסק כל ה­עולם אלא לדעת את ה' בלבד\" (שכוונתו לכללות המין האנושי, גם אוה\"ע<sup data-n=\"887\">40</sup>) אינו באופן שבנ\"י יתעסקו עמהם. אבל מ\"מ ה\"ז שייך לבנ\"י, היינו שזהו תוצאה מע­בודת בנ\"י, וכדמוכח מזה שכולל באותה הלכה הן מעלת ידיעת ה' דבנ\"י והן זה שעסק כל העולם כולו יהי' לדעת את ה', והיינו שזה ש\"לא יהי' עסק כל העו­לם אלא לדעת את ה' בלבד\" יהי' קשור ותוצאה ממצב בנ\"י באותו הזמן.\nובזה יובן הדיוק בדברי הרמב\"ם ב­הלכה שלפנ\"ז<sup data-n=\"888\">41</sup> \"לא נתאוו החכמים וה­נביאים ימות המשיח לא כדי שישלטו על כל העולם ולא כדי שירדו בעכו\"ם ולא כדי שינשאו אותם העמים ולא כדי לאכול ולשתות ולשמוח, אלא כדי שיהיו פנויין בתורה וחכמתה\". דלכאורה תמוה, איך יעלה על הדעת לפרש ש\"נתאוו החכמים והנביאים ימות המשיח. . כדי שישלטו על כל העולם. . ירדו בעכו\"ם. . כדי שינשאו אותם העמים\", והרי אפילו בנוגע לחכמי אוה\"ע מצינו שעיקר עיסקם ומשאת נפשם הוא במושכלות<sup data-n=\"889\">42</sup> ואין להם תשוקה לשלוט ולרדות, וכ\"ש וק\"ו שכ\"ה בנוגע לחכמי ונביאי ישראל?\nאלא כוונת הרמב\"ם היא, דסלקא דעתך אמינא שתכלית המעלה שאלי' נתאוו החכמים וכו' היא לתקן את ה­עולם, היינו ללמד את העולם דעת את הוי' באופן של פעולה והשפעה (כמ\"ש בפרק יא), שזהו ענין של שליטה ורדי' אמיתית (ברוחניות). וקמ\"ל הרמב\"ם כאן שזה אינו שלימות הענין, ולא בשביל זה נתאוו החכמים והנביאים לימות המשיח, אלא כדי שיהיו פנויין בתורה וחכמתה ויהיו חכמים גדולים ויודעים דברים ה­סתומים.\nאבל אעפ\"כ ממשיך, כנ\"ל, שגם דרגא נעלית זו דבנ\"י פועלת בעולם, שבדרך ממילא יהי' מצב כל העולם באופן נעלה ביותר, ש\"לא יהי' עסק כל העולם אלא לדעת את ה' בלבד כו' שנאמר כי מלאה הארץ דעה את ה' כמים לים מכסים\".\nו. ע\"פ כל הנ\"ל יובן גם תוכן הענין שקודם לידת יצחק הי' צ\"ל שינוי השם דאברהם ושרה, \"אב המון גוים\" ו\"שרה על כל\" — כי בראשית יצירת עם ישראל בהולדת יצחק ע\"י אברהם ושרה הי' צ\"ל מודגש שמציאותם של ישראל (אינה ענין ופרט בהבריאה, אלא) היא עיקר ומטרת כללות הבריאה כולה.\nוזהו גם הטעם שלידתו של יצחק ב­",[["884","37","צפני' ג, ט (ושם: לעבדו. וראה לקו\"ש חכ\"ג ע' 103 בהערה)."],["885","38","ישעי' יא, ט."],["886","39","ראה לקו\"ש חכ\"ה ע' 127 הערה 47."],["887","40","ראה לקו\"ש חכ\"ז ע' 246 ואילך."],["888","41","בפי\"ב ה\"ד."],["889","42","ראה תו\"א תולדות יט, רע\"ג."]]],[1301670161,"דרך נס היתה באופן כזה שפעל באוה\"ע כנ\"ל, \"הרבה עקרות נפקדו עמה הרבה חולים נתרפאו בו ביום הרבה תפלות נענו עמה ורב שחוק הי' בעולם\", ותוס' השפעה שבשרה באופן ד\"היניקה בנים שרה\", ועד\"ז באברהם, שהפלא והחסד דאברהם בהולדת יצחק, פעל גם ש­הוליד עוד (ששה) בנים מקטורה — כי כדי שבנ\"י יוכלו לפעול על אוה\"ע, היתה פעולה מיוחדת ע\"י הקב\"ה שגם אוה\"ע ירגישו דבר זה גופא, שעיקר מציאותו של העולם, כולל מציאותם דב\"נ, הוא ישראל.\n[וע\"ד שמצינו בנוגע לתורה — ש­ארז\"ל<sup data-n=\"890\">43</sup> \"שכשניתנה תורה לישראל הי' קולו הולך מסוף העולם ועד סופו וכל מלכי עובדי כוכבים אחזתן רעדה ב­היכליהן כו' נתקבצו כולם אצל בלעם הרשע ואמרו לו מה קול ההמון אשר שמענו שמא מבול בא לעולם כו' א\"ל חמדה טובה יש לו בבית גנזיו כו' וביקש ליתנה לבניו שנאמר<sup data-n=\"891\">44</sup> ה' עוז לעמו יתן מיד פתחו כולם ואמרו<sup data-n=\"891\">44</sup> ה' יברך את עמו בשלום\"]<sup data-n=\"893\">45</sup>.\nועפ\"ז מתורצת בפשטות הקושיא: ידוע דקוב\"ה לא עביד ניסא למגנא, וזה מובן בפשטות, דכיון שהקב\"ה קבע את הבריאה באופן מסודר וטבעי, \"לא יש­בותו\"<sup data-n=\"894\">46</sup>, לא ישנה את סדרי הבריאה אלא לצורך מיוחד<sup data-n=\"895\">47</sup>.\nוא\"כ תמוה, מהו הצורך וההכרח שהנס דלידת יצחק יביא ויגרום לעוד נסים — \"היניקה בנים שרה\" וכו', כנ\"ל שייעשה נס גדול כזה, שהרבה עקרות נפקדו כו', היפך טבע הבריאה?\nאלא שלא הי' בזה נס נוסף<sup data-n=\"896\">48</sup>, כי אם המשך ותוצאה מכללות הנס של לידת יצחק, כי לידת יצחק לא היתה נס פרטי, רק לאברהם ושרה, אלא נס כללי מ­לכתחילה, כדי שתהי' לידת יצחק נעשו אברהם ושרה \"אב לכל העולם\" ו\"שרה על כל\" — ובדרך ממילא כשארע הנס נפעל ונמשך ב\"כל העולם\" וב\"כל\", ונשתנו סדרי בראשית (כולל אוה\"ע).\nז. והנה בפעולת הנס דלידת יצחק על אוה\"ע גופא, היו שני פרטים (מצד אברהם ומצד שרה, כנ\"ל) — שיש לומר, ששני ענינים אלו הם השרש לשני ה­אופנים הנ\"ל בפעולת ישראל על אוה\"ע — ובהתאם להחילוק בתוכן עבודת אב­רהם ושרה, המודגש גם בשמם החדש שניתן להם לפני הולדת יצחק:\nאברהם ע\"ש \"אב המון גוים\", \"אב לכל העולם\", מורה על שייכות ל\"המון גוים\", \"כל העולם\", ולכן גם ההשפעה הנסית שנעשתה על ידו ב\"המון גוים\" היתה ע\"י פעולה מיוחדת מצד אברהם (להוסיף בעולם) — \"ויוסף אברהם ויקח אשה גו' ותלד לו גו'\" (ומטעם זה באה (לא בקירוב זמן להולדת יצחק אלא) לאחר זמן, כי בזה מודגש שבאה בדרך פעולה חדשה).\nמשא\"כ שרה שהיא \"שרה על כל\", ה\"ז גדר של שררה ומלכות, שהמלך הוא",[["890","43","זבחים קטז, סע\"א. מכילתא ר\"פ יתרו. ובכ\"מ."],["891","44","תהלים כט, יא."],["891","44","תהלים כט, יא."],["893","45","וביותר מודגש ע\"פ מרז\"ל (ע\"ז ב, ב. וראה ספרי ורש\"י ברכה לג, ב) שהקב\"ה החזיר את התורה על כל אומה ולשון כו'. וראה פנים יפות ברכה שם. אוה\"ת עה\"פ. ועוד."],["894","46","נח ח, כב."],["895","47","ראה דרשות הר\"ן דרוש ח' הקדמה הא'. וראה לקו\"ש ח\"ו ע' 49 הערה 16. וש\"נ."],["896","48","להעיר שבב\"מ (וראה גם שאר המקומות) שבהערה 19, מדגיש \"ונעשה נס בשרה אמנו ונפתחו דדי' כשני מעיינות והניקה את כולן\". משא\"כ בפרש\"י עה\"ת שאינו מדגיש שהי' בזה (עוד) \"נס\"."]]],[1301670162,"מובדל מעמו, ולכן פעולת שרה על אוה\"ע שבאה יחד עם לידת יצחק היתה באופן של בדרך ממילא, ריבוי ברכות באוה\"ע.\nושלימות ענין זה תהי' בסוף זמן הגלות בביאת משיח צדקנו, בקיום היעוד<sup data-n=\"897\">49</sup> \"והי' באחרית הימים נכון יהי' הר בית ה' בראש ההרים גו' ונהרו אליו כל הגוים והלכו עמים רבים ואמרו לכו ונעלה אל הר ה' אל בית אלקי יעקב ויורנו מדרכיו ונלכה באורחותיו גו'\"<sup data-n=\"898\">50</sup> — שמצד זה שהגילוי לבנ\"י יהי' בתכלית השלימות ה\"ז ישפיע בדרך ממילא על גוים ועמים רבים<sup data-n=\"899\">51</sup>, עד להמצב ד\"מלאה הארץ דעה את ה' כמים לים מכסים\".\n<span data-k=\"q\">(משיחות ש\"פ חיי שרה וש\"פ תולדות תשמ\"ה; י\"ט כסלו תשמ\"ג)</span>",[["897","49","ישעי' ב, ב ואילך."],["898","50","ראה פרש\"י ישעי' שם, ה."],["899","51","ראה תניא ספל\"ו, \"שאז יזדכך גשמיות הגוף והעולם ויוכלו לקבל גילוי אור ה' שיאיר לישראל כו' ומיתרון ההארה לישראל יגי' חשך האומות גם כן כדכתיב (ישעי' ס, ג) והלכו גוים לאורך וגו' וכתיב (שם ב, ה) בית יעקב וכו'\". ואף שפשטות תוכן הלשון הוא שהגהת חושך האומות היא מיתרון ההארה לישראל, והיינו שבא בדרך ממילא, אולי י\"ל שמרמז בזה לב' האופנים הנ\"ל, שלכן מדייק להביא כמה פסוקים, ומודגש בהלשון שמביא בסופו (מתפלת עמידה דר\"ה) \"והופע בהדר גאון עוזך על כל יושבי תבל\". וראה לקו\"ש חכ\"ג ע' 170 ואילך."]]],[1301670163,"<h3>שיחה א</h3>\nא. כ' החיד\"א בס' מדבר קדמות<sup data-n=\"900\">1</sup> (בשם ר' יהודה החסיד) \"אבות העולם אברהם יצחק ויעקב ראו זה את זה וט\"ו שנים<sup data-n=\"901\">2</sup> למדו התורה [ביחד<sup data-n=\"902\">3</sup>] בכל יום ובכל לילה ט\"ו שעות, ובן<sup data-n=\"903\">4</sup> ט\"ו לתלמוד\" (ומונה כמה ענינים שבמספר ט\"ו).\nומבאר החיד\"א שם החשבון של \"ט\"ו שעות\" (דוקא), כי \"ט' שעות לישן ו­לאכול ולעשות צרכיו וט\"ו לתורה ו­תפלה\", ורמז לזה — \"כל הנשמה תהלל י\"ה<sup data-n=\"904\">5</sup>, שילמוד תורה ויתפלל. . תהלל י\"ה בי\"ה שעות\".\nוהנה בס' חסידים<sup data-n=\"905\">6</sup> איתא: \"ולמה אהב הקב\"ה את האבות מפני שכל היום וכל הלילה לא הי' לבם פונה מלהרהר אחר חפצי שמים. . וייקץ יעקב משנתו<sup data-n=\"906\">7</sup> ו­אמרו חז\"ל<sup data-n=\"907\">8</sup> ויקץ יעקב ממשנתו [דאפילו בשעת השינה הי' עוסק ושונה בתורה<sup data-n=\"908\">9</sup>], כ\"ד פסוקים אברהם יצחק יעקב בפסוק אחד על הסדר. . כי היו כל כ\"ד שעות בסדר אחד שלא הי' להם פנאי מחפצי שמים אפילו בחלום\".\nומבאר החיד\"א בפירושו לספר חסי­דים שם, דלפי זה אי אפשר לומר דהא דנקט ר\"י החסיד ש\"למדו התורה. . (רק) ט\"ו שעות\" הוא לפי שבשאר ט' השעות היו עוסקים בצרכי הגוף (כמ\"ש במדבר קדמות שם), שהרי \"רבינו בעצמו כתב דכל כ\"ד שעות אפילו בחלום היו ב­חפצי שמים\", אלא \"ר\"ל כי ט\"ו שעות היו לומדים תורה וט' שעות מכוונים לבם למקום לחשוב ביראתו ורוממותו ואהבתו ודבוקו\" [היינו העסק בתפלה, וכמחז\"ל<sup data-n=\"909\">10</sup> דחסידים הראשונים היו עוס­קים בתפלה וכוונתה ט' שעות ביום].\nויש להוסיף, דפירוש זה (דמספר \"ט\"ו שעות\" קאי רק על לימוד התורה) מוכרח לכאורה בדברי ר\"י החסיד גופא (ש­הביא החיד\"א), שכ' \"וט\"ו שנים למדו התורה. . ט\"ו שעות ובן ט\"ו לתלמוד\", שמזה משמע, דאין שעות עבודת התפלה בכלל חשבון זה<sup data-n=\"910\">11</sup>.\nוצריך ביאור:\nמזה שהאבות \"ראו זה את זה\" רק ט\"ו שנים, כמ\"ש ר\"י החסיד ד\"ט\"ו שנים למדו כו' ט\"ו שעות\" [כי לידת יצחק היתה בהיות אברהם אבינו בן מאה שנה<sup data-n=\"911\">12</sup>, ויעקב נולד כשיצחק הי' בן",[["900","1","בתחלתו (מ\"קונטרס ישן כתיבת יד על קלף מתלמידי רבינו יהודה החסיד\"). וראה הנסמן בהערה הבאה."],["901","2","השנים שהיו האבות יחד ו\"ראו זה את זה\" (כדלקמן בפנים). ואולי יש כאן טה\"ד וצ\"ל \"ראו זה את זה ט\"ו שנים ולמדו. . \". — וראה גם מ\"ש החיד\"א בחומת אנך ס\"פ נשא ומגילת רות (אות יד). פני דוד פ' נח (אות ו). יוסף תהלות לתהלים מזמור קכ. ועוד."],["902","3","בחומת אנך רות שם \"ועבדו את ה' במיטב תלתא כחדא\"."],["903","4","אבות ספ\"ה."],["904","5","תהלים קנ בסופו."],["905","6","סי' קסה."],["906","7","ויצא כח, טז."],["907","8","ב\"ר פס\"ט, ז."],["908","9","ראה יפ\"ת השלם לב\"ר שם. עץ יוסף שם."],["909","10","ברכות לב, ב."],["910","11","ולהעיר די\"ה הם כנגד חו\"ב, מוחין (תניא אגה\"ת פ\"ד (צד, ב). לקו\"ת ר\"פ ראה. ובכ\"מ). — אבל ראה לקמן סעיף ה והנסמן בהערה 31."],["911","12","וירא כא, ה."]]],[1301670164,"ששים שנה<sup data-n=\"912\">13</sup>, שאז הי' אברהם בן מאה וששים שנה, ושני חיי אברהם היו קע\"ה<sup data-n=\"913\">14</sup>, הרי שרק ט\"ו<sup data-n=\"914\">15</sup> שנה (שבסוף חיי אברהם) היו כל ג' האבות יחד] — מובן, שיש עילוי מיוחד בט\"ו שעות אלו ש­למדו תורה ביחד (כנגד ט\"ו שנים שראו זה את זה) לגבי שאר שעות היום.\nוהנה לפי ביאורו של החיד\"א במדבר קדמות, שט\"ו שעות הן שעות של תורה ותפלה וט' השעות הנשארות היו לצרכי הגוף, מובן העילוי שבט\"ו שעות אלו. דאע\"פ שזה פשוט שגם צרכיהם הגש­מיים של האבות נעשו לשם שמים ב­תכלית השלימות [וכמ\"ש אדמו\"ר הזקן בס' התניא<sup data-n=\"915\">16</sup> \"שהאבות. . כל ימיהם לעולם לא הפסיקו אפילו שעה אחת מלקשר דעתם ונשמתם לרבון העולמים\", ובמ\"א<sup data-n=\"916\">17</sup> מפרט ומפרש שהיו \"בחי' מרכ­בה בכל מעשיהם אפילו בשינתם\"], מ\"מ, אין זה בערך להעילוי דעסק התורה והתפלה עצמו.\nאבל לביאורו בפירושו לס' חסידים, דט' השעות הנשארות הן זמן עסק התפלה, אינו מובן, למה ישתנו וכ\"כ ט\"ו השעות דלימוד התורה מט' השעות דעסק התפלה, עד שלכן \"ראו זה את זה\" רק ט\"ו שנים (כמספר ט\"ו שעות היום והלילה שלמדו תורה ביחד)?\nב. ויש לומר הביאור בזה ע\"ד ה­חסידות:\nידוע<sup data-n=\"917\">18</sup>, שג' האבות אברהם יצחק ו­יעקב הם כנגד ג' העמודים שעליהם העולם עומד<sup data-n=\"918\">19</sup>, תורה עבודה וגמילות חסדים: עיקר עבודת אברהם הי' גמילות חסדים, יצחק — עבודה (וכמחז\"ל<sup data-n=\"919\">20</sup> ש­יצחק הי' \"עולה תמימה\"), ויעקב ענינו תורה, כמ\"ש<sup data-n=\"920\">21</sup> \"ויעקב איש תם יושב אהלים\". וכך הם מחולקים בעבודת ה­מדות, דמדת אברהם היא מדת החסד וה­אהבה, מדתו של יצחק — גבורה ויראה, ושל יעקב — תפארת ורחמים.\nולפי זה, זה שהאבות \"ראו זה את זה\" והיו ביחד ט\"ו שנים, מורה על חיבור כולם יחד, דאע\"פ שכל אחד משלשת אופנים אלו בעבודה מחולק מחבירו, נתחברו ג' האבות יחד לעבוד את ה', שאין זו התחברות גשמית לבד, אלא התחברות אופני עבודת ה' יחד.\nולכן היתה התחברותם רק בנוגע ללימוד התורה, כי התחברות זו של ג' עבודות מחולקות יחד, היא רק בדרגא דלימוד התורה, כפי שהענינים והעבו­דות הם בדרגת התורה<sup data-n=\"921\">22</sup>, שבה \"אלו<sup data-n=\"922\">23</sup> ואלו דברי אלקים חיים\"; משא\"כ בעבו­דה בפועל, בעבודת המדות, וכ\"ש וק\"ו במעשה בפועל, אי אפשר שתהי' הש­תוות כל סוגי ואופני עבודה אלו.\nוזהו גם טעם החילוק, דזה שהאבות למדו תורה ביחד ט\"ו שעות ביום, בא",[["912","13","פרשתנו כה, כו."],["913","14","ח\"ש כה, ז."],["914","15","להעיר מהשקו\"ט ממחז\"ל (ב\"ר פס\"ג, י. פרש\"י פרשתנו כה, כז) דבן י\"ג שנה פירש עשו לע\"ז — ראה דעת זקנים מבעה\"ת וריב\"א עה\"ת שם. ועוד. וראה לקו\"ש ח\"א ע' 49. ח\"ה ע' 369 ואילך. ואכ\"מ."],["915","16","רפל\"ד. וראה שם פכ\"ג (כח, ב)."],["916","17","מאמרי אדה\"ז הקצרים ע' תקמ."],["917","18","זהר (ס\"ת) ר\"פ ויצא. מגלה עמוקות אופן רנ (בסופו). מגלה עמוקות עה\"ת ר\"פ לך. ועוד."],["918","19","אבות פ\"א מ\"ב."],["919","20","ב\"ר פס\"ד, ג. רש\"י פרשתנו כה, כו. שם כו, ב."],["920","21","פרשתנו כה, כז. ב\"ר (פס\"ג, י) ופרש\"י עה\"פ."],["921","22","ובעבודת האדם — מצד דרגת המוחין (י\"ה), כדלקמן ס\"ג. — וראה גם לקו\"ש ח\"כ ע' 126."],["922","23","עירובין יג, ב."]]],[1301670165,"לידי ביטוי בחיי האבות בגשמיות, שחיו יחד ט\"ו שנה, ואילו זה שעבדו את ה' כל כ\"ד שעות היום נרמז רק בכך שיש \"כ\"ד פסוקים אברהם יצחק יעקב בפסוק אחד על הסדר\" — כי ענין התחברות (עבודת) ג' האבות יחד בהדרגא של לימוד תורה היתה בפועל; משא\"כ התחברותם יחד בעבודת ה' במשך כל כ\"ד שעות היום, היא רק כפי שהיא בתורה (\"כ\"ד פסוקים אברהם יצחק יעקב בפסוק אחד על הסדר\"), אבל במעשה בפועל, זה שעבדו השם כ\"ד שעות היום, הרי אין עבודת אחד מהם דומה לחבירו כו'<sup data-n=\"923\">24</sup>.\nג. הסברת הענין:\nתורה, גם כשניתנה למטה, הרי היא חכמתו ית' כמו שהיא למעלה, וכשם שאצלו ית', הרי כל המדות ישכנו יחד באחדות גמורה, דכולם הם פרט בגילוי שלימותו ית', והוא \"כוללם יחד\", הנה עד\"ז בתורתו ית', שאין סתירה בין כל סוגי עבודה, דחכמתו ית' מחייבת את כולם (אלו ואלו דא\"ח); משא\"כ בעבודה בפועל, מצד האדם, דכל נברא הוא מצי­אות, הרי כל עבודה (ומדה) אחרת ה\"ה מנוגדת לחברתה, ולכן יש סתירה בין סוגי העבודה.\nוכן הוא גם מצד האדם גופא, דב­מוחין שבאדם אין התחלקות כ\"כ כמו במדות שבלב. וכפי שרואים, דקשה ל­אדם להרגיש קירוב (אהבה) וריחוק (יר­אה) לדבר אחד בבת אחת, משא\"כ מצד המוחין, אפשר שאדם אחד ישיג בבת אחת סברות הפוכות בענין אחד, הן ה­סברות לחיוב והן הסברות לזכות. וכן בעבודה, דכאשר האדם עסוק בהבנת חילוקי אופני העבודה, אפשר שיהי' \"מונח\" בשכלו הבנת עבודות מחולקות זמ\"ז בתכלית, אך כשבא לידי מעשה הרי הוא מוגבל בקו אחד דוקא.\nובדקות יותר:\nידוע שמוחין נקראים \"אין\" לגבי ה­מדות שהן \"יש\", והיינו לפי שענין השכל הוא — תפיסת והשגת המושכל כמו שהוא לאמיתתו, בלי תערובת מציאות ומצב האדם המשיג, משא\"כ תוכן ענין המדות הוא להיפך — התייחסותו אל הדבר שמחוץ הימנו, היינו פעולת הדבר על האדם המרגיש, אם להתקרב אליו (אהבה) או להתרחק ממנו (יראה).\nוכן הוא בעבודת השם: עבודת ה­מדות היא — רגש האדם, שהוא אוהב את השם לפי ש\"קרבת אלקים לי טוב\"<sup data-n=\"924\">25</sup>, ולכן רוצה להתקרב אליו ית' (ועד\"ז ב­יראה וכיו\"ב); משא\"כ עבודת המוחין היא מה ש\"יוצא\" מגדרי מציאות עצמו ותופס ומשיג חכמתו ית' כמו שהיא.\nולכן, במדות האדם הקשורות עם \"מציאותו\", ישנו ענין ההתחלקות בתוקף, משא\"כ במוחין, שבהם משיג האדם כפי אשר חייבה חכמתו ית', אפשר להיות התחברות כל סוגי עבודות יחד.\nד. ויש לומר, דזה שהתחברות העבו­דות דג' האבות יחד היא רק בלימוד התורה שלהם (מוחין), הוא לפי שהם היו קודם מ\"ת, לפני ביטול הגזירה בין \"עליונים\" ו\"תחתונים\", כמבואר במדרש<sup data-n=\"925\">26</sup> דקודם מ\"ת היתה גזירה ד\"השמים שמים לה' והארץ נתן לבני אדם\"<sup data-n=\"926\">27</sup>, דעליונים",[["923","24","להעיר מהמבואר במ\"א (לקו\"ש ח\"ה ע' 373 ואילך), שהנהגת יצחק ויעקב בחיי אברהם (בפעו­לתם בעולם) היתה בקו של עבודת אברהם. ע\"ש. ואכ\"מ."],["924","25","תהלים עג, כח."],["925","26","תנחומא וארא טו. שמו\"ר פי\"ב, ג."],["926","27","תהלים קטו, טז."]]],[1301670166,"לא ירדו לתחתונים ותחתונים לא יעלו לעליונים, ובעת מ\"ת נתבטלה הגזירה וניתנה האפשרות לחבר \"עליונים\" ו\"תח­תונים\", אלקות עם גשמיות העולם.\nוכשם שישנו ענין ביטול ה\"גזירה\" בכללות העולם, כך ישנו גם באדם גו­פא, ולא רק בין נפשו וגופו (רוחניות וגשמיות שבו), אלא גם בנפש האדם גופא:\nעבודת המוחין, הבנה והשגה, שבה מאירה האמת כפי שהיא מצד חכמתו ית', היא בחי' \"עליונים\" שבאדם; ועבו­דת המדות, רגש האדם, הקשורה עם מציאותו, היא בחי' \"תחתונים\" (בנפשו גופא).\nוזהו ענין \"ביטול הגזירה\" בנפש האדם: קודם מ\"ת לא הי' אפשר להיות החיבור האמיתי בין \"מוחין\" ו\"מדות\", שה\"ביטול\" שמצד עבודת המוחין יומשך ויורגש גם במדות האדם; ורק לאחרי ביטול הגזירה דמ\"ת ניתן הכח, שאותו הביטול שבמוחין, שמצד ביטול זה אפשר להיות התחברות והתכללות עבו­דות הפכיות (כנ\"ל), יומשך גם במדות, באופן שגם בעבודה בפועל יוכל לעבוד את ה' בכל סוגי העבודות (וכדאיתא בספרי עה\"פ<sup data-n=\"927\">28</sup> ואהבת את ה\"א, שנדרש מאדם הן אהבה והן יראה, אע\"פ \"שאין לך אהבה במקום יראה ויראה במקום אהבה אלא במדת הקב\"ה בלבד\", זאת אומרת, שניתן לאדם הכח לחבר ב' הפכים דאהבה ויראה יחד, \"אהבה ב­מקום יראה ויראה במקום אהבה\").\nה. ועפ\"ז יש לבאר בעומק יותר החי­לוק בין שני הביאורים שבחיד\"א — אם ט' השעות הן השעות של העסק בצרכי הגוף או שהן השעות דעבודת התפלה — שהם שני אופנים בעבודת האבות, אם כללות עבודתם (הן בנפש והן בגוף), או רק עבודה רוחנית שלהם (עבודת הנפש עצמה):\nהביאור הא' שהט' שעות הן השעות דצרכי הגוף, קאי בכללות עבודת ה­אבות, דזה שעבודת האבות (יחד) היתה רק ט\"ו שעות ביום, הוא לפי שלהיותם קודם מ\"ת, לכן היתה עיקר עבודתם רק ברוחניות ולא בגשמיות (כמבואר ב­כ\"מ<sup data-n=\"928\">29</sup>). דאע\"פ שזה פשוט (כנ\"ל) שגם צרכי הגוף שלהם נעשו בתכלית השלי­מות (עד לביטול ד\"מרכבה\"), מ\"מ, אין זה בערך כלל לדרגת עבודתם מצד הרוחניות שלהם, שדביקותם העצומה בה' מצד רוחניותם, לא היתה יכולה להיות נמשכת בגלוי ובפועל בגשמיות שלהם. וזהו ש\"למדו התורה בכל יום. . (רק) ט\"ו שעות\", שלביאור זה היינו תורה ותפלה (כנ\"ל ס\"א), שהיא העבודה ה­רוחנית דהאבות, \"דחילו ורחימו דבמוחא ולבא\"<sup data-n=\"929\">30</sup> (וכידוע<sup data-n=\"930\">31</sup> שהם בחי' י\"ה (ט\"ו) שבשם);\nמשא\"כ הביאור השני שט' השעות ה­נשארות הן השעות דעבודת התפלה, קאי בעבודה רוחנית עצמה דהאבות, שהחי­לוק בין עליון ותחתון הוא \"מוח\" ו\"לב\", תורה ותפילה, וההתחברות דכל האבות יחד היא רק בדרגא דמוחין ולא במדות שבלב, וכנ\"ל באורך.\nו. והנה פ' תולדות (שבה מסופר ע\"ד התחלת חיי יעקב, שהוא הזמן שבו",[["927","28","ואתחנן ו, ה."],["928","29","ראה ספר הערכים­חב\"ד מע' אבות סעיף ד. וש\"נ."],["929","30","הנק' \"הנסתרות\" (רע\"מ נשא קכג, ריש ע\"ב. ת\"ז ת\"י (כה, ב). ת\"ע (קכט, א). ועוד. וכ\"ה בתניא בהקדמה. שם ר\"פ מד)."],["930","31","ת\"ז ריש תכ\"ב. ת\"ע שם."]]],[1301670167,"האבות \"ראו זה את זה\"<sup data-n=\"931\">32</sup>) חלה בתחלת חודש כסלו או בשבת מברכים החודש כסלו — החודש השייך (במיוחד) לגילוי תורת החסידות, וכידוע<sup data-n=\"932\">33</sup> שחודש סיון, ירחא תליתאי<sup data-n=\"933\">34</sup> לחדשי הקיץ הוא זמן גילוי תורת הנגלה, וחודש כסלו, ירחא תליתאי לחדשי החורף שייך לגילוי תורת החסידות\n[עד שבחודש זה ישנם כמה ימים מיו­חדים בדברי ימי החסידות, כמו: הילולא דהרב המגיד (י\"ט כסלו); חג הגאולה של אדמו\"ר הזקן (י\"ט כסלו) ואדמו\"ר האמצעי (יו\"ד כסלו); יום הולדת ויום ההילולא של אדמו\"ר האמצעי (ט' כסלו) ועוד. וכן ימי חנוכה שבסיום החודש, שייכים ג\"כ לפנימיות התורה, שעיקר נס חנוכה הוא נס פך השמן, והרי \"שמן\" שבתורה הם רזי רזין דאורייתא<sup data-n=\"934\">35</sup>].\nוכאן רואים דבר פלא, דכשם שאבות העולם, אברהם יצחק ויעקב, היו יחד בעלמא דין ט\"ו שנה — כך הוא אצל \"אבות החסידות\", הבעש\"ט והמגיד ו­אדמו\"ר הזקן<sup data-n=\"935\">36</sup>, שהיו בעלמא דין יחד ט\"ו שנה (כי רבינו הזקן נולד בשנת תק\"ה (קה\"ת), והסתלקות הבעש\"ט היתה בשנת תק\"כ).\nויש להוסיף עוד פלא:\nנזכר לעיל שבאבות היו שני ענינים — הט\"ו שעות שלמדו תורה (הנרמז בט\"ו שנה שראו זה את זה), וזה שעבדו את ה' כל כ\"ד שעות היום (הנרמז ב\"כ\"ד פסו­קים (שנאמר) אברהם יצחק ויעקב ב­פסוק אחד על הסדר\"),\nודוגמתו מצינו ב\"אבות החסידות\" — שהאבות של חסידות הכללית היו ביחד בעולם הזה ט\"ו שנה (כנ\"ל); ואילו ה­\"אבות\" של תורת חסידות חב\"ד, אדמו\"ר הזקן<sup data-n=\"936\">37</sup> ואדמו\"ר האמצעי ואדמו\"ר הצ\"צ, היו ביחד בעולם הזה כ\"ד שנה (כי אדמו\"ר הצ\"צ נולד בשנת תקמ\"ט, ו­הסתלקות אדמו\"ר הזקן היתה בשנת תקע\"ג).\nוע\"פ משנת\"ל בענין עבודת האבות (קודם מ\"ת), יש לבאר גם תוכן הענין, ובהקדם דברי אדמו\"ר (מהורש\"ב) נ\"ע<sup data-n=\"937\">38</sup> בביאור סדר התגלות תורת החסידות, דכשם שקודם מ\"ת הי' צ\"ל ההקדמה דעבודת האבות, בעבודה רוחנית, אך \"מ\"מ אין זה המשכת התורה ממש. . ואח\"כ ניתנה התורה במ\"ת בהתלבשות שבזה נמשך בחי' העצמות. . התורה שנתלבשה בענינים שלמטה נמשך בזה העצמות\" — כך הוא בהתגלות תורת החסידות, דתחילה היתה \"התגלות ה­בעש\"ט [והרב המגיד]. . התגלות פני­מיות התורה. . שלא בבחי' התלבשות. . ולא הי' העולם יכול לקבל, והי'",[["931","32","אף שסיפור הסתלקות אברהם הוא בס\"פ ח\"ש (כה, ז ואילך)."],["932","33","ראה שיחת י\"ט כסלו (ליל ב') תרפ\"ט. לקוטי לוי\"צ — אגרות (ע' ריז). ועוד."],["933","34","שבת פח, א."],["934","35","אמרי בינה שער הק\"ש פנ\"ד ואילך. ועוד."],["935","36","ראה לקוטי דיבורים ח\"א (לו, א­ב), שה­בעש\"ט והמגיד ואדה\"ז הם כח\"ב (כתר חכמה בינה) דתורת החסידות. — וראה הערה הבאה והערה 40."],["936","37","דשני ענינים באדמו\"ר הזקן — א' מנשיאי תורת החסידות הכללית, ומייסד תורת חסידות חב\"ד. ויש לומר, שזהו החילוק בין שני האופנים בדרגות הנשיאים בספירות: (א) הבעש\"ט, הה\"מ ואדה\"ז — כח\"ב (כנ\"ל מלקו\"ד. וראה שם לז, א), (ב) הבעש\"ט והה\"מ — כתר (עתיק ואריך), אדה\"ז — חכמה, אדמו\"ר האמצעי — בינה, והצ\"צ — דעת (סה\"ש תש\"ב ע' 19. תש\"ה ע' 60)."],["937","38","י\"ט כסלו עטר\"ת (נדפס בסה\"מ עטר\"ת (קה\"ת, תשמ\"ח) ע' תרעג). הובא ונת' בד\"ה פדה ב­שלום תרפ\"ה (סה\"מ תרפ\"ה ע' עט)."]]],[1301670168,"עבודה נעלית וגבוה מאד אבל אין זה התגלות עצם פנימיות התורה, ובא ע\"י רבינו נ\"ע בהתלבשות בהשגה ובזה נמשך בחי' העצם כו'\".\nונת' הענין בכ\"מ<sup data-n=\"938\">39</sup>, שזהו עיקר החי­דוש דתורת חסידות חב\"ד, שע\"י שהעני­נים של תורת החסידות נתבארו בתורת חב\"ד באופן שהם מושגים בשכלו והב­נתו של האדם, עי\"ז נמשך אור החסידות בפנימיותו, בבירור וזיכוך נפשו הבהמית וחלקו בעולם, עד שחודר בכל עניניו, גם בעניניו הגשמיים [ע\"ד החידוש דמ\"ת, חיבור עליונים ותחתונים].\nוזה נרמז בכך, שהאבות של חסידות הכללית היו ביחד ט\"ו שנים, ואילו האבות של חסידות חב\"ד היו ביחד כ\"ד שנה:\nתורת החסידות הכללית, שהיא \"הת­גלות שלא בבחי' התלבשות\", בבחי' מקיף<sup data-n=\"939\">40</sup>, היא בעיקר עבודה רוחנית (ע\"ד עבודת האבות קודם מ\"ת), \"דחילו ו­רחימו דבמוחא ולבא\", בחי' י\"ה (ט\"ו) שבנפש;\nמשא\"כ על ידי חסידות חב\"ד נמשך אור החסידות בכל חלקי האדם (וכפתגם כ\"ק מו\"ח אדמו\"ר<sup data-n=\"940\">41</sup> שגם העקב שברגל יהי' \"אַ חסידישע פּיאַטע\"), ועד שחודר בכל עניניו, גם בעניניו הגשמיים (כנ\"ל) — ועי\"ז ניתן הכח לחיות חיי חסידות במשך כל כ\"ד שעות היממה, עד שאפילו בעת השינה<sup data-n=\"941\">42</sup> יהי' ניכר עליו \"אַז עס שלאָפט אַ חסיד\".\nוכן הוא בנוגע ל\"ציור קומה\" הכללי של כללות ישראל במשך כל הדורות, שע\"י תורת חסידות חב\"ד נמשך הכח שאור החסידות יחדור גם את החשך דדרא דעקבתא דמשיחא, בחי' רגלים ועקביים דוקא<sup data-n=\"942\">43</sup>,\nועי\"ז זוכים ל\"והי' עקב תשמעון גו' ושמר ה\"א לך את הברית גו'\"<sup data-n=\"943\">44</sup>, דכאשר גם בבחי' \"עקב\", דרא דעקבתא דמשי­חא<sup data-n=\"944\">45</sup>, ישנו ה\"תשמעון\" — מקיים הקב\"ה \"את הברית ואת החסד אשר נשבע לאבותיך\", גאולה האמיתית והשלימה ע\"י משיח צדקנו, ותיכף ומיד ממש.\n<span data-k=\"q\">(משיחת י\"ט כסלו תשכ\"ב)</span>",[["938","39","ראה סד\"ה פדה בשלום הנ\"ל. ובכ\"מ."],["939","40","להעיר מלקו\"ד שם, דזה שהבעש\"ט והמגיד ואדה\"ז הם כח\"ב דחסידות הוא ב\"כללות הגילוי מלמעלה. . סדר התגלות תורת החסידות בדרך מלמעלה למטה\". ע\"ש."],["940","41","ראה אגרות קודש אדמו\"ר מהוריי\"צ ח\"ג ע' תקסח ואילך (\"התמים\" ח\"ו ע' נב­ג). וראה ס' השיחות תש\"ב ע' 43 ואילך. סה\"מ תש\"ח ע' 253 ואילך."],["941","42","ראה רד\"ה זה היום תרפ\"ו. ועוד. — ולהעיר מרמב\"ם הל' דעות ספ\"ג \"נמצאת שינה שלו עבודה למקום ב\"ה\", אף שלקמן שם (רפ\"ה), במנין עשרה הדברים שבהם צריך שיהי' החכם ניכר, לא מנה ענין השינה. ונת' במ\"א. ואכ\"מ."],["942","43","ראה אגרות קודש וסה\"ש שנסמנו בהערה 41."],["943","44","ל' הכתוב ר\"פ עקב."],["944","45","אוה\"ת ר\"פ עקב. ועוד."]]],[1301670169,"<h3>שיחה ב<sup data-n=\"945\">*</sup></h3>\nא. תנן בסוף קידושין<sup data-n=\"946\">1</sup>: \"מצינו שעשה אברהם אבינו את כל התורה כולה עד שלא ניתנה שנאמר<sup data-n=\"947\">2</sup> עקב אשר שמע אבר­הם בקולי וישמור משמרתי מצותי חוקותי ותורותי\".\nוביומא<sup data-n=\"948\">3</sup> גרסינן: אמר רב קיים אברהם אבינו כל התורה כולה שנאמר עקב אשר שמע אברהם בקולי וגו' (ופריך: ואימא שבע מצות, הא איכא נמי מילה וכו').\nוכבר הקשו<sup data-n=\"949\">4</sup>, דמאחר שהיא משנה שלימה בסוף קידושין שעשה אברהם כל התורה כולה, מאי אתא רב לאשמעינן ב­מאמרו במס' יומא<sup data-n=\"950\">5</sup>? (ועוד: אדפריך הכא אמילתא דרב \"ואימא ז' מצות\", לפרוך אמתני' דקידושין?)\nותי' במהרש\"א<sup data-n=\"949\">4</sup>, דבמשנה נקט \"שעשה<sup data-n=\"952\">6</sup> אברהם אבינו\", ד\"לא משמע אלא שעשה כל המצות, והיינו העשין, אבל לישנא דרב קיים כל התורה משמע נמי אלאוין של התורה\" (ולכן פריך ארב \"ואימא שבע מצות\").\nוצ\"ע, דאע\"פ שלשון המשנה היא \"עשה\n.. את כל התורה\", למה תיסק אדעתין שאברהם קיים רק העשין ולא נשמר מלעבור אלאווין? והרי בוודאי השתדל אברהם לקיים כל התורה כולה עד כמה שהי' אפשר לו<sup data-n=\"953\">7</sup> (ובפרט לפי גירסת ה­משנה שלפנינו<sup data-n=\"954\">8</sup> — \"עשה אברהם אבינו את כל התורה כולה\").\n[וזה שלא מקשה הש\"ס בסוף קידושין \"ואימא ז' מצות\" כמו שמקשה ביומא אדרב, י\"ל בפשטות, כי בקידושין אין זה עיקר מקומו של ענין זה (קיום התומ\"צ של אברהם), והובא במשנה רק כתוס' ראי' על פעולתה של התורה \"בעת זקנותו\" (לאחרי הראי' הא' \"(בנערותו מהו אומר<sup data-n=\"955\">9</sup> וקוי ה' יחליפו כח) בזקנותו מהו אומר<sup data-n=\"956\">10</sup> עוד ינו­בון בשיבה\". ולהעיר, דבברייתא שם<sup data-n=\"957\">11</sup>",[["945","*","וסיום מס' קידושין."],["946","1","פב, א."],["947","2","פרשתנו כו, ה."],["948","3","כח, ב."],["949","4","חדא\"ג יומא שם ד\"ה קיים. ובכ\"מ. וראה הנסמן על גליון המשניות."],["950","5","כמה ראשונים (תוס' ר\"י הזקן (הובא בפתח עינים להחיד\"א סוף קידושין). תוס' הרא\"ש. תוס' טוך) כתבו, דסיום המשנה \"מצינו שעשה כו'\" אינו מן המשנה אלא ברייתא היא, אלא דבפתח עינים (מתוס' ר\"י הזקן) ובתוס' טוך שהוא לא רק בנוגע לסיום המשנה, \"וכן כתוב בספרים ישנים דלעולם ילמד אדם אומנות נקי' ברייתא היא\". וראה שינויי נוסחאות למשניות ובהמובא בגליון הש\"ס מ\"פי' הקונט'\" סוף קנים. וישנו בכמה גירסאות וכן בגירסת המאירי. וראה בית דוד למשניות כאן."],["949","4","חדא\"ג יומא שם ד\"ה קיים. ובכ\"מ. וראה הנסמן על גליון המשניות."],["952","6","י\"ג גם במשנה קידושין \"קיים\", כהובא על הגליון בש\"ס ובמשניות. וכ\"ה במאירי, יש\"ש, ופתח עינים קידושין שם."],["953","7","בגו\"א על פרש\"י ויגש (מו, יוד קרוב לסופו) האריך בזה, דשאר האבות (והשבטים כו') קיימו רק מ\"ע ולא ל\"ת (ורק אברהם קיים כל המצות). וראה שם בארוכה הטעם שהיו מקיימין רק מצות עשה.\nאבל לכאורה מצינו בכ\"מ איפכא, ובל' התוס' (ב\"ב טז, ב ד\"ה בא) \"דאע\"פ שלא נצטוו מכל מקום מכוער הדבר\" (ושם כ' זה אפילו בנוגע לעשו). ועד\"ז הוא בכמה מקומות לגבי האבות שהיו נזהרים מלעבור אל\"ת."],["954","8","ראה שינויי נוסחאות למשניות."],["955","9","ישעי' מ, לא."],["956","10","תהלים צב, טו."],["957","11","בסיום המס' (פב, ב). אבל בירושלמי שם הובאה ראי' זו (בסגנון אחר קצת) גם בברייתא."]]],[1301670170,"הובאה רק הראי' הא' ולא הביא הראי' מאברהם)]<sup data-n=\"958\">12</sup>.\nבפשטות יש לומר, שהחידוש במאמר רב על המשנה הוא, שבמשנה קאי רק ב­לימוד התורה דאברהם, משא\"כ רב מחדש שהי' אצלו גם קיום כל המצוות.\nוכן מובן גם מהמשך הענינים, דבמשנה הובא זה בסיום מאמר ר' נהוראי<sup data-n=\"959\">13</sup> \"מניח אני כל אומנות שבעולם ואיני מלמד את בני אלא תורה, שאדם אוכל משכרה בעולם הזה והקרן קיימת לו לעולם הבא ושאר כל אומנות אינו כן כשאדם בא לידי חולי או לידי זקנה או לידי יסורין ואינו יכול לעסוק במלאכתו הרי הוא מת ברעב אבל התורה אינה כן כו' וכן הוא אומר באברהם אבינו ואברהם<sup data-n=\"960\">14</sup> זקן וה' ברך את אברהם בכל מצינו שעשה אברהם אבינו את כל התורה כולה עד שלא ניתנה כו'\" — והיינו שמדובר בענין לימוד התורה; משא\"כ מאמרו של רב ביומא בא בהמשך להמבואר שם לפנ\"ז דאברהם זקן ויושב בישיבה הי' (ומימיהן של אבותינו לא פרשה ישיבה מהם כו'), שע\"ז מביא הש\"ס מאמר רב, דנוסף לזה שאברהם למד תורה, הרי עוד זאת, קיים אברהם אבינו כל התורה כולה (וע\"ז מקשה הש\"ס מנין שקיים אברהם אבינו המצות כו').\nאבל אף שפירוש זה מתיישב היטב בלשון רב \"קיים אברהם אבינו\", מ\"מ קשה לפרש לשון המשנה (בקידושין) \"עשה אברהם אבינו את כל התורה כולה\" דקאי על לימוד התורה בלבד ולא על עשיית המצות בפועל. והרי מביא ראי' מהכתוב \"עקב אשר שמע אברהם בקולי וישמור משמרתי מצותי חוקותי ותורותי\", שמ­פורש בו<sup data-n=\"961\">15</sup> שמירת ועשיית המצוות<sup data-n=\"962\">16</sup>.\nב. יש מפרשים<sup data-n=\"963\">17</sup>, דמתני' משמע ש­עשה אברהם כן מדעתו (וכמודגש במשנה \"עשה אברהם אבינו את כל התורה כולה עד שלא ניתנה\"), אבל רב נקט \"קיים\", דמשמע שנצטווה על כך וקיים הציווי, ודייק לה מדכתיב אשר שמע אברהם בקולי ומשמע שה' צוה לו כך.\nוכן משמע בפרש\"י ביומא שם<sup data-n=\"964\">18</sup>: על קושיית הש\"ס על מאמר רב \"ואימא שבע מצות\" פרש\"י \"ז' מצות שנצטוו לשאר כל בני נח, אבל תורה לא ניתנה לו\" — \"ש\"מ<sup data-n=\"963\">17</sup> דמפרש דברי רב שקיים אברהם את התו­רה לאחר שניתנה (ועלי' קאי קושיית רב שימי)\".\nאבל לכאורה חידוש גדול הוא לומר דרב ס\"ל שאברהם נצטווה על קיום כל התורה, וכמו שהקשה החיד\"א<sup data-n=\"966\">19</sup>, ד\"ליכא למ\"ד שאברהם אבינו ע\"ה נצטווה יותר מהמילה וז' מצות, אלא הוא מעצמו סביר וקביל\".\nג. ונ\"ל בזה, ובהקדם דבגדר תורה ומצות בימי האבות לפני שניתנה<sup data-n=\"967\">20</sup> יש",[["958","12","וראה מה שהקשה עוד על דברי המהרש\"א בשירי קרבן לירושלמי סוף קידושין."],["959","13","ואף את\"ל דלשון זו אינה מדברי ר\"נ עצמו (וראה לעיל הערה 5), ה\"ז בהמשך לדבריו."],["960","14","ח\"ש כד, א (בהשמטת תיבות)."],["961","15","ואולי זהו טעם הגירסא שהביא במלאכת שלמה סוף קידושין שהובא רק \"עקב אשר שמע אברהם בקולי\"."],["962","16","בירושלמי כאן \"ששימר את התורה\", ועד\"ז איתא בכמה דרז\"ל, ובכ\"מ \"קיים\", \"עשה אותה ושמר אותה\", \"עשה אותה ודקדק בה\", ועוד — ראה תו\"ש פרשתנו עה\"פ אות כח. וש\"נ."],["963","17","שירי קרבן לירושלמי סוף קידושין."],["964","18","ד\"ה שבע מצות."],["963","17","שירי קרבן לירושלמי סוף קידושין."],["966","19","פתח עינים שם. כסא רחמים לאבות דר\"נ (ב\"תוספות\") פל\"ג בתחלתו."],["967","20","בגדר האבות וקיום המצות שלהם כבר האריכו במפרשים. וראה פרשת דרכים דרך האתרים דרוש ג. בית האוצר להר\"י ענגיל בתחלתו. ועוד."]]],[1301670171,"לבאר בשני אופנים<sup data-n=\"968\">21</sup>: א) דישנה החפצא דתורה ומצוות (שהרי אלפיים שנה קדמה תורה לעולם<sup data-n=\"969\">22</sup>), אלא שעדיין לא הי' ציווי להגברא (כיון שעדיין לא ניתנה למטה), ולפ\"ז קיום המצות לפני מ\"ת הוי בגדר אינו מצווה ועושה (שמצינו לאחרי מ\"ת), דישנן לתורה ומצוות אלא שהגברא אינו מצווה עליהן; ב) לפני מ\"ת ליכא החפצא דתורה ומצות בעולם, דלא רק שלא הי' ציווי להגברא, אלא שהחפצא נתחדשה (בעולם) בשעת מ\"ת<sup data-n=\"970\">23</sup>.\nויש לומר, שזהו החידוש במאמר רב על מאמר המשנה:\nבמאמר המשנה, שמדייק \"שעשה אבר­הם אבינו את כל התורה כולה עד שלא ניתנה\", כוונתו שלפני מ\"ת לא חל על פעולת התומ\"צ דהאבות גדר של קיום מצוה, אלא מעשה סתם, כיון שכל החפצא נתחדשה בשעת מ\"ת<sup data-n=\"971\">24</sup>;\nואילו רב מחדש שקיים אברהם אבינו כל התורה כולה, דאף שהתורה לא ניתנה עדיין, מ\"מ ישנה להחפצא דתורה ומצות, אלא שלא נצטווה לקיימן, ושפיר יוכל לחול על מעשה אברהם שם \"קיום\" מצוה<sup data-n=\"972\">25</sup> [וע\"ד נשים בקיום מ\"ע שהזמן גרמא, שאף שאינן מצוות עליהן<sup data-n=\"973\">26</sup>, מ\"מ יכולין לקיי­מן<sup data-n=\"974\">27</sup> ונחשב לקיום מצוה, וקיי\"ל<sup data-n=\"975\">28</sup> כהדי­עות שנשים יכולות לברך על קיום מ\"ע שהזמ\"ג \"אשר קדשנו במצותיו וצונו\"].\nד. ועדיין צריך ביאור: מה נוגע לתו­כן דברי המשנה ההדגשה ש\"עשה אברהם אבינו את כל התורה כולה עד שלא נית­נה\", שלא הי' בזה אפילו החפצא דתורה, ואילו בסוגיא דיומא נוגע ההדגשה (שב­מאמר רב) שהי' אצל אברהם גם החפצא דתורה?\nויובן זה בהקדם ביאור ההוספה בה­ראי' מאברהם \"וכן הוא אומר באברהם אבינו\" על הראי' הא' מהכתוב \"עוד ינובון בשיבה\":\nהראי' מהכתוב \"עוד ינובון בשיבה\" יש מקום לפרשה שזה ש\"התורה אינה כן (כ­שאר אומנות) אלא משמרתו מכל רע בנערותו ונותנת לו אחרית ותקוה בזקנו­תו\", וכפרש\"י<sup data-n=\"976\">29</sup> \"אבל התורה אינה כן, שאף הבא לידי זקנה או ייסורין ואינו יכול לעסוק בה הוא אוכל ממתן שכרה דכתיב עוד ינובון בשיבה\", הוא בגדר שכר על לימוד התורה (וקיום המצות) בימי נערותו,",[["968","21","וע\"ד שיש לפרש ב' אופנים בהא דקטנים אינן בני מצוה, אם שאין תומ\"צ שייכים אליהם, או דלכל ישראל ניתנו (וגם להם) אלא דקטנים אינם בני חיוב ועונש כו' — ראה לקו\"ש ח\"ד ע' 1249. וש\"נ. וראה מנ\"ח מצוה רסג בסופה."],["969","22","ראה מדרש תהלים צ, ד. ב\"ר פ\"ח, ב. וש\"נ. תנחומא וישב ד."],["970","23","ראה בארוכה (בסגנון אחר) לקו\"ש חט\"ז (ע' 212 ואילך; 218 ואילך). וש\"נ."],["971","24","להעיר מהקושיא בתוס' הרא\"ש סוף קידושין. וראה השינויים בזה ברז\"ל \"עד שלא ניתנה\" (כבמשנתנו), ובירושלמי סוף קידושין \"עד שלא באת לעולם\", ובתוספתא סוף קידושין \"עד שלא באת\" ומסיים \"מלמד שנתגלו לו טעמי תורה ודקדוקי'\". וראה ב\"ר פצ\"ה, ג \"עד עכשיו לא ניתנה תורה כו' (ומסיים) ומהיכן למד אברהם את התורה כו'\" (וראה שם הדיעות בזה)."],["972","25","וע\"ד ב' האופנים די\"ל במצות דקטן ש­מדרבנן (ראה לעיל הערה 21), אם חל ע\"ז שם מצוה דאז צריך לקיימן בכל הפרטים, או דהוי רק מעשה והכשר בעלמא, ואין העשי' צ\"ל בכל הפרטים כגדול — ראה לעיל ע' 62 ואילך. וש\"נ."],["973","26","משנה קידושין כט, א. רמב\"ם הל' ע\"ז פי\"ב ה\"ג. טושו\"ע (ודאדה\"ז) או\"ח סי' יז ס\"ב (א). ועוד."],["974","27","ראה רמב\"ם הל' ציצית פ\"ג ה\"ט. תוד\"ה דלמא (עירובין צו, א). ובכ\"מ."],["975","28","רמ\"א (ושו\"ע אדה\"ז) או\"ח שם ס\"ב (ג). טור (וראה חי' הגהות לסי\"ז שם) ורמ\"א (ושו\"ע אדה\"ז) סתקפ\"ט ס\"ו (ב). וראה שו\"ת הצ\"צ או\"ח סי' ג. — וראה לקו\"ש חלק לא ע' 96."],["976","29","ד\"ה אבל התורה."]]],[1301670172,"או עכ\"פ זכות התורה מצד עצמה, עצם החפצא דתורה דמגינא ומצלא<sup data-n=\"977\">30</sup> גם בזק­נותו; וע\"ז קמ\"ל ראי' הב', שזהו גם מצד (זכות) מעשה הגברא, וכפי שמצינו באב­רהם \"שעשה אברהם אבינו את כל התורה כולה עד שלא ניתנה\", אף שלא הי' אז כל הגדר דתורה, וגם בו נאמר \"ואברהם זקן וה' ברך את אברהם בכל\".\nויש לומר, דכמו\"כ במאמר רב ביומא שם נוגע הדיוק \"קיים אברהם אבינו כל התורה כולה\", שהיתה כבר חפצא דמצוה, ובמילא שיש בעשיית אברהם הגדר ד­קיום מצוה:\nלעיל בגמ' שם איתא \"צלותא דאברהם מכי משחרי כותלי אמר רב יוסף אנן מ­אברהם ניקום וניגמר (ופי' הערוך<sup data-n=\"978\">31</sup> היאך נלמד מאברהם שקיים התורה עד שלא ניתנה ואין לנו ללמוד אלא ממנהג נביאים מפני שנהגו בהלמ\"מ), אמר רבא תנא גמר מאברהם ואנן לא גמרינן מיני' דתניא וביום<sup data-n=\"979\">32</sup> השמיני ימול בשר ערלתו מלמד שכל היום כשר למילה אלא שהזריזין מקדימין למצות שנאמר<sup data-n=\"980\">33</sup> וישכם אברהם בבוקר ויחבוש וגו' אלא אמר רבא רב יוסף הא קא קשיא לי' כו' א\"נ שאני אבר­הם דאיצטגנינות גדולה היתה בלבו א\"נ משום דזקן ויושב בישיבה הוה כו'\".\nוע\"פ פירוש הערוך הנ\"ל יש לומר, דזהו שהביא הש\"ס לאח\"ז מאמר רב \"קיים אברהם אבינו כל התורה כולה\", והיינו שאין זה רק אגב אורחא דהסוגיא דלימוד התורה וקיום המצות דאברהם, אלא דכיון שבמעשה אברהם הי' בזה גדר קיום מצוה שהרי היתה חפצא דתורה, לכן אפשר ללמוד (גם) מאברהם, אף שהי' לפני ה­ציווי על קיומן [ולפ\"ז מוסבר מה שאפשר ללמוד מאברהם לא רק ענין הזריזות ב­קיום המצות אלא גם בענין קיום המצות גופא].\nה. והנה ביאור הנ\"ל בל' המשנה \"עשה אברהם אבינו את כל התורה כולה עד שלא ניתנה\" מתאים גם עם הפירוש ה­פנימי ב\"עשה\" — שהוא פעל וחידש בה (ע\"ד לשון הכתוב<sup data-n=\"981\">34</sup> \"ואת הנפש אשר עשו בחרן\", וכפשטות פירושו ברז\"ל<sup data-n=\"982\">35</sup> דקאי על \"עשיית\" גרים, ד\"אברהם מגייר את האנשים ושרה מגיירת הנשים\").\nוהיינו דאברהם בעשייתו ועבודתו \"עשה\" — פעל והמשיך התורה בשביל בני ישראל, וכמאמר חז\"ל בנוגע לכמה דב­רים \"מעשה אבות סימן לבנים\"<sup data-n=\"983\">36</sup>, ופירושו שהוא נתינת כח לבנים<sup data-n=\"984\">37</sup>, כן הוא בנוגע לכללות ענין התורה<sup data-n=\"985\">38</sup>, שע\"י עבודת אב­רהם במסירת נפש על התורה והמצוה \"עשה\"<sup data-n=\"986\">39</sup> והמשיך את התורה לבניו, כל בני ישראל אחריו.\n[וכמו שהוא בשייכות לנשמות ישראל, דכיון ש\"האבות הן הן המרכבה<sup data-n=\"987\">40</sup> (\"שכל אבריהם כולם היו קדושים ומובדלים מענייני עוה\"ז ולא נעשו מרכבה רק לרצון",[["977","30","ראה סוטה כא, א."],["978","31","ערך שחר (הא') — נעתק על הגליון ביומא שם. ועד\"ז בר\"ח יומא שם. ועוד."],["979","32","תזריע יב, ג."],["980","33","וירא כב, ג."],["981","34","לך לך יב, ה."],["982","35","כפרש\"י עה\"פ (מב\"ר פל\"ט, יד. ע\"ש)."],["983","36","ראה תנחומא לך לך ט. ב\"ר פ\"מ, ו."],["984","37","ראה רמב\"ן לך לך יב, ו. שם, יוד. יד, א. פרשתנו כו, א. ועוד."],["985","38","ראה בארוכה ע\"ד החסידות תו\"ח לך לך (פג, סע\"ג ואילך). שם ח\"ש (קלה, סע\"א ואילך). ובכ\"מ."],["986","39","להעיר מד\"ה אנכי מגן לך תרע\"ח (קה\"ת, תנש\"א) בנוגע למצות שקיימו האבות, ושם בסופו \"דמש\"א (שהש\"ר פ\"א, ג (א)) ריחות היו זהו בהמצות שעשו מצ\"ע. . אבל בחסד ה' ע\"י הנסיונות המשיכו ג\"כ מבחי' עצמות א\"ס\" (כמו המצות שלאחרי מ\"ת)."],["987","40","ב\"ר פמ\"ז, ו. פפ\"ב, ו. ועוד."]]],[1301670173,"העליון לבדו כל ימיהם\"<sup data-n=\"988\">41</sup>) ועל כן זכו להמשיך נר\"נ לבניהם אחריהם עד עולם מעשר ספירות דקדושה\"<sup data-n=\"989\">42</sup>].\nו. ויש לומר שגם בלימוד התורה דידן יש מעין חילוקי דרגות אלו: תורה כפי שהיא מצד הציווי; שאין עלי' ציווי אבל ישנה להחפצא; אופן שאינו שייך כלל לציווי וכאילו ליתא גם החפצא:\nא) הלימוד מצד החיוב הכללי השייך לכאו\"א, שכל אחד \"יוצא י\"ח בקביעות עתים לת\"ת. . ביום ובלילה בכדי ללמוד ולזכור היטב לימוד המביא לידי מעשה בלבד שהוא חובה על הכל דהיינו השלחן ערוך מהלכות הצריכות לכל אדם לידע אותן כו' ושאר כל היום יעסוק במשא ומתן כדי שיוכל להחזיק ידי ת\"ח\"<sup data-n=\"990\">43</sup>;\nב) קיום \"מצוה<sup data-n=\"991\">44</sup> זו (דת\"ת) כראוי (ע\"י ש)יעשה מלאכה בכל יום מעט כדי חייו בלבד ויסור התאוות ותענוגי הזמן מלבו כמו שאמרו חכמים<sup data-n=\"992\">45</sup> כך היא דרכה של תורה פת במלח תאכל כו'\", והיינו שעושה \"מלאכתו עראי\", וחיוב זה אינו מוטל על כל אחד מישראל ד\"אינו חייב לחיות חיי צער ולעשות מלאכתו עראי כדי להרבות בלימוד שאינו מבין על בוריו כו' אא\"כ עושה במדת חסידות ואהבת התורה\"<sup data-n=\"990\">43</sup>, אבל באם עושה כן הרי הוא זוכה ל\"כתר תורה\"<sup data-n=\"994\">46</sup>;\nג) לימוד התורה באופן שהאדם בוטח בה' לגמרי, ואינו עושה מלאכה כלל, וע\"ד אוכלי המן, וכדברי רשב\"י<sup data-n=\"995\">47</sup> \"אפשר אדם חורש כו' תורה מה תהא עלי' אלא בזמן שישראל עושין רצונו של מקום מלאכתן נעשית על ידי אחרים<sup data-n=\"996\">48</sup> כו'\".\nויש לומר, שב' אופנים האחרונים שאין עליהם ציווי לכאו\"א, הם ע\"ד ב' האופנים הנ\"ל בגדר התורה דאברהם — אם ישנה לחפצא דתורה אלא שלא נצטווה כדוגמת אופן הב', דישנו גדר לימוד כזה שתורתו קבע ומלאכתו עראי לגמרי (\"בכל יום מעט כדי חייו. . תספיק לו מלאכת עראי בישועת ה' והצלחתו בלי הזכרת מעשה נסים\"<sup data-n=\"991\">44</sup>), אלא שהאדם אינו חייב בזה רק מצד מדת חסידות ואהבת התורה; ול­מעלה מזה הוא האופן דבוטח בה' לגמרי שיספק לו כל צרכיו, ועוסק רק בתורה, וגדר לימוד כזה הוא ע\"ד תורה עד שלא ניתנה, שלא רק שאין על זה חיוב, אלא שע\"פ הלכה לא מצינו מציאות כזו לסמוך על הנס<sup data-n=\"998\">49</sup>.\nוזהו מה שמדייק ר\"נ \"מניח אני כל אומנות שבעולם ואיני מלמד את בני אלא תורה\", שלא בא לחלוק אדברי ר\"מ<sup data-n=\"999\">50</sup> שלפנ\"ז \"לעולם ילמוד אדם את בנו אומ­נות\", כי אם מעשה רב דעצמו אתי ל­אשמעינן, \"מניח אני כל אומנות שבעולם ואיני מלמד את בני אלא תורה\" (כמבואר במפרשים<sup data-n=\"1000\">51</sup>), שהוא דוקא, מצד גודל",[["988","41","תניא פכ\"ג."],["989","42","תניא פי\"ח."],["990","43","הל' ת\"ת לאדה\"ז פ\"ג ס\"ד."],["991","44","הל' ת\"ת שם ס\"ג. וש\"נ."],["992","45","אבות פ\"ו, ד."],["990","43","הל' ת\"ת לאדה\"ז פ\"ג ס\"ד."],["994","46","ראה קו\"א להל' ת\"ת שם סק\"א [תתמד, ב ואילך]."],["995","47","ברכות לה, ב."],["996","48","ראה קו\"א שם."],["991","44","הל' ת\"ת שם ס\"ג. וש\"נ."],["998","49","ראה הל' ת\"ת שם ס\"ג (נעתק לעיל בפנים) ובהנסמן שם. וראה רמב\"ם הל' שמיטה ויובל בסופן."],["999","50","ובפרט דר\"מ הוא ר' נהוראי (עירובין יג, ב. רמב\"ם בהקדמתו לפיה\"מ בסופה (פ\"ו)). ולהעיר דזוהי אחת מהראיות בס' היוחסין (הובא בסה\"ד חלק תנאים ואמוראים ערך ר' נהוראי) דר\"נ אינו ר\"מ, כי \"בסוף קידושין חולק ר\"נ עם ר\"מ\". וראה מלאכת שלמה שבהערה הבאה."],["1000","51","מלאכת שלמה למשניות קידושין שם. המק­נה סוף קידושין. ועוד. וראה גם כסא רחמים למס' סופרים רפט\"ז (ב\"פירוש\"): לפי רוב הענוה אשר במאמרו לא דיבר דרך הוכחה ולא אזהרה כו'."]]],[1301670174,"בטחונו בה', אינו מלמד את בנו אלא תו­רה<sup data-n=\"1001\">52</sup>, אבל אין זו הדרך הנתבעת מכל אדם, דאצל כל אדם צ\"ל תורתו קבע ומלאכתו עראי כנ\"ל, כדברי ר\"מ<sup data-n=\"1002\">53</sup>.\nומדויק גם בדברי רשב\"י \"בזמן ש­ישראל עושין רצונו של מקום מלאכתן נעשית ע\"י אחרים\", היינו שבנ\"י \"עושין\" ומחדשים<sup data-n=\"1003\">54</sup> רצונו של מקום, כי מצד ציווי ה' אין מקום להנהגה זו, אלא יחידי סגולה מצד גודל בטחונם בה' עושין ומחדשים רצונו של מקום, ואז בדרך ממילא מלאכתן נעשית ע\"י אחרים, שהקב\"ה ממלא כל הצטרכותם בדרך נס<sup data-n=\"1004\">55</sup>, למעלה מהטבע לגמרי.\n<span data-k=\"q\">(משיחת ו' תשרי תשמ\"ה)</span>",[["1001","52","וראה גם מאירי במשנה קידושין בדברי ר\"נ \"מניח אני כל אומנות שבעולם\" — \"אפילו אומנות נקי' וקלה\". וכ\"כ בשושנים לדוד למשניות סוף קידושין, דלר\"נ לא ילמוד אומנות כלל."],["1002","53","אבל בחדא\"ג כאן, כסא רחמים (להחיד\"א) למס' סופרים שם (ב\"תוספות\") — פי' דגם לר\"נ צ\"ל מלאכתו עראי עכ\"פ."],["1003","54","ראה לקו\"ת שלח מג, א. ברכה צט, ג."],["1004","55","וראה בארוכה הדרן על מס' קידושין — לקו\"ש חט\"ז ע' 533 ואילך. וראה שם ביאור החילוק בין המשנה והברייתא דסוף קידושין."]]],[1301670175,"<h3>שיחה ג</h3>\nא. בסיום פרשתנו נאמר \"וירא עשו כי רעות בנות כנען בעיני יצחק גו' וילך עשו אל ישמעאל ויקח את מחלת בת ישמעאל גו' על נשיו לו לאשה\".\nובמדרש רבה<sup data-n=\"1005\">1</sup> הובאו ב' דעות בפי­רוש כתוב זה: \"ר' יהושע בן לוי אמר נתן דעתו להתגייר (לעשות תשובה<sup data-n=\"1006\">2</sup>), מחלת שמחל לו הקב\"ה על כל עונותיו כו' אמר ר\"א אילו הוציא את הראשונות יפה הי', אלא על נשיו, כאב על כאב (ראשונות היו רעות והשניות כמו כן. רש\"י לב\"ר), ד\"א כוב על כוב (קוצים על קוצים), תוספת על בית מלא (בית היתה מלאה נשים נכריות (ארורות. מתנות כהונה) והוא הוסיף לקחת עליהן. רש\"י).\nועפ\"ז יש לעיין בשיטת רש\"י בפי­רושו על התורה, שפירש \"על נשיו\" — \"הוסיף רשעה על רשעתו שלא גרש את הראשונות\", כדעת ר\"א במדרש, ואילו לקמן בפ' וישלח עה\"פ<sup data-n=\"1007\">3</sup> \"בשמת בת יש­מעאל\" פרש\"י \"ולהלן קורא לה מחלת. . ג' מוחלין להן עונותיהם. . והנושא א­שה. . לכך נקראת מחלת שנמחלו עונותיו\" — הרי שנקט כדעת ריב\"ל (שנמחלו עונותיו)?\nוהנה בנוגע להנהגת עשו יש לתווך, דגם בפירושו בפ' וישלח אין כוונת רש\"י (כדברי ריב\"ל במדרש) \"שנמחלו עונותיו\" מפני \"שנתן דעתו להתגייר\", אלא שעצם הענין ד\"נושא אשה\" יש בו סגולה שמביא למחילת עונות (ע\"ד \"העולה לגדולה\" שהובא ברש\"י שם), ולכן נמחלו עונותיו של עשו אף שלא נתן דעתו להתגייר (ואדרבה, \"הוסיף רשעה על רשעתו\")<sup data-n=\"1008\">4</sup>.\nוצריך ביאור בנוגע ל\"מחלת\" עצמה:\nמפשטות דברי המדרש מובן, ששתי הדיעות בכוונתו של עשו (אם \"נתן דעתו להתגייר\" או להיפך) חלוקות גם בטיבה ומהותה של \"מחלת בת ישמעאל\", אם אשה כשרה היתה: לפי ריב\"ל היתה אשה כשירה (ולכך נקראת \"מחלת\" — שם הרומז על מחילת עונות), ולפי ר\"א היתה מרשעת, כנשי עשו הראשונות (וזהו פירוש \"על נשיו\", שהיתה דומה לנשיו הראשונות).\nוא\"כ סתרי דברי רש\"י אהדדי, דכאן (בסוף פרשתנו) נקט שהיתה מרשעת, ואילו לקמן פי' השם ד\"מחלת\" ע\"ש מחילת עונות, שמזה משמע שאשה כשרה היתה.\n[שהרי גם את\"ל שעצם הענין ד\"נושא אשה\" מביא למחילת עונות (גם בלי שינוי מעשים לטוב) — מ\"מ, מזה גופא",[["1005","1","סוף פרשתנו."],["1006","2","נזר הקודש (השלם) ועץ יוסף לב\"ר שם. וראה חי' הרד\"ל שם."],["1007","3","לו, ג."],["1008","4","ראה נחלת יעקב כאן. וראה גם יפה תואר (השלם) לב\"ר שם, יפה מראה ועץ יוסף לירושלמי בכורים (פ\"ג ה\"ג) — דהא דירושלמי שם (ומדרש שמואל פי\"ז), \"חכם חתן כו' מכפרת\", פליג אתנא דב\"ר.\nוגם לפמשנ\"ת במ\"א (לקו\"ש ח\"ה ע' 170. ח\"ל ע' 162 ואילך), שלשיטת רש\"י בפירושו עה\"ת, מחי­לת עונות דחתן תלוי' בשינוי מעשיו לטוב, הרי עשו לא שינה מעשיו, כמפורש ברש\"י כאן ש(אדרבא) \"הוסיף רשעה על רשעתו\", וצ\"ל שנמחלו עונותיו מצד מחלת. ולהעיר מהגירסא בפרש\"י \"שנמחלו עונותי'\" — ראה לקמן בפנים."]]],[1301670176,"שרק היא נקראת בשם \"מחלת\" (הרומז על מחילת עונות), ולא נשיו הראשונות, משמע, שהיא היתה ראוי' לכך (גם) מצד מעשי' וכו'.\nובפרט לפי הגירסא בפרש\"י<sup data-n=\"1009\">5</sup> בכמה כתבי יד — \"שנמחלו עונותי'\" (ולא \"עונותיו\"), שמשמע מזה שרק עונותי' נמחלו ולא של עשו, והיינו לפי שהיא היתה כשרה, משא\"כ עשו שנשאר רשע].\nב. אבל כד דייקת נראה שקושיא מעיקרא ליתא, כי כוונת רש\"י בפירושו כאן אינה כפירוש ר\"א במדרש אלא הוא פירוש חדש בדברי הכתובים:\nלשון המדרש היא \"אילו הוציא את הראשונות יפה הי', אלא על נשיו כאב על כאב כו'\"; אבל רש\"י שינה וכתב \"הוסיף רשעה על רשעתו שלא גירש את הראשונות\". ושני שינויים (עיקריים) כאן:\n(א) \"כאב על כאב\" (כוב על כוב) פי­רושו שהוסיף אשה מרשעת על נשיו הרשעות שהיו לו לפני זה, אבל ל' רש\"י \"הוסיף רשעה על רשעתו\" פירושו שמ­עשה נישואי מחלת עצמו הוא מעשה של רשעות מצד עשו.\n[בדפוסי רש\"י הנפוצים ישנה הוספה­הגהה בסוגריים \"ר\"ל מרשעת על מר­שעיות שהיו לו כבר\".\nאמנם עכצ\"ל שאין כוונת המגי' ש­\"רשעה על רשעתו\" פירושו \"מרשעת על מרשעיותיו\" (\"רשעה\" בניקוד שבא, ש­אשתו היא רשעה, כמו \"מלכות יון הרש­עה\") — דא\"כ הו\"ל לרש\"י לכתוב \"רשעה על רשעותיו\"<sup data-n=\"1010\">6</sup>: ומדכתב רש\"י \"על רשע­תו\" משמע, שהרי\"ש בתיבת \"רשעה\" היא בניקוד חיריק (וכמו \"והרשעה כולה ב­עשן תכלה\"), וקאי על רשעתו של עשו<sup data-n=\"1011\">7</sup>.\nויותר מסתבר לומר, שכוונת המגי' היא רק לפרש ולבאר, שרשעתו של עשו (שהוסיף על רשעתו שלפנ\"ז) היא — שנשא מרשעת על מרשעיותיו שהיו לו כבר.\nאבל גם לפ\"ז צע\"ג איך אפשר לפרש כן בפרש\"י<sup data-n=\"1012\">8</sup>, שהרי רש\"י לא הזכיר כלל שמחלת היתה מרשעת, ואם זוהי כוונת רש\"י הי' כותב כן בלשון ברורה: \"הוסיף מרשעת\" (וכיו\"ב)].\n(ב) הלשון \"אילו הוציא את הראשונות יפה הי'\" במדרש באה בתחילת הענין, ואילו רש\"י מהפך הסדר וכתב לשון זו (\"שלא גרש את הראשונות\") בסיום הענין.\nג. ויש לומר ששני השינויים תלויים זב\"ז:\nלפי המדרש, הרשעות של עשו היתה בזה שנשא עוד מרשעת, \"כאב על כאב\", ומ\"ש \"אילו הוציא את הראשונות יפה הי'\" היא רק הקדמה להוציא מדעת ריב\"ל (שלפנ\"ז) ש\"נתן דעתו להתגייר\", שא\"א לומר כן, כי אם כן הי' לו לגרש את הראשונות;\nמשא\"כ לדעת רש\"י לא היתה מחלת מרשעת, וזהו שכתב רש\"י \"הוסיף רשעה על רשעתו שלא<sup data-n=\"1013\">9</sup> גירש את הראשונות\",",[["1009","5","וישלח שם."],["1010","6","או \"רשעיותיו\", \"רשעניותיו\" (ע\"ד סנהדרין קיב, א וברש\"י שם).\nובדפוס א' דפרש\"י (וכן בא' מכת\"י רש\"י ש­תח\"י) \"רשעה על רשעה\", ובזה אפשר לפרש מלשון \"מרשעת\". וראה הערה 9."],["1011","7","ובכמה כת\"י רש\"י שתח\"י \"רשע (רשעה) על רשע (רשעו)\"."],["1012","8","וכן צ\"ע לפירושו, סיום ל' רש\"י \"שלא גירש את הראשונות\" — ראה הערה 10."],["1013","9","בדפוס ראשון דפרש\"י \"ולא גירש כו'\". ולהעיר, שלגירסתו \"הוסיף רשעה על רשעה\", יש לפרש שהיו ב' חטאים: א) נשא אשה מרשעת (ראה הערה 6), ב) ולא גירש את הראשונות."]]],[1301670177,"כלומר, שזו עצמה היא הרשעות שהוסיף עשו עתה<sup data-n=\"1014\">10</sup>, שלא גירש את הראשונות, כדלקמן סעיף ד.\nומוכרח מתוכן הפרשה שמחלת לא היתה מרשעת, שהרי<sup data-n=\"1015\">11</sup> כל הטעם שנשא עשו את בת ישמעאל הוא לפי שראה \"כי רעות בנות כנען בעיני יצחק אביו\", ורצה לעשות נח\"ר לאביו ולישא אשה שתהי' ישרה בעיניו, ולכן הלך ליש­מעאל<sup data-n=\"1016\">12</sup> לישא אשה מיוחסת דוקא [שזהו דיוק לשון הכתוב \"(וילך עשו אל יש­מעאל) ויקח את מחלת בת ישמעאל בן אברהם\" — שלכאורה \"בן אברהם\" מיו­תר, ומאי קמ\"ל<sup data-n=\"1017\">13</sup>? אלא שבזה מדגיש הכתוב שעשו נשא אשה מיוחסת דוקא, בת \"בן אברהם\"] — וא\"כ מסתבר לומר שלקח אשה כשירה<sup data-n=\"1018\">14</sup>, ולא אשה כנשיו הראשונות שהיו \"מורת רוח ליצחק ול­רבקה\"<sup data-n=\"1019\">15</sup>.\nד. ועדיין הדברים טעונים ביאור — דאיך אפשר לומר שרשעתו היא בכך \"שלא גירש את הראשונות\", דמה זה שייך ל\"ויקח את מחלת גו'\"? הרי ה­רשעות \"שלא גירש את הראשונות\" היתה אצלו ענין מכו\"כ זמן (מאז נשא אותן), ומהו הענין שאז \"הוסיף רשעה על רש­עתו (בכך) שלא גירש את הראשונות\"?\nויש לומר הביאור בזה — בפשטות:\nהרשעות של עשו בלקיחת נשיו הרא­שונות לא היתה רק שנשא נשים כאלו שהיו \"מורת רוח ליצחק ולרבקה\", אלא גם מפני הצביעות והרמאות בנישואין אלה, וכפרש\"י עה\"פ<sup data-n=\"1020\">16</sup> \"ויהי עשו בן אר­בעים שנה\" — \"עשו הי' נמשל לחזיר כו' החזיר הזה כשהוא שוכב פושט טלפיו לומר ראו שאני טהור, כך אלו גוזלים וחומסים ומראים עצמם כשרים, כל מ' שנה הי' עשו צד נשים כו' כשהי' בן מ' אמר אבא בן מ' שנה נשא אשה אף אני כן\".\nוזהו גם שאומר (הכתוב ו)רש\"י בסוף פרשתנו — \"ויקח את מחלת גו' על נשיו\", \"הוסיף רשעה על רשעתו שלא גירש את הראשונות\" — דכשם שנישואיו הרא­שונים היו מעשה צביעות (שיאמרו שמת­",[["1014","10","אבל אין לומר שב\"לא גירש את הרא­שונות\" בא רש\"י לבאר תוכן רשעתו הקודמת של עשו (שעלי' הוסיף עתה עוד רשעות — \"(רשעה) על רשעתו\") — שלא גירש את הראשונות [ולכאורה כן מפרש בעל המגי' בפרש\"י] — כי (א) א\"כ לא נזכר ברש\"י כלל מהי רשעתו של עשו עתה. (ב) ועיקר: רשעתו הקודמת של עשו היא מה שנשא נשים אלו, ומהיכי תיתי לומר שגירש את הראשונות, שבשביל זה צריך רש\"י להדגיש (ש\"על נשיו\" פירושו) \"שלא גירש את הראשונות\"."],["1015","11","ראה יפה תואר לב\"ר שם."],["1016","12","להעיר מרש\"י חיי שרה כד, מט."],["1017","13","ועכ\"פ הו\"ל לאמרו בתחילת הכתוב, \"וילך עשו אל ישמעאל בן אברהם\" (יפ\"ת שם)."],["1018","14","ראה גם גו\"א סוף פרשתנו (ד\"ה אחות נביות).\nועפ\"ז מתורץ גם זה שנמחלו עונותיו של עשו (להגירסא \"שנמחלו עונותיו\"), גם להסברא שצ\"ל שינוי מעשיו לטוב (ראה הערה 4) — כיון שלקח אשה כשירה. ואע\"פ שהיתה בזה רשעות (\"הוסיף רשעה כו'\"), מצד הצביעות שבזה (כדלקמן סעיף ד) — מ\"מ, כיון שבפועל לקח אשה כשירה, יש בנישואין אלה כדי לפעול מחילת עונות. וק\"ל.\n[וי\"ל, שזהו הטעם שענין זה (דנושא אשה מוחלין לו כו') נרמז אצל נישואי עשו ומחלת דוקא, ללמ­דנו, שגם שינוי מעשה כזה מספיק לפעול מחילת עונות. וראה יפ\"ת ונזר הקודש לב\"ר שם. לקו\"ש ח\"ל ע' 7­166]."],["1019","15","פרשתנו כו, לה ובפרש\"י. שם כז, מו."],["1020","16","כו, לד."]]],[1301670178,"נהג כיצחק אביו), כך גם בנישואי מחלת הוסיף רשעות מעין רשעתו הקודמת, שלקח אשה כשירה רק כדי<sup data-n=\"1021\">17</sup> שיאמר יצחק שחוזר בתשובה, בה בשעה שזה לא הי' אלא צביעות<sup data-n=\"1022\">18</sup>, שהרי \"לא גירש את הראשונות\"<sup data-n=\"1023\">19</sup>. כלומר: נישואי אשה כשרה בה בשעה ששאר נשיו אינן כש­רות מורה שנישואין אלו הן צביעות ורשעות.\n[ולפי\"ז, התיבות \"על נשיו\" שבכתוב, לא באו ללמד את הצד השווה של נשי עשו (ע\"ד הנ\"ל במדרש — \"כאב על כאב\"), אלא לתאר את רשעתו של עשו, דאע\"פ שלקח עתה אשה כשרה, מ\"מ הי' זה \"על נשיו\" — \"שלא גירש את הרא­שונות\"].\nה. מ\"יינה של תורה\" שבפירוש רש\"י:\nסיפורי התורה בכלל, אינם סיפור בעלמא ח\"ו, אלא בגלל ההוראות ב­עבודת השם<sup data-n=\"1024\">20</sup> הטמונים בהם (תורה מל­שון הוראה). וכ\"ש וק\"ו סיפורי תולדות עשו ש\"לא היו ספונים וחשובים ל­פרש\"<sup data-n=\"1025\">21</sup> אותם בתורה, שכל הפרטים בהם שבאו בתורה, יש בהם הוראה בעבודת בני ישראל.\nומזה מובן גם בעניננו, שהסיפור שבסוף פרשתנו אודות נישואי עשו עם מחלת בת ישמעאל, נוגע לעבודת בני ישראל. ובזה גופא יש לימוד מיוחד ע\"פ פירוש רש\"י ש\"רשעתו\" של עשו היא \"צביעותו\". כלומר: החסרון שבצביעות אינו רק משום שהיא מטעה ומרמה, אלא שה\"צביעות\" עצמה היא (עיקר) \"רשעתו\" של עשו.\nויובן זה בהקדים החילוק הכללי בין תולדות עשו שבפ' תולדות לאלו שבפ' וישלח — שבפרשתנו מסופר (בעיקר) או­דות עניני עשו השייכים ליצחק (\"ואלה תולדות יצחק\"), משא\"כ בפ' וישלח באו קורות עשו בשייכות ליעקב.\nוהבדל עיקרי ביניהם: בנוגע ליצחק השתדל עשו לרמות אותו שיחשוב ש­צדיק הוא, וכפרש\"י עה\"פ<sup data-n=\"1026\">22</sup> \"כי ציד בפיו\", ואילו כלפי יעקב אחיו הלך ב­מלחמה גלוי'.\nוב' ענינים אלה של עשו הם הוראה בעבודת כאו\"א מישראל, שיש שני סוגי רע — רע גלוי, ורע נעלם המכוסה וטמון בטוב. וכשם שצריך לעמוד בכל התוקף נגד רע הגלוי (שאי אפשר לטעות בו) — כך, ויתר על כן, צריך להזהר מפני תערובת טוב ורע, רע נעלם, ואדרבה — המלחמה נגד רע זה היא קשה יותר.\nוע\"ד שמצינו אצל יעקב עצמו, ששהה בבית לבן עשרים שנה, ואילו היותו עם עשו לא נמשכה אלא יום א' בלבד (כמו שנאמר<sup data-n=\"1027\">23</sup> \"וישב ביום ההוא עשו לדרכו",[["1021","17","ועפ\"ז יש לבאר מה שהתיבות \"בת ישמעאל בן אברהם\" הם ב\"קדמא ואזלא\", שזה מורה שעשו פרסם שהוא נושא את נכדתו של אברהם. וראה כת\"י רמזי התורה לר' יואל (הובא בתו\"ש פרשתנו ע' תתשיז): בת ישמעאל בן אברהם מוכתר בתגין, כלומר מיוחסת לקח כו'."],["1022","18","ראה גם פירושי התורה לבעלי התוספות (ירושלים, תשד\"מ) וישלח שם: וכל זה עשה עשו לרמות אביו."],["1023","19","ברמב\"ן כאן (כח, ה), שבלקיחת מחלת \"ש­מע לעשות רצון אביו\", וזה ש\"לקח אותן על נשיו ולא גרש את הרעות, כי הלך על תאוות נפשו יותר מרצון אביו\". אבל מלשון רש\"י \"הוסיף רשעה כו'\" מובן, שיש כאן הוספת רשעות חדשה, והיינו לפי שעשה כן רק לרמות את אביו, כבפנים."],["1024","20","ראה זח\"ג קנב, א. ע\"ש."],["1025","21","ל' רש\"י ר\"פ וישב."],["1026","22","פרשתנו כה, כח."],["1027","23","וישלח לג, טז."]]],[1301670179,"שעירה\"), ומבואר בזה<sup data-n=\"1028\">24</sup>, כי \"לבן ה­ארמי\" ענינו גניבת דעת ורמאות, וכדי להתגבר על רמאות ולבטלה דרוש זמן רב, משא\"כ עשו שהלך במלחמה גלוי' נגד יעקב, רומז על (זהו) רע גלוי, שעל זה התגבר יעקב במהירות.\nויש לומר, שהרמאות והצביעות של עשו כלפי יצחק היא פחותה וגרועה יותר מה\"רמאות\" של לבן כלפי יעקב. דהנה בהעלמת רע בטוב, יש ב' אופנים: א) ע\"י העלמת הרע כפי האפשרי, ב) ע\"י הדגשת ופרסום הטוב. שזהו החילוק בין לבן לעשו, שלבן רק רימה את יעקב שלא יכיר מחשבתו הרעה, אבל עשו התנהג כחזיר הזה, ש\"פושט טלפיו לומר ראו שאני טהור\", שלא זו בלבד שמסתיר את הסימן הטמא שבו אלא שעושה מעשה לפרסם \"כשרותו\" — והעבודה לברר רמאות זו קשה הרבה יותר מ­ביטול רמאות סתם.\nוי\"ל שזהו גם הטעם שהתורה מספרת אודות נישואי עשו עם מחלת בת ישמעאל, שבזה מגלה לנו הכתוב עד כמה היא צביעותו של עשו, שהלך בזה באופן של \"הוסיף רשעה על רשעתו\", ש\"פשיטת טלפיו\" היתה עד כ\"כ, שבגלל זה לקח אשה כשירה באמת, בה בשעה שנשאר להיות עשו הרשע, שכל רשעתו הקודמת לא סרה ממנו כלל, \"לא גירש את הראשונות\".\nומזה הוראה לכל או\"א מישראל, עד כמה יש להזהר מענין הצביעות, כי אפשר שהיצר יסכים שהאדם יעשה מעשים טובים, ורשעתו עדיין לא סרה ממנו כלל!\nו. לפי ביאור זה בענינו של עשו הר­שע, יש להבין יותר גם דברי רבינו הזקן בטעם אריכות גלות זה האחרון, וז\"ל<sup data-n=\"1029\">25</sup>:\n\"ענין אריכות הגלות הזה מגלו' ה­קדמוני', צריך להבין מלחמות יעקב עם עשו שהי' בזמן קצר שנלחם עמו ונצחו, ובלבן נשתהה כ\"ב שנים. . עד שנאמר<sup data-n=\"1030\">26</sup> ויבא יעקב שלם<sup data-n=\"1031\">27</sup>. [והביאור] לפי ש­עשו. . מה שלבו חפץ כן ימהר לעשותו שהלך בשרירות לבו רק רע כל היום והכל בגלוי אומר מה שרוצה ואינו בר­מאות, ונקל להלחם עמו שלא לעשות כרצונו בכל הדברים אשר הוא חושק ומתאוה. . וכן בדורות הראשונים היו בגלוי מי שהי' רשע לא הי' בוש מלעשות רע. . ולפיכך ארז\"ל<sup data-n=\"1032\">28</sup> דורות ראשונים שנתגלה עונם נתגלה קצם, אבל דורות האחרונים שלא נתגלה עונם כו', לא נתגלה פי' שמכסים עונם ואינו ניכר הגניבת דעת הבריות שהוא יכול לעשות עבירה. . אך בסתר, ויבוש מלעבור ב­גלוי. . הרע נסתר ונטמן ומכסה עצמו בעבודת ה'. . וזה הי' מלחמת יעקב עם לבן שהי' רמאי ביותר והי' קשה ביותר כי הי' צריך ג\"כ להתנהג עמו ברמאות כי א\"א בלאו הכי, ולכן נמשך זמן רב משך מלחמתם וזהו אריכות הגלות הזה שהוא בחי' לבן\". עכ\"ל.\nולכאורה אינו מובן: ידוע שגלות זה האחרון הוא גלות אדום, ש\"עשו הוא",[["1028","24","ראה מאמרי אדה\"ז — הקצרים (ע' תנב­ג), נעתק (בקיצור) לקמן בפנים סעיף ו. וראה גם אוה\"ת ויצא רכב, א (ושם רכו, א באו\"א קצת). סה\"מ תרע\"ח ע' פג."],["1029","25","נסמן בהערה הקודמת. — כאן נעתק נוסח השני הנדפס שם."],["1030","26","וישלח לג, יח."],["1031","27","ראה רש\"י (וישלח שם, יז. רש\"י ישן סוף פרשתנו. ועוד) — שעד אז שהה כ\"ב שנה. ובנוסח הראשון של המאמר \"עשרים שנה\" — הזמן ששהה בבית לבן עצמו (ויצא לא, מא). וראה סה\"מ תרע\"ח שם."],["1032","28","יומא ט, ב."]]],[1301670180,"אדום\"<sup data-n=\"1033\">29</sup>, וע\"פ הנ\"ל מבואר שגלות זה שייך ללבן דוקא, ולא לעשו שהלך בגלוי \"ואינו ברמאות\"?\nוע\"פ הנ\"ל מתורץ, כי בעשו גופא יש ב' אופנים: כלפי יעקב אחיו הלך עשו במלחמה גלוי', ולכן התגבר עליו יעקב בלא שהיית זמן ארוך (ומלחמתו של יעקב נגד מדת ה\"רמאות\" היתה בהיותו אצל לבן הארמי, ולפיכך הוצרך לשהות שם עשרים שנה); משא\"כ כלפי יצחק אביו, התנהג עשו ברמאות, ועוד יותר מרמאות של לבן כנ\"ל, ו\"בירור\" זה של עשו קשה עוד יותר מבירורו של לבן.\nוזהו הטעם שגלות זה האחרון (שעבו­דתו היא לבטל רמאות זו כנ\"ל) הוא גלות אדום דוקא, שנמשל לחזיר (כדאי­תא במדרש<sup data-n=\"1034\">30</sup> \"ואת החזיר זו אדום\"), ש\"פושט טלפיו לומר ראו שאני טהור\" — שזהו הטעם לאריכות הגלות הזה, לפי שעיקר הבירור שבו הוא לבטל רע נעלם כזה, שנוסף על שהוא מעורב בטוב (כמו אצל לבן), עוד זאת, ש\"פוש­טים\" (מדגישים) הטוב לחוץ ובחוץ לומר \"ראו שאני טהור\".\nז. ויש לומר הטעם שצביעות זו של עשו היתה רק כלפי יצחק — ע\"פ ה­ידוע<sup data-n=\"1035\">31</sup> בענין ברכות יצחק, שזה שרצה יצחק לברך את עשו דוקא, הוא לפי שיצחק \"הביט\" על עשו, ראה אותו כפי שהוא מצד שרשו, וראה את הטוב הגנוז בו (כנשמות הגרים שיצאו ממנו, \"כמו<sup data-n=\"1036\">32</sup> ר' מאיר, ואונקלוס, ושמעי' ואבטליון, ועובדי'\"), ואמר שע\"י הברכות יצא טוב זה מן ההעלם אל הגילוי (גם אצל עשו עצמו), באופן שיבטל לגמרי את הרע שבו.\nוכן בעניננו: ה\"טוב\" שבעשו — שהוא הנותן מקום לרמאות שלו, לערב טוב עם רע ועד לפשוט את טלפיו ולומר אני טהור כו' — הוא מצד הטוב הגנוז שב­שרשו, ולכן הבירור של רע זה שבעשו שייך ליצחק דוקא.\nוזהו ג\"כ תוכן עבודתם של ישראל בגלות זה האחרון, גלות אדום, לברר גם רע זה של עשו (אבי אדום), עד עת קץ שאז יתגלה הטוב הגנוז שבו (כפי שהי' נראה אצל יצחק<sup data-n=\"1037\">33</sup>),\nועי\"ז מהפכים גם את \"אדום\" לטוב — כמחז\"ל<sup data-n=\"1038\">34</sup> \"עתיד חזיר ליטהר\" (המרמז גם על אדום, \"את החזיר זו אדום\") — בקיום היעוד<sup data-n=\"1039\">35</sup> \"ועלו מושיעים בהר ציון לשפוט את הר עשו והיתה לה' המלוכה\", במהרה בימינו ממש.\n<span data-k=\"q\">(משיחות ש\"פ תולדות וש\"פ וישלח, תשכ\"ז; ש\"פ ויצא תש\"מ)</span>",[["1033","29","וישלח לו, א."],["1034","30","ויק\"ר ספי\"ג."],["1035","31","תו\"א פרשתנו כ, ג. ובכ\"מ."],["1036","32","ל' אדה\"ז בתו\"א שם."],["1037","33","ולהעיר שלעת\"ל יאמרו ליצחק דוקא \"כי אתה אבינו\" (ישעי' סג, טז. שבת פט, ב. תו\"א ויצא כא, ג. כב, ג. ובכ\"מ)."],["1038","34","מרז\"ל בלשון זה הובא בשל\"ה פ' חיי שרה, ובכ\"מ (נסמנו בלקו\"ש חי\"ב ע' 175. וע\"ש באורך)."],["1039","35","עובדי' בסופו. — וראה לקו\"ש ח\"כ (ע' 153. ע' 165 הערה 69). חכ\"ה (ע' 175 הערה 71)."]]],[1301670181,"<h3>שיחה א</h3>\nא. בריש פרשתנו, בתחילת סיפור הליכת יעקב לחרן, נאמר \"ויצא יעקב מבאר שבע גו'\". ובביאור הלשון ויצא (ולא וילך — כבס\"פ לפני זה (פעמיים)) פירש רש\"י<sup data-n=\"1040\">1</sup> \"(לא הי' צריך לכתוב אלא וילך יעקב חרנה ולמה הזכיר יציאתו אלא) מגיד שיציאת צדיק מן המקום עושה רושם, שבזמן שהצדיק בעיר הוא הודה הוא זיוה הוא הדרה, יצא משם פנה הודה פנה זיוה פנה הדרה, וכן ותצא מן המקום האמור בנעמי ורות\"<sup data-n=\"1041\">2</sup>.\nומקורו של פירוש זה הוא בבראשית רבה עה\"פ<sup data-n=\"1042\">3</sup>, וז\"ל: \"בזמן שהצדיק בעיר הוא זיוה הוא הדרה יצא משם פנה זיוה פנה הדרה, ודכוותה ותצא מן המקום אשר היתה שמה וגו', ותצא וכי לא יצא מן המקום אלא היא. . כשהצדיק בעיר הוא זיוה הוא הדרה יצא משם פנה זיוה פנה הדרה, ניחא דתמן לא היתה שם אלא אותה הצדקת בלבד אלא הכא דהוי יצחק ורבקה, רבי עזרי' בשם רבי סימון אמר לא דומה זכותו של צדיק אחד לזכותו של שני צדיקים\".\nוצ\"ע, למה לא נחית רש\"י לשאול ולתרץ הא דאיתא במדרש על זה, ש­אע\"פ שאין הנידון דומה לראי', שכאן נשארו יצחק ורבקה במקום שיצא יעקב ממנו, משא\"כ גבי נעמי שלא נשאר שם אף צדיק אחד — שאינה דומה זכות ג'<sup data-n=\"1043\">4</sup> צדיקים לזכותם של שני צדיקים. — דהשאלה והתירוץ הם גם ע\"ד הפשט.\n[ודוחק גדול לפרש דס\"ל לרש\"י ש­מקום מושב יצחק ורבקה בזמן ההוא הי' בעיר חברון (וע\"ד מ\"ש במדרש שם<sup data-n=\"1044\">5</sup> לפנ\"ז \"כבר כתיב<sup data-n=\"1045\">6</sup> וישמע (יעקב) אל אביו ואל אמו, ומה ת\"ל ויצא יעקב מבאר שבע, אלא אמר, אבא בשעה שבקש לצאת לחוץ לארץ היכן הורשה לא מבאר שבע אף אני הריני הולך לבאר שבע אם נותן לי רשות הרי אני יוצא ואם לאו איני יוצא לפיכך צריך הכתוב לומר ויצא יעקב מבאר שבע\"). ולכן לא נחית רש\"י לבאר שאינה דומה זכותו של צדיק אחד כו', כי כיון שיצחק ורבקה התגוררו אז בחברון, ואילו יצי­את יעקב היתה \"מבאר שבע\", הרי לא נשאר אף צדיק אחד בעיר (בדיוק כמו גבי נעמי ורות), והמדרש דלעיל (מקורו של פרש\"י זה) ס\"ל שיצחק הי' גר אז בבאר שבע ולכן צריך לתרץ שאינה דומה כו'<sup data-n=\"1046\">7</sup> —\nכי<sup data-n=\"1047\">8</sup> בפשוטו של מקרא מפורש רק",[["1040","1","ריש פרשתנו."],["1041","2","רות א, ז."],["1042","3","פס\"ח, ו."],["1043","4","צע\"ק שבמדרש כאן אומר: אחד. . שני צדיקים."],["1044","5","ב\"ר שם ה בסופו."],["1045","6","תולדות כח, ז."],["1046","7","ראה נזר הקודש (השלם שם, ז סד\"ה והלא כמה) מפי' \"אב\"א\" (ר' אברהם ב\"ר אשר. נדפס בס' \"אור השכל\" על בראשית רבה — וויניציאה, שכ\"ח). מלאכת הקודש על פרש\"י כאן בסופו."],["1047","8","נוסף על מ\"ש במפרשים (ראה פי' אב\"א ופי' מהרז\"ו לב\"ר שם) שגם לדיעה זו, עיקר יציאתו (שעשתה רושם) היתה ממקום שדר בה בקביעות עם אבותיו, דהיינו בחברון, ולא בבאר שבע שלא הלך שם רק לשעה (וראה מפרשים שצויינו לקמן הערה 10). וראה חזקוני כאן \"באר שבע מקום קרוב לחב­רון הי'\". ולהעיר מהלשון במדרש הגדול כאן \"כ\"ז שהצדיק במדינה\"."]]],[1301670182,"ש\"ויעל [יצחק] משם באר שבע\"<sup data-n=\"1048\">9</sup> ולא נזכר שיצחק הלך מבאר שבע לחברון<sup data-n=\"1049\">10</sup>].\nב. לכאורה י\"ל שלפי פירוש רש\"י אין מקום לשאלה זו, שהרי רש\"י מוסיף על לשון המדרש בתחילת פירושו, וכותב \"מגיד שיציאת צדיק מן המקום עושה רושם\", דיש לפרש כוונתו בזה, שהגם שבדרך כלל יציאת הצדיק מן העיר גורמת לסילוק ההוד והזיו וההדר של העיר (שאין זה ענין של עשיית \"רושם\" בלבד), מ\"מ, בנדו\"ד, ביציאת יעקב מבאר שבע, עשתה יציאה זו (רק) רושם, כיון שהיו שם יצחק ורבקה.\nאבל לא גלאַטיק (חלק) לבאר כן כוונת רש\"י, שהרי כותב \"מגיד שיציאת צדיק מן המקום עושה רושם (וממשיך בחדא מחתא) שבזמן שהצדיק בעיר כו'\", ולפי הנ\"ל הי' יותר מתאים לומר \"מגיד שיציאת יעקב עשה רושם\", ואח\"כ להמ­שיך בלשון סתמי (בנוגע לצדיקים בכלל) \"שבזמן שהצדיק בעיר כו'\".\nומשמע, שגם מ\"ש רש\"י \"שיציאת צדיק מן המקום עושה רושם\" לא נאמר רק ביעקב אלא הוא גם כשלא נשאר בעיר צדיק אחר (כבנעמי) [והטעם ש­כותב הלשון \"עושה רושם\" — יש לבאר, כי הודה זיוה והדרה הם רק ענין של \"רושם\" לגבי עצם מציאות העיר].\nג. והנה תוכן פירוש זה הביא רש\"י גם בפירושו לרות שם, וז\"ל \"מגיד ש­יציאת צדיק מן המקום ניכרת ועושה רושם פנה זיוה פנה הדרה פנה שבחה של עיר וכן ויצא יעקב מבאר שבע\".\nוצ\"ע למה כאן בפי' עה\"ת הוצרך רש\"י לכפול \"בזמן שהצדיק בעיר הוא הודה הוא זיוה הוא הדרה, יצא משם פנה הודה כו'\", ולא כתב בקיצור (כבפי' לרות) שע\"י יציאת צדיק מן המקום פנה זיוה כו'<sup data-n=\"1050\">11</sup>.\nונראה לבאר שיש שינוי תוכני בין פירוש רש\"י בפרשתנו לפירושו ברות, דהכא (בפרשתנו) שרש\"י מקדים \"שבזמן שהצדיק בעיר הוא הודה הוא זיוה הוא הדרה\" (ואח\"כ ממשיך \"יצא משם פנה הודה כו'\") משמעו שהחידוש הוא בה­חיוב, שהצדיק הוא כל הודה וזיוה וה­דרה של העיר (ובדרך ממילא שע\"י יציאתו משם \"פנה הודה וכו'\"); משא\"כ ברות ששם כתב רק השלילה, שע\"י \"יציאת צדיק. . פנה זיוה פנה הדרה\", הרי לא מודגש שהיות הצדיק בעיר פועלת שינוי יסודי בעיר עד שזהו ההוד וכו' של העיר, ורק שהיציאה גורמת חסרון בעיר.\nומטעם זה כותב שם רש\"י \"ניכרת ועושה רושם\", משא\"כ בפרשתנו כתב רק \"עושה רושם\" — כי שם אין ההדגשה שהצדיק הוא זיוה והדרה של העיר אלא שיציאתו רק ניכרת ועושה רושם, משא\"כ בפרשתנו כוונתו להדגיש שזה שהצדיק נמצא בעיר הוא ההוד של המקום וכו'. ולפי זה י\"ל שכוונתו בלשון \"עושה רושם\" היא שזהו יותר מ\"ניכרת\", אלא שנשתנו לגמרי פני העיר (משא\"כ הלשון \"עושה רושם\" ברש\"י רות שם, שבא בהמשך להלשון \"ניכרת\", היא (ע\"ד הנ\"ל ס\"ב) רק למעט מתוקף הדבר).\nודורש ביאור — מהו טעם השינוי בין פירושו כאן לפירושו ברות.",[["1048","9","תולדות כו, כג."],["1049","10","ראה בכל הנ\"ל מלאכת הקודש ובאר בשדה על פרש\"י כאן."],["1050","11","והרי גם ברות רבה שם (פ\"ב, יב [ז]) איתא מאמר ר' עזרי' המובא בב\"ר כאן: גדול שבעיר הוא זיוה כו' וכן אתה מוצא ביעקב אבינו כו'."]]],[1301670183,"ד. ויובן כ\"ז בהקדם ביאור הגדרת השפעת הצדיק על העיר בפרש\"י, שגם בזה שינה מלשון המדרש, שבמדרש איתא \"שבזמן שהצדיק בעיר הוא זיוה הוא הדרה יצא משם פנה זיוה פנה הדרה\"<sup data-n=\"1051\">12</sup>, וברש\"י מוסיף גם \"הוא הודה\", ולא עוד אלא שמקדים \"הודה\"<sup data-n=\"1052\">13</sup> לפני \"זיוה\" ו\"הדרה\"<sup data-n=\"1053\">14</sup> (וכן ברש\"י רות לפנינו ליתא לתיבת \"פנה הודה\"<sup data-n=\"1054\">15</sup>).\nוהנה בפי' תיבות אלו רבו הפירו­שים<sup data-n=\"1055\">16</sup>, אבל כיון שרש\"י, פי' לתלמיד בן חמש למקרא, לא ביאר ופירט פירוש תיבות אלו, עכצ\"ל שס\"ל שמובן מלשו­נות הכתובים בתורה גופא — ועל הסדר, מן המאוחר אל המוקדם:\nהדרה: הלשון \"הדר\" מפורש בקרא — \"והדרת פני זקן\"<sup data-n=\"1056\">17</sup>, שפירושו — בפשטות — לשון כבוד<sup data-n=\"1057\">18</sup>. ועד\"ז בנדו\"ד, ש\"בזמן שהצדיק בעיר. . הוא הדרה\", כי כבודה של העיר הוא שיש בה דברים חשובים ויקרים, וכשצדיק נמצא בעיר נעשית עי\"ז עיר מכובדת, עיר שדר בה צדיק.\nזיוה: \"זיו\" הוא כמו \"זיו השמש\", שפירושו — מלשון אור, אלא שאין זה האור עצמו, אלא רק זיו והארה שמת­פשט ממנו להאיר לעולם. ועד\"ז בנדו\"ד, ש\"בזמן שהצדיק בעיר. . הוא זיוה\", כי ע\"י הנהגתו הטובה ומעשיו הטובים, ה\"ה מקרין אור וזיו על כל אנשי העיר, ו­לומדים ממעשיו כו'.\nהודה: גם \"הוד\" הוא מלשון אור (כמו זיו), כפי שמצינו בנוגע ל\"קרני הודו של משה\"<sup data-n=\"1058\">19</sup>, ובלשון הכתוב<sup data-n=\"1059\">20</sup> \"ונתת מהודך עליו\", \"זה קירון עור פנים\"<sup data-n=\"1060\">21</sup> (\"פני משה כחמה, פני יהושע כלבנה\"<sup data-n=\"1060\">21</sup>), אלא שב­\"הוד\" יש ענין נוסף לגבי \"זיו\" — ש\"קרן עור פניו\" פעל ש\"וייראו מגשת אליו\"<sup data-n=\"1062\">22</sup>, שמזה מובן, ש\"הוד\" אינו \"זיו\" סתם, אלא אור הגורם ליראה ופחד.\n[וכמובן גם בפשטות: זיו החמה וזיו הלבנה אינם פועלים רגש של יראה ופחד, ואדרבה — נהנים מאורם, ואילו קרני הוד של משה — פעל שייראו מ­גשת אליו].\nועד\"ז בנדו\"ד, ש\"בזמן שהצדיק בעיר הוא הודה\" — שנוסף על ה\"זיו\" שמקרין על אנשי המקום להשפיע על הנהגתם, ישנו גם ענין של \"הוד\", שמקרין אור כזה שפועל על אנשי העיר רגש של ביטול ויראה<sup data-n=\"1063\">23</sup>.\nאמנם כ\"ז הוא לפרש\"י, שמפרש לפי פשטות הענין, ש\"הוא הודה. . זיוה. .",[["1051","12","בילקוט לפנינו \"הוא זיוה הוא שבחה הוא הדרה\" [וראה ב\"ר הוצאת תיאודור­אלבק שם ב­חילופי נוסחאות — שרק לפי גירסא אחת ישנו ה­לשון \"הודה\", וגם שם הוא לא בהחיוב, \"הוא הודה\", אלא לגבי יציאת הצדיק, \"פנה הודה\"]."],["1052","13","וכ\"ה בדפוס ראשון, דפוס שני<sup data-n=\"e29\">*</sup> וכמה כת\"י רש\"י (שתח\"י). ובכמה כת\"י רש\"י (שתח\"י) מתחיל ב\"הוא זיוה\". ועד\"ז בדפוס רומא."],["1053","14","ובמדרש לקח טוב כאן \"הוא זיוה הוא שבחה הוא הודה\"."],["1054","15","ברות רבה איתא גם \"הוא הודה\", אבל מתחיל \"הוא זיוה\", ואח\"כ \"הוא הודה\", וכן אח\"כ \"פנה משם פנה זיוה פנה הודה\"."],["1055","16","ראה במפרשי המדרש ומפרשי רש\"י."],["1056","17","קדושים יט, לב."],["1057","18","וראה גם משפטים כג, ג ובפרש\"י. וראה פרש\"י ח\"ש כד, סד."],["1058","19","פרש\"י תשא לד, ל."],["1059","20","פינחס כז, כ."],["1060","21","פרש\"י שם."],["1060","21","פרש\"י שם."],["1062","22","תשא שם."],["1063","23","ראה רא\"ם וגו\"א בפרש\"י. יפה תואר (ובהשלם) לב\"ר שם."],["e29","*","ובהמשך לשון רש\"י \"פנה משם\" איתא \"פנה זיוה (ואח\"כ) פנה הודה כו'\"."]]],[1301670184,"הדרה\" של העיר היינו השפעתו ופעולתו על יושבי העיר (ולכן מתחיל רש\"י ב­\"הוד\" כנ\"ל);\nאבל לפי המדרש, זה שהצדיק פועל בעיר \"זיו והדר\" (\"הוא זיוה הוא הדרה\") לא קאי על הפעולה והשינוי בהנהגת אנשי העיר, אלא על זכות הצדיק — כפי שמסיים שם \"לא דומה זכותו של צדיק כו'\" — והיינו מה שהצדיק מגין על העיר<sup data-n=\"1064\">24</sup>, וכן שבזכותו של הצדיק ישנן השפעות טובות וברכה וכיו\"ב<sup data-n=\"1065\">25</sup>.\nה. ועפ\"ז מתורץ החילוק בין דברי המדרש ודברי רש\"י: לפי פרש\"י ה­מדובר הוא ע\"ד השפעת ופעולת הצדיק על הנהגת אנשי העיר ומעשיהם, ולכן אין צורך לתרץ זה שנשארו יצחק ורבקה — שהרי מפורש בפרש\"י בהמשך הכתובים כאן בנוגע ליצחק \"שכהו עיניו וכלוא בבית והרי הוא כמת\"<sup data-n=\"1066\">26</sup>, וכיון שיצחק הי' \"כלוא בבית\", לא בא במגע עם אנשי העיר לפעול שינוי בהנהגתם, להקרין עליהם מאורו וזיוו וכיו\"ב (אף שמובן שזכותו מגינה על העיר).\n[ובנוגע לרבקה, הרי נוסף לכללות הענין ד\"כל כבודה בת מלך פנימה\"<sup data-n=\"1067\">27</sup>, י\"ל שהיתה צריכה להמצא במחיצתו של יצחק, במשך כל הזמן, כיון ש\"כהו עיניו\", כדי לשמשו ולסייעו כו' (דבפשטות עש­תה זאת רבקה<sup data-n=\"1068\">28</sup>)].\nמשא\"כ כשמדובר בהגנה על העיר או השפעות הטוב והברכה, הרי כשנמצא יצחק בתוך העיר, אפילו במצב ד\"כלוא בבית\", ה\"ה משפיע בעיר, ואדרבא, להיותו נמצא במצב של \"כהו עיניו וכלוא בבית והרי הוא כמת ויצר הרע פסק ממנו\" — \"ייחד הקב\"ה שמו על יצחק\"<sup data-n=\"1069\">29</sup> (\"אע\"פ שלא מצינו במקרא שייחד שמו על צדיקים בחייהם לכתוב אלקי פלוני\"<sup data-n=\"1069\">29</sup>) — הרי פשיטא שגדלה זכותו של יצחק ביותר להביא הגנה וכל השפעת טוב להעיר שדר בה.\nו. ע\"פ כל הנ\"ל יש לבאר החילוק בין פרש\"י בפרשתנו ופרש\"י ברות:\nבפירושו ברות \"מגיד שיציאת צדיק מן המקום ניכרת ועושה רושם, פנה זיוה פנה הדרה פנה שבחה של עיר\", הכוונה בעיקר על ההגנה וההשפעה שבעיר (ע\"ד פירוש המדרש כאן), ולכן לא הקדים רש\"י שם \"פנה הודה\", ולאידך גיסא מוסיף \"(פנה) שבחה של עיר\", שבזה מדגיש שאין המדובר (כ\"כ) בפעולה והשפעה על הנהגת אנשי העיר, אלא ב\"שבחה\" של העיר, שע\"י יציאת צדיק פנה שבחה של העיר.\nמשא\"כ בפרשתנו כוונת רש\"י (כנ\"ל) להשפעת הצדיק על הנהגת ומעשי אנשי העיר, וזהו שמסיים כאן \"וכן ותצא מן המקום האמור בנעמי ורות\", וכוונתו כאן הוא לזה, שיציאה של נעמי ביחד עם",[["1064","24","ויש לומר, שלפרש\"י דבר זה שזכות הצדיק מגינה על עירו וכו' כבר ידעינן ממעשה סדום (וירא יח, כו ואילך). ובמילא לא מתאים כ\"כ לומר בשיי­כות לזכות הצדיק שעל העיר \"מגיד שיציאת צדיק מן המקום עושה רושם\" (אע\"פ ששם מדובר בעשרה צדיקים ויותר, וכאן — אפילו בנוגע לצדיק אחד)."],["1065","25","ראה פי' אב\"א הנ\"ל (הערה 7) על ב\"ר שם (הובא גם באמרי שפר על פרש\"י כאן). נזר הקודש השלם לב\"ר שם."],["1066","26","כח, יג."],["1067","27","תהלים מה, יד."],["1068","28","שאף שהיו לו רועים לצאנו ועבדים לטפל ברכושו וכו', לא מצינו שיהי' ליצחק עבד ע\"ד אליעזר עבד אברהם, ובפשטות תפקיד חשוב כזה, לטפל ביצחק באופן אישי, לא הי' ניתן לסתם עבד."],["1069","29","פרש\"י פרשתנו שם."],["1069","29","פרש\"י פרשתנו שם."]]],[1301670185,"רות פעלה ש\"פנה הודה. . זיוה. . הד­רה\", שהרי רות דבקה בחמותה (למרות שהיתה בתו של מלך<sup data-n=\"1071\">30</sup>) והלכה ל­התגייר<sup data-n=\"1072\">31</sup>, ודבר זה השפיע על אנשי המקום, ולכן ע\"י יציאתה של נעמי עם רות<sup data-n=\"1072\">31</sup> \"פנה הודה וזיוה והדרה\".\n[אבל בפירושו ברות, שפשטות הכ­תוב \"ותצא מן המקום\" קאי על נעמי, אין לומר בנוגע אלי' \"הוא הודה כו'\" (באופן הפועל יראה וביטול על אנשי המקום)<sup data-n=\"1074\">32</sup>, שהרי יציאתה מא\"י ביחד עם בעלה לא הי' דבר רצוי, והיתה הנהגה היפך יראת השם. אלא שמ\"מ שייך לומר שזכות מעשי' הטובים הגינה וגרמה להשפעת ברכה במקום, באופן שביציאתה פנה זיוה הדרה ושבחה של העיר].\nז. מיינה של תורה<sup data-n=\"1075\">33</sup> שבפירוש רש\"י:\nידוע מ\"ש באור החיים<sup data-n=\"1076\">34</sup> שהכתוב \"ויצא יעקב מבאר שבע וילך חרנה\" הוא רמז על ירידת הנשמה בגוף<sup data-n=\"1077\">35</sup>, ד\"באר שבע\" קאי על שורש הנשמה למעלה, ו\"חרן\" קאי על עולם הזה (\"חרן\" ע\"ש \"חרון אף של מקום (בעולם)\"<sup data-n=\"1078\">36</sup>). ודוקא ע\"י ירידת הנשמה בגוף, \"וילך חרנה\", הרי היא מתעלית למעלה יותר מכפי שהיתה לפני ירידתה<sup data-n=\"1079\">37</sup>, כהכלל \"ירידה צורך עלי'\".\nומרמז רש\"י בפירושו על \"ויצא יעקב מבאר שבע\"<sup data-n=\"1080\">38</sup> ענין נוסף בזה — \"לא הי' צריך לכתוב אלא וילך יעקב חרנה ולמה הזכיר יציאתו (מבאר שבע)\"<sup data-n=\"1080\">38</sup>, כלומר: עיקר החידוש בירידת הנשמה הוא בזה ש\"וילך חרנה\", הליכת הנשמה למקום של \"חרון אף של מקום\", שיש שם העלמות והסתרים על קיום התורה והמצות, ואעפ\"כ מתגברת היא על כל העלמות והסתרים אלו ועוסקת בתורה ובמצות, ויתירה מזו, שהיא פועלת בירור נה\"ב והגוף וחלקו בעולם ועושה דירה לו ית' בתחתונים<sup data-n=\"1079\">37</sup> — וא\"כ יש מקום להקשות למה מזכיר הכתוב כאן גם יציאתו מבאר שבע (שלא זהו עיקר הנסיון של הנשמה, ובמילא מובן שלא בגלל זה היא העלי' שלה)<sup data-n=\"1083\">39</sup>.\nוע\"ז מתרץ רש\"י — \"מגיד שיציאת צדיק מן המקום עושה רושם\", די\"ל הרמז בזה לענין ירידת הנשמה למטה, שעצם ה\"יציאה\" ממצב של דביקות בה­קב\"ה (שבו הייתה קודם ירידתה למטה) \"עושה רושם\" למעליותא ופעולה גדולה.",[["1071","30","פרש\"י רות שם, ב."],["1072","31","ראה פרש\"י שם, יט ותלכנה שתיהם \"כיון שנתנה דעתה להתגייר השוה אותה הכתוב לנעמי\"."],["1072","31","ראה פרש\"י שם, יט ותלכנה שתיהם \"כיון שנתנה דעתה להתגייר השוה אותה הכתוב לנעמי\"."],["1074","32","ובפרט שבאשה (נעמי) לא מתאים כ\"כ ענין ההשפעה מצד הנהגתה כו' בכללות העיר, דכל כבודה בת מלך פנימה (כנ\"ל בפנים), משא\"כ בנוגע לרות, שגיור בתו של מלך הוא דבר מפורסם כו'."],["1075","33","היום יום טז שבט."],["1076","34","פרשתנו כח, יד. הובא ונתבאר בקיצורים והערות לתניא ע' נז. ד\"ה ויצא תר\"ל (סה\"מ תר\"ל ע' כט)."],["1077","35","ועד\"ז על ירידת בנ\"י בגלות — ראה זהר ריש פרשתנו קמז, א. שם כג, ב (הובא באוה\"ת פרשתנו (כרך ה) תתנד, א). ב\"ר פס\"ח, יג. של\"ה פרשתנו רצב, ב."],["1078","36","פרש\"י ס\"פ נח."],["1079","37","נתבאר בארוכה בד\"ה ושבתי בשלום תש­ל\"ח (סה\"מ — מלוקט ח\"ב ע' קסב ואילך). וש\"נ. לקו\"ש חט\"ו ע' 245 ואילך."],["1080","38","להעיר שבדפוס ראשון דפרש\"י (ובכמה כת\"י רש\"י שתח\"י) הד\"ה הוא \"ויצא יעקב מבאר שבע\", ובהתחלת פירושו \"למה הזכיר יציאתו מן המקום\"."],["1080","38","להעיר שבדפוס ראשון דפרש\"י (ובכמה כת\"י רש\"י שתח\"י) הד\"ה הוא \"ויצא יעקב מבאר שבע\", ובהתחלת פירושו \"למה הזכיר יציאתו מן המקום\"."],["1079","37","נתבאר בארוכה בד\"ה ושבתי בשלום תש­ל\"ח (סה\"מ — מלוקט ח\"ב ע' קסב ואילך). וש\"נ. לקו\"ש חט\"ו ע' 245 ואילך."],["1083","39","באוה\"ח הנ\"ל \"ואומרו מבאר שבע ממקום שממנו יצאו הנשמות יקרא באר מים חיים ושבע ירמוז אל שבועת ה' אשר תשבע הנפש ביציאתה שלא לעבור על דברי תורה\". אבל לפ\"ז אינו חלק מגוף הירידה אלא רק הנתינת כח על העבודה או על העלי' (ראה במקומות שבהערה 34). משא\"כ לפי המבואר בפנים."]]],[1301670186,"דכיון שכאשר הצדיק הוא בעיר — \"עיר אלקינו\" — \"הוא הודה הוא זיוה הוא הדרה\", שכל מציאות הנשמה היא מה שהיא נהנית מזיו השכינה<sup data-n=\"1084\">40</sup> ויש לה אהבה ויראה מאלקות, וע\"י יציאתה מ\"עיר אלקינו\", \"פנה הודה פנה זיוה פנה הדרה\"<sup data-n=\"1085\">41</sup> — הרי שעצם יציאת הנשמה משרשה ומקורה (\"באר שבע\") היא מסירת נפש ולכן \"עושה רושם\"<sup data-n=\"1086\">42</sup>.\nוכיון שכן, ברור שבזכות היציאה עצמה, ראוי כאו\"א מישראל לכך ש­הקב\"ה יחזירו למקומו האמיתי, \"ושבתי בשלום אל בית אבי והי' הוי' לי לאלקים וגו'\"<sup data-n=\"1087\">43</sup>, בגאולה האמיתית וה­שלימה על ידי משיח צדקנו, תיכף ומיד ממש.\n<span data-k=\"q\">(משיחות ש\"פ ויצא תשכ\"ה, תשמ\"ח)</span>",[["1084","40","רמב\"ם הל' תשובה פ\"ח ה\"ב. מברכות יז, א."],["1085","41","ראה תניא פל\"ז (מח, סע\"א)."],["1086","42","ויש לומר שזהו שרש\"י מסתייע \"וכן ותצא מן המקום האמור בנעמי ורות\", דשם אין המדובר ביציאה מא\"י לחו\"ל (כבפרשתנו בנוגע ליעקב) — שהיא ע\"ד יציאת הנשמה משרשה ומקורה וירידתה למטה בגוף — אלא להיפך, יציאה מחו\"ל לא\"י. וגם שם מדגיש הכתוב \"ותצא מן המקום\", כי עיקר החידוש הוא עצם היציאה ממקומו של האדם, וגבי רות הי' זה בעקירתה ויציאתה ממקומה ע\"מ להתגייר."],["1087","43","פרשתנו כח, כא. וראה בארוכה ד\"ה ושבתי בשלום הנ\"ל."]]],[1301670187,"<h3>שיחה ב</h3>\nא. תנן<sup data-n=\"1088\">1</sup>: \"תפלת השחר עד חצות. . תפלת המנחה עד הערב. . תפלת הערב אין לה קבע\". וכבר עמדו במפרשים<sup data-n=\"1089\">2</sup> על טעם השינוי, שגבי ק\"ש התחיל התנא<sup data-n=\"1090\">3</sup> ב­ק\"ש של ערבית (\"מאימתי קורין את שמע בערבין\"), ואילו כאן גבי תפלה נשנו ה­תפלות בסדר דשחרית מנחה וערבית.\nוביותר יוקשה להמ\"ד בגמ'<sup data-n=\"1090\">3</sup>, שהטעם שהתחיל בק\"ש של ערבית הוא כ\"ברייתו של עולם דכתיב<sup data-n=\"1092\">4</sup> ויהי ערב ויהי בקר יום אחד\" [ולא משום דסמיך אקרא \"בשכבך ובקומך\", ש\"א\"כ אינו מקפיד קרא אלא אק\"ש\"<sup data-n=\"1093\">*4</sup>], וא\"כ גם בסדר התפלות הו\"ל ל­מיתני הכי.\nוביארו, דשאני תפלה מק\"ש, דמצד עצם התקנה דתפלה הרי סדר התפלות הוא — שחרית מנחה ערבית: הן למ\"ד<sup data-n=\"1094\">5</sup> \"תפלות אבות תקנום\" — הרי אברהם תיקן תפלת שחרית יצחק תפלת מנחה ויעקב תפלת ערבית<sup data-n=\"1095\">6</sup>, והן למ\"ד<sup data-n=\"1095\">6</sup> \"תפלות כנגד תמידין תקנום\", הרי שחרית ומנחה הן כנגד שני התמידים, וערבית היא כנגד \"אברים ופדרים שלא נתעכלו מבערב קרבים והולכים כל הלילה\"<sup data-n=\"1097\">7</sup>, ונמצא ש­תפלת ערבית היא התפלה האחרונה, כמו שהקרבת אברים ופדרים בלילה היא השלמה לקרבנות שנקרבו ביום.\nולכאורה צ\"ע מהא דאיתא בגמ'<sup data-n=\"1098\">8</sup>: \"טעה ולא התפלל ערבית מתפלל בשח­רית שתים, שחרית מתפלל במנחה שתים. . איבעיא להו טעה ולא התפלל מנחה מהו שיתפלל ערבית ב', את\"ל טעה ולא התפלל ערבית מתפלל שחרית ב' משום דחד יומא הוא דכתיב<sup data-n=\"1092\">4</sup> ויהי ערב ויהי בוקר יום אחד אבל הכא תפלה במקום קרבן היא וכיון דעבר יומו בטל קרבנו, או דילמא כיון דצלותא רחמי היא כל אימת דבעי מצלי ואזיל\".\nהרי מפורש, דסדרן של ג' תפלות הוא — ערבית שחרית מנחה, כפי סדר \"ברייתו של עולם\" (כמו ק\"ש), \"חד יומא. . ויהי ערב ויהי בוקר יום אחד\", ולכן סלקא דעתך אמינא שאי אפשר להשלים תפלת מנחה בתפילת ערבית שלאחרי', כיון שכ­בר עבר יומו<sup data-n=\"1100\">9</sup> (וגם לפי המסקנא דלא אמ­רינן \"עבר יומו בטל קרבנו\", ה\"ז רק לפי<sup data-n=\"1101\">10</sup>",[["1088","1","ברכות רפ\"ד."],["1089","2","פני יהושע וצל\"ח ברכות רפ\"ד. סמיכת חכמים שם (לתוד\"ה תפלת). ועוד. ולהעיר מלבוש שבהערה *16."],["1090","3","ריש ברכות."],["1090","3","ריש ברכות."],["1092","4","בראשית א, ה."],["1093","*4","תוד\"ה אי הכי ברכות שם."],["1094","5","ברכות כו, ב. ועד\"ז בירושלמי שם פ\"ד ה\"א (ושם הלשון \"תפילות מאבות לימדום\"). ב\"ר פרש­תנו (פס\"ח, ט)."],["1095","6","ברכות שם. ועד\"ז בירושלמי וב\"ר שם."],["1095","6","ברכות שם. ועד\"ז בירושלמי וב\"ר שם."],["1097","7","ברכות שם (וראה רש\"י שם ד\"ה ופדרים \"וכנגדן תקנו תפלת ערבית\". ועד\"ז ברמב\"ם הל' תפלה פ\"א ה\"ו. ועוד). ירושלמי וב\"ר שם (וראה מפרשים שם)."],["1098","8","ברכות כו, א."],["1092","4","בראשית א, ה."],["1100","9","וראה השקו\"ט בפני יהושע ברכות שם, ד­לכאורה הא ד\"תפלה במקום קרבן\" הוא טעם להיפך, שיכולים להשלים מנחה בערבית, כמו הקטרת איברי התמיד בלילה, ולאידך — שא\"א להשלים ערבית בשחרית ושחרית במנחה שלאחרי', ע\"ש באורך (וראה גם צל\"ח לתוס' שם ד\"ה איבעי' להו). — וראה מאירי שבהערה הבאה."],["1101","10","אבל במאירי ברכות שם, דזה שאין אומרים עבר יומו בטל קרבנו הוא לפי ש\"אף איברים ופדרים שמתעכלין כל הלילה מקרבן היום שעבר הם\"."]]],[1301670188,"ש\"צלותא רחמי היא כל אימת דבעי מצלי ואזיל\").\nוכן מצינו בגמ'<sup data-n=\"1102\">11</sup>: \"יכול יתפלל אדם כל היום כולו כבר מפורש על ידי דני­אל<sup data-n=\"1103\">12</sup> זמנין תלתא וגו'. . יכול יהא כוללן בבת אחת, כבר מפורש על ידי דוד ד­כתיב<sup data-n=\"1104\">13</sup> ערב ובקר וצהרים וגו'\" — הרי ש­סדר התפלות הוא \"ערב ובקר וצהרים\"<sup data-n=\"1105\">14</sup>.\nב. ויש לומר הביאור בזה:\nידוע הכלל בהלכה<sup data-n=\"1106\">15</sup>, ד\"במעשה ברא­שית היום הולך אחר הלילה\", ו\"בקדשים לילה הולך אחר היום\".\nועפ\"ז יש לומר, ששני הסדרים בג' התפלות, אם תפילת ערבית היא סיום ג' התפלות (לילה הולך אחר היום), או שהיא התחלת ג' התפלות (היום הולך אחר הלי­לה), תלוי אם תפלה היא בגדר \"קדשים\" או בגדר \"מעשה בראשית\".\nויש לומר דתרווייהו איתנהו בה, שיש בענין התפלה גדר של \"קדשים\", שמצד זה \"לילה הולך אחר היום\"<sup data-n=\"1107\">16</sup> וסדר התפלות הוא שחרית מנחה ערבית; וגם גדר של \"מעשה בראשית\" שבזה \"היום הולך אחר הלילה\", ולפ\"ז סדר התפלות הוא — ער­בית שחרית מנחה<sup data-n=\"1108\">*16</sup>.\nדהנה, במהותה של תפלה מצינו שני ענינים:\nמחד גיסא התפלה היא \"עבודה שב­לב\", וכמרז\"ל<sup data-n=\"1109\">17</sup> שחובת התפלה נלמדת ממ\"ש<sup data-n=\"1110\">18</sup> \"ולעבדו בכל לבבכם\" — \"איזו היא עבודה שהיא בלב הוי אומר זו תפ­לה\"; ולאידך, הפירוש הפשוט של \"תפלה\" הוא מלשון בקשה, והיינו מה שהאדם מבקש את צרכיו מאת הקב\"ה.\nדשני ענינים אלה — עבודה שבלב ובקשת צרכיו — שונים זמ\"ז בתכלית, שהרי \"עבודה שבלב\" פירושה (כפשטות הלשון) — לעבוד את ה', שענינה קבלת עול מלכות שמים ודביקות בה'<sup data-n=\"1111\">19</sup>, וכד­איתא במשנה<sup data-n=\"1112\">20</sup> ש\"חסידים הראשונים היו שוהין שעה אחת ומתפללין כדי שיכוונו לבם לאביהם שבשמים\", ומבואר בטור<sup data-n=\"1113\">21</sup>, \"",[["1102","11","ברכות לא, א. וכן בירושלמי ברכות שם. וראה ברכות כ, ב (אבל ראה רש\"י שם ד\"ה ה\"ג והגהת הב\"ח שם. וראה תוד\"ה בתפלה שם)."],["1103","12","דניאל ו, יא, שם, יד."],["1104","13","תהלים נה, יח. — הובא גם ברמב\"ם הל' תפלה שם. וראה שם ה\"ח. ובשאילתות פ' לך (שאילתא ח) נלמד עצם החיוב \"לצלויי תלתא זימני ביומא\" מכתוב זה."],["1105","14","להעיר מהדיעה בירושלמי וב\"ר שם, שג' תפלות הם כנגד \"ג' פעמים שהיום משתנה\". ע\"ש. ולהעיר, שבב\"ר שם נקט בדיעה זו כהסדר ערבית שחרית מנחה, וראה יפה תואר (השלם) שם, ש\"נקט. . כסדר היום שהיום הולך אחר הלילה\"."],["1106","15","חולין פג, סע\"א."],["1107","16","וראה צל\"ח הנ\"ל הערה 2."],["1108","*16","ולהעיר מלבוש או\"ח ר\"ס פט: ג' תפלות כו' ערב ובקר וצהרים כו' ותקנו אותן כו' כנגד התמידין כו' נתקנו מימות האבות כו' לפיכך נפרש אותן ג\"כ על הסדר שנתקנו, זמן תפלת השחר כו'."],["1109","17","תענית בתחילתה. ירושלמי ברכות שם. וכן בספרי עקב (יא, יג). הובא ברמב\"ם ריש הל' תפלה (כדלקמן סעיף ג)."],["1110","18","עקב שם."],["1111","19","וכהפירוש ב\"תפלה\" מלשון התחברות (תו\"א ר\"פ תרומה (עט, סע\"ד). אוה\"ת פרשתנו (כרך ה תתסח, א), שם ויחי שפ, א (ע\"פ פרש\"י פרשתנו ל, ח). ובכ\"מ)."],["1112","20","ברכות ל, ב. ובגמ' שם (לב, ב. הובא בהל' ת\"ת לאדה\"ז שבהערה הבאה) \"ששוהין ט' שעות ביום בתפלה\"."],["1113","21","או\"ח סצ\"ח. נעתק בשו\"ע (ודאדה\"ז) שם. וראה גם הל' ת\"ת לאדה\"ז (פ\"ד ס\"ה), ושם (מס' חרדים והשל\"ה): \"ולא היו חוששין לביטול תורה אף שת\"ת כנגד כולם\" לפי ש\"מצות הדביקות האמיתית ביראה ואהבה היא גדולה ממצות ת\"ת וקודמת אלי'\"."]]],[1301670189,"שהיו מתבודדים ומכוונין בתפלתן עד שהיו מגיעים להתפשטות הגשמיות ולהת­גברות רוח השכלית עד שהיו מגיעים קרוב למעלת הנבואה\", ומובן בפשטות, שבהיותם במצב זה של התקשרות \"לאדון הכל ב\"ה ביראה ואהבה עזה ודביקות אמיתית\"<sup data-n=\"1114\">22</sup>, אין חושבים ע\"ד צרכי עצ­מם<sup data-n=\"1115\">23</sup>.\nאלא שהם הם שני הגדרים שבתפלה: \"עבודה שבלב\", שהיא הדביקות בה', ה\"ז כמו גדר \"קדשים\"<sup data-n=\"1116\">24</sup> [דכמו ענין הקרבנות כפשוטו, שהוא הקרבה לה' ובבית ה', כך הוא ענין התפלה, מה שהאדם עומד לפני ה'<sup data-n=\"1117\">25</sup>, וגם תוכן העבודה הוא הדביקות בה' (ע\"ד הקרבה לה')]; ובקשת הצרכים שב­תפלה ה\"ז ע\"ד וענין \"מעשה בראשית\", שהאדם חושב ע\"ד צרכי עצמו.\nג. והנה, להלכה למעשה נקטינן (כנ\"ל) שסדר התפלות הוא ערבית שחרית ומנחה, שלכן ליכא אפילו קס\"ד בגמ'<sup data-n=\"1101\">10</sup> שזה ש­יכולים להשלים תפלת מנחה בתפילת ערבית הוא להיותה הסיום של ג' התפלות, ומוכח שסדר התפלות להלכה הוא ערבית שחרית מנחה.\nויש לומר טעם הדבר, כי ע\"פ הלכה, החיוב והדין דמצות התפלה הוא בקשת צרכיו (שהוא גדר \"מעשה בראשית\" שב­תפלה כנ\"ל), שזהו עצם החפצא דתפלה; משא\"כ \"עבודה שבלב\" הוא רק תיאור מצב הגברא המתפלל, דכדי שתהי' החפ­צא דבקשת צרכיו כדבעי צריך הגברא להיות במצב של \"עבודה שבלב\", ובלעדה חסר בעצם הבקשה, אבל מ\"מ אין זו מהות התפלה.\nועפ\"ז יש לבאר דברי הרמב\"ם בריש הל' תפלה: \"מצות עשה להתפלל בכל יום שנאמר<sup data-n=\"1119\">26</sup> ועבדתם את ה' אלקיכם, מפי השמועה למדו שעבודה זו היא תפלה שנאמר<sup data-n=\"1110\">18</sup> ולעבדו בכל לבבכם אמרו חכ­מים<sup data-n=\"1121\">27</sup> אי זו היא עבודה שבלב זו תפלה\".\nוכבר הקשו במפרשים<sup data-n=\"1122\">28</sup>, אמאי הביא הרמב\"ם הכתוב \"ועבדתם את ה' אלקיכם\", הרי בלאה\"כ צריך להביא הכתוב \"ולעב­דו בכל לבבכם\" שרק ממנו למדים דקאי על תפלה, \"אי זו היא עבודה שבלב זו תפלה\" (משא\"כ בכתוב \"ועבדתם את ה' אלקיכם\" שלא נתפרש בו \"לב\", אין הכרח דקאי על תפלה דוקא) — וא\"כ הו\"ל ל­הביא רק הכתוב ד\"ולעבדו בכל לבב­כם\"<sup data-n=\"1123\">29</sup>.\nויש לומר ע\"פ מ\"ש בקרית ספר<sup data-n=\"1124\">30</sup>, דמ­הכתוב \"ועבדתם גו'\" למדים ש\"מצות עשה להתפלל בכל יום\", כי \"סמיך אסופי' ד­",[["1114","22","ל' אדה\"ז בהל' ת\"ת שם."],["1115","23","ראה תקו\"ז ת\"ו (כב, א) \"צווחין בצלותין כו' ככלבים הב הב לנו מזונא כו'\". או\"ת להה\"מ ר\"פ ויגש ועוד. וראה לקו\"ש חכ\"ג ע' 217 ואילך. וש\"נ."],["1116","24","וכנרמז גם בטור שם, שבהמשך הסימן מאריך ע\"ד זה ש\"התפלה היא במקום הקרבן. . ולכן צריך ליזהר שתהא דוגמת הקרבן בכוונה כו'\". ע\"ש באורך (ונעתק בשו\"ע (ודאדה\"ז) שם). וראה לקו\"ש חלק ל\"ב ע' 39.\nולהעיר ממרז\"ל (הובא בסהמ\"צ להרמב\"ם מ\"ע ה'. כס\"מ הל' תפלה פ\"א ה\"ג) עבדהו במקדשו."],["1117","25","טושו\"ע (ודאדה\"ז) שם. וראה שבת י, א \"כעבדא קמי' מרי'\" (וכן בטושו\"ע (ודאדה\"ז) או\"ח סו\"ס צה). ברכות לג, א: עומד לפני ממה\"מ כו'. שו\"ע אדה\"ז או\"ח סי' קד ס\"ב. ועוד."],["1101","10","אבל במאירי ברכות שם, דזה שאין אומרים עבר יומו בטל קרבנו הוא לפי ש\"אף איברים ופדרים שמתעכלין כל הלילה מקרבן היום שעבר הם\"."],["1119","26","משפטים כג, כה."],["1110","18","עקב שם."],["1121","27","נסמן בהערה 17."],["1122","28","כס\"מ ועוד."],["1123","29","ובמנין המצות בריש ס' היד (מ\"ע ה) הובא רק הכתוב ד\"ועבדתם\". וגם בסהמ\"צ שם: א) לא הביא בתחילת המצוה הכתוב ד\"ולעבדו\". ב) גם בהמשך הענין מעתיק רק ל' הספרי \"ולעבדו זו תפלה\", ולא כל הדרשה \"אי זו היא עבודה שבלב כו'\" [ואדרבה, ממשיך \"ואמרו גם כן ולעבדו זו תלמוד\". ונת' בשיחת ש\"פ בחוקותי תשד\"מ]."],["1124","30","להמבי\"ט לרמב\"ם שם. נעתק בלח\"מ שם."]]],[1301670190,"קרא דכתיב וברך את לחמך ואת מימיך וגו' דהוא צורך כל יום הכי נמי תפלה ב­כל יום\" (\"למה<sup data-n=\"1125\">31</sup> שאתה שואל צרכיך בה\").\nועפ\"ז י\"ל, שהחילוק בין שני הכתובים ד\"ועבדתם גו'\" ו\"ולעבדו בכל לבבכם\" הוא: עיקר ההדגשה בכתוב \"ועבדתם גו'\" היא על בקשת הצרכים (כמ\"ש לאח\"ז \"וברך את לחמך גו'\"), ואילו בכתוב \"ול­עבדו בכל לבבכם\" נאמר רק הענין דעבו­דה שבלב. וזהו שמשמיענו הרמב\"ם<sup data-n=\"1126\">32</sup> בזה שהקדים הכתוב ד\"ועבדתם גו'\", כי מהות מצות התפלה היא בקשת צרכיו, וזה שתפלה היא \"עבודה שבלב\" הוא רק כדי שבקשה זו תהי' כדבעי, \"בבקשה ובתחי­נה\" (כלשון הרמב\"ם<sup data-n=\"1127\">33</sup>), שזהו רק כשדיבור התפלה הוא מתוך רגש הלב, ולכן צריך האדם לעורר את לבו כדבעי, שאז בקשת צרכיו היא כמתאים להמבקש צרכיו מאת המלך.\n[ע\"ד שמצינו בתפלה גופא, שסדר ה­תפלה הוא, שבתחילה \"מגיד שבחו של הקדוש ברוך הוא ואחר כך שואל צרכיו שהוא צריך להם בבקשה ובתחינה ואחר כך נותן שבח והודי' לה' על הטובה שהש­פיע לו\"<sup data-n=\"1128\">34</sup>, זאת אומרת, שכדי שבקשת צרכיו תהי' באופן המתאים, צריך להק­דים לפני' סידור שבחו של מקום (וכן ל­סיים בשבח כו')].\nד. ביאור שני הסדרים הנ\"ל בג' תפ­לות בעבודת השם, יובן בהקדם הביאור הפנימי בכלל הנ\"ל ד\"במעשה בראשית היום הולך אחר הלילה\", ו\"בקדשים לילה הולך אחר היום\", שהם שני סדרים בעבו­דת ה' [שהרי הכלל ד\"במעשה בראשית היום הולך אחר הלילה\" קאי גם בעניני מצוה ועבודת השם הקשורים בזמן, שהיום הולך אחר הלילה].\nהסברת הענין<sup data-n=\"1129\">35</sup>:\n\"מעשה בראשית\" מורה על העבודה להמשיך קדושה בעניני העולם, ו\"קדשים\" היא העבודה בענינים שהקדושה היא ב­התגלות בהם. וכך הוא בעבודת כאו\"א בפרט, שהאדם כלול מנשמה וגוף: \"קד­שים\" מורה על העבודה המביאה לידי גילוי קדושת הנשמה, שהיא \"חלק אלקה ממעל ממש\"<sup data-n=\"1130\">36</sup>; ו\"מעשה בראשית\" היא עבודת זיכוך הגוף (וכן עניני העולם).\nוזהו גם טעם ההבדל, ש\"במעשה ברא­שית היום הולך אחר הלילה\", ו\"בקדשים לילה הולך אחר היום\":\nב\"קדשים\" (גם) ההתחלה היא ב\"יום\" ואור, כיון שכל עיסוקו הוא בדברים ש­הקדושה בהם היא בהתגלות (אור וגי­לוי); ואח\"כ עולה מחיל אל חיל, להוסיף ולעלות באור הקדושה (כהכלל<sup data-n=\"1131\">37</sup> מעלין בקודש), שמזה מובן, שלא זו בלבד שה­\"לילה\" הבא לאחרי ה\"יום\" (בקדשים) הוא ג\"כ ענין של אור וקדושה, אלא עוד זאת, ש\"לילה\" זה הוא למעלה מאור היום ש­",[["1125","31","ל' הלח\"מ."],["1126","32","להעיר מהשינויים בל' הרמב\"ם: בסהמ\"צ \"שצונו לעבדו\" (ורק בהמשך הענין \"שהוא ציווי לתפלה\"); במנין המצות בריש ס' היד \"להתפלל אליו\"; במנין המצות על סדר ההלכות (ובכותרת להל' תפלה) \"לעבוד. . בתפלה\"; בריש הל' תפלה \"מ\"ע להתפלל\"."],["1127","33","שם ה\"ב. — וראה בארוכה לקו\"ש חכ\"ב ע' 116 ואילך."],["1128","34","רמב\"ם שם."],["1129","35","להעיר מהמבואר בכ\"מ בתיווך שני הענ­ינים, אם חשך קדם לאור או להיפך (וכן אם לילה קדם ליום או להיפך) ע\"ד החסידות — ראה ס' ה­ערכים חב\"ד ערך אור ביחס לחשך סעיף ב ואילך. וש\"נ."],["1130","36","ל' התניא רפ\"ב."],["1131","37","ברכות כח, א. וש\"נ."]]],[1301670191,"לפניו\n— כי ב\"אור\" גופא יש שני אופנים: אור היום, דהיינו התגלות אלקית שיכולה ל­התקבל אצל האדם באופן שנשאר במצי­אות; ואור עליון יותר, אור סתום, הנקרא בשם \"חושך\"<sup data-n=\"1132\">38</sup> כי הוא למעלה מתפיסת האדם, וכאשר מדריגה זו מתגלה ה\"ה פועלת על האדם שיתבטל ממציאותו<sup data-n=\"1133\">39</sup>;\nוזהו ש\"בקדשים לילה הולך אחר ה­יום\", שההתחלה היא בענין האור הגלוי, ואח\"כ מגיעים לאור נעלה יותר, אור סתום, שלמעלה מגדר נבראים.\nמשא\"כ ב\"מעשה בראשית היום הולך אחר הלילה\", וכסדר \"ברייתו של עולם. . ויהי ערב (ואח\"כ) ויהי בוקר\", \"ברישא חשוכא והדר נהורא\"<sup data-n=\"1134\">40</sup> — כי מטרת עבודה זו היא הפעולה בעולם, ולכן התחלת ה­עבודה היא מ\"לילה\", כי בתחילת העבודה העולם הוא במצב של \"חושך\", עולם מ­לשון העלם<sup data-n=\"1135\">41</sup>, שאין הקדושה נראית ונג­לית בו; וע\"י עבודת האדם באים מ\"לילה\" ל\"יום\", שמאירים את החושך, עד שמהפ­כים את החושך עצמו לאור.\nה. ומזה יובן גם בנוגע לענין התפלה, שיש בו שני סדרים אלו:\nבעבודת התפלה ישנם<sup data-n=\"1136\">42</sup>: היגיעה לג­לות אור נשמתו, ע\"י התעוררות אהבת ה' ויראתו בלבו (וזוהי ה\"עבודה שבלב\" שב­תפלה); ואח\"כ ישנו הדיבור דתפלה, שאין כוונת הלב מספיקה, אלא צריך לבטא את תיבות התפלה בשפתים הגשמיים<sup data-n=\"1137\">43</sup>, וכמ­בואר בארוכה בספר התניא<sup data-n=\"1138\">44</sup>, שזהו לפי שתכלית התפלה היא לזכך את הגוף וה­נפש הבהמית שבאדם, שלזה צריכים (גם) הדיבור דתפלה.\nוהם שני הסדרים שבג' התפלות:\nבענין דביקות הנשמה באלקות, הרי התחלת עבודת היום היא בתפילת שחרית, יום ואור; והסיום ושלימות דדביקות זו הם בתפילת ערבית, שאז מגיע האדם ל­אור הסתום שלמעלה מגדר הנבראים, הפועל בו מצב של ביטול מוחלט ל­הקב\"ה.\n[ונמצא, שמצד גדר זה שבתפילה, תפי­לת ערבית היא למעלה מתפילת שחרית ומנחה<sup data-n=\"1139\">45</sup>; וזה מתאים עם הא דדוקא יעקב אבינו תיקן תפילת ערבית, כי יעקב הוא בחיר שבאבות<sup data-n=\"1140\">46</sup>].\nאבל להלכה נקטינן (כנ\"ל), שסדר ג' התפלות הוא ערבית שחרית ומנחה, כי תכלית הכוונה של בריאת העולם וירידת הנשמה למטה היא לעשות לו ית' דירה בתחתונים דוקא, כמבואר בארוכה בספר התניא<sup data-n=\"1141\">47</sup>, דהיינו בעוה\"ז הגשמי שהוא \"תחתון. . שאין תחתון למטה ממנו בענין הסתר אורו ית' וחושך כפול ומכופל\",",[["1132","38","בחי' \"ישת חשך סתרו\" (ראה — לענין תפי­לת ערבית — אוה\"ת מסעי ס\"ע א'שצז. ובביאוה\"ז להצ\"צ (ע' צא) \"כחשיכה כאורה\")."],["1133","39","וגם מטעם זה נקרא \"חושך\", מצד הביטול והעדר המציאות הנפעל עי\"ז בהאדם."],["1134","40","שבת עז, ב."],["1135","41","לקו\"ת שלח לז, ד. ובכ\"מ."],["1136","42","ראה בארוכה בזה קונטרס העבודה פ\"א. ד\"ה אין עומדין תרע\"ח. לקוטי דיבורים ח\"ד בהוס­פות (תשעו, א ואילך). ועוד."],["1137","43","שו\"ע או\"ח סק\"א ס\"ב ובמג\"א שם סק\"ב. שו\"ע אדה\"ז שם (ס\"ב וס\"ד)."],["1138","44","רפל\"ז (מז, א ואילך). שם רפל\"ח. ועוד."],["1139","45","ראה זח\"א קלג, א. נת' בביאורי הזהר לאדמו\"ר האמצעי (יג, ד ואילך) ולהצ\"צ (ע' פה ואילך). ושם, שזהו הטעם ש\"תפלת ערבית רשות\" (ברכות כז, ב), כי היא למעלה מחובה. ע\"ש. וראה גם לקו\"ש חכ\"ה ע' 156 ואילך. וש\"נ. וראה שם בביאור ב' הענינים שבתפילת ערבית (סיום עבודת היום או התחלתה) ע\"ד החסידות."],["1140","46","ראה ב\"ר ר\"פ עו. זהר שבהערה הקודמת. ועוד."],["1141","47","פל\"ו."]]],[1301670192,"וזהו ע\"י שמהפכים את חושך העולם ל­אור;\nוכן הוא בענין התפלה, שעיקר ענין התפלה הוא הדיבור שבתפלה, שעל ידו נעשה זיכוך הגוף והנפש הבהמית, ה­עבודה במקום החושך דוקא, ולכן סדר ה­תפלות הוא ערבית שחרית מנחה, שה­עבודה היא במקום החושך, ובזה עולים מדרגא לדרגא, בהמשכת קדושה בחושך, עד שמהפכים את החושך לאור.\nולפי סדר זה, תפלת ערבית היא התח­לת העבודה, והסיום ושלימות דג' תפילות הוא בתפלת מנחה. וזה מתאים עם המבואר בכ\"מ<sup data-n=\"1142\">48</sup> שעיקר המעלה דתפלת מנחה היא בזה שזמנה הוא באמצע היום, כשאדם עסוק בפרנסתו כו' ומ\"מ מפסיק ועומד להתפלל, והיינו מעלת העבודה כפי שהיא קשורה עם עניני העולם דוקא.\n[ושני סדרים אלו נרמזים גם בנוסח ברכות ק\"ש של ערבית — \"גולל אור מפני חושך וחושך מפני אור\"<sup data-n=\"1143\">49</sup>: \"גולל אור מפני חושך\" מדגיש שהחושך (לילה) בא לאחרי האור (יום), שזהו לפי הסדר דת­פלת ערבית היא סיום עבודת היום; \"וחו­שך מפני אור\" היינו מה שחושך הלילה הוא הקדמה לאור היום שלאחריו, כהסדר ערבית שחרית ומנחה].\nויש לומר, שזהו גם הטעם שתפלת מנחה קשורה עם אליהו הנביא, מבשר הגאולה<sup data-n=\"1144\">50</sup>, \"לעולם יהא אדם זהיר בתפלת המנחה שהרי אליהו לא נענה אלא בתפלת המנחה\"<sup data-n=\"1145\">51</sup> — כי זהו העילוי דימות המשיח, שאז \"יזדכך גשמיות הגוף והעולם ויוכלו לקבל גילוי אור ה' שיאיר לישראל\"<sup data-n=\"1146\">52</sup>, ובאופן ש\"יגיה חשך האומות גם כן\"<sup data-n=\"1146\">52</sup>, שהעולם כולו ייעשה דירה לו ית'.\n<span data-k=\"q\">(משיחת ליל ו' תשרי תשמ\"ה)</span>",[["1142","48","סדר היום תפלת מנחה (הובא באוה\"ת לנ\"ך ע' עב). סד\"ה לעולם יהא אדם תרע\"ז, תרצ\"א (בסה\"מ קונטרסים ח\"א). ובכ\"מ.\nוראה אוה\"ת שם (ע' עא ואילך) בביאור מעלת תפלת מנחה (בין הערביים), שהיא ביטול היש לאין, בירור ההסתר וחושך הנמשך משם אלקים, ולכן שייכת ליצחק, \"צחוק עשה לי אלקים\". ע\"ש באורך."],["1143","49","ברכות יא, ב."],["1144","50","רש\"י עירובין מג, ריש ע\"ב. רש\"י עה\"ת בחוקותי כו, מב. וראה פסיקתא רבתי ספל\"ו (לה). ועוד."],["1145","51","ברכות ו, ב."],["1146","52","ל' התניא ספל\"ו."],["1146","52","ל' התניא ספל\"ו."]]],[1301670193,"<h3>שיחה ג</h3>\nא. \"ויהי<sup data-n=\"1148\">1</sup> בעת יחם הצאן ואשא עיני וארא בחלום והנה העתודים העולים על הצאן עקודים נקודים וברודים\", וב­פרש\"י \"וברודים, תרגומו<sup data-n=\"1149\">2</sup> ופציחין [היינו פתוחים]. . חוט של לבן מקיף את גופו סביב וחברבורות<sup data-n=\"1150\">3</sup> שלו פתוחה ומפולשת מזו אל זו<sup data-n=\"1151\">4</sup> ואין לי להביא עד מן המקרא\".\nוהנה הראב\"ע כותב בפירושו<sup data-n=\"1152\">5</sup> ש­\"טלואים הם הברודים\"<sup data-n=\"1153\">6</sup>, וברד\"ק כאן<sup data-n=\"1154\">7</sup> פי' \"וברודים, זכרו במקום טלואים ואמר ברודים כי לבנותם הי' כמו הברד\"<sup data-n=\"1155\">8</sup>.\nוצריך ביאור, מדוע העדיף רש\"י את פירוש התרגום, ולא פי' כהראב\"ע (וה­רד\"ק) שברודים היינו טלואים (שנזכר לעיל בקרא<sup data-n=\"1156\">9</sup>). דלפי' הראב\"ע מובן שאין כאן צורה חדשה על הצאן שלא נזכרה עד עתה, אבל לפרש\"י ש\"ברודים\" היינו \"חוט של לבן מקיף את גופו סביב כו' פתוחה ומפולשת כו'\", צריך ביאור, הרי לעיל בכתוב נזכרו רק \"עקודים נקודים וטלואים\"<sup data-n=\"1157\">10</sup> ולא ברודים, ונמצא שבחלום יעקב נתחדשה צורה חדשה בצאן שלא נזכרה עד עתה.\nב. לכאורה יש לומר שרש\"י אזיל כאן לשיטתי'. דהנה בתוכן פסוקים אלו<sup data-n=\"1158\">11</sup>, \"וארא בחלום והנה העתודים העולים על הצאן עקודים גו' ויאמר אלי מלאך האלקים בחלום גו' שא נא עיניך וראה כל העתודים העולים גו' כי ראיתי את כל אשר לבן עושה לך\", שקו\"ט במפר­שים, שהרי כבר מפורש לעיל שצאן יעקב הולידו עקודים נקודים כו' ע\"י המקלות<sup data-n=\"1159\">12</sup>, \"ויפצל בהן פצלות לבנות גו' ויצג את המקלות גו' ויחמו הצאן אל המקלות ותלדנה הצאן עקודים נקודים וטלואים\" — וא\"כ מה נתחדש בזה שראה בחלום \"העתודים העולים על הצאן עקודים נקודים וברודים\", והמלאך אמר לו \"שא נא עיניך וראה כל העתודים העולים על הצאן עקודים גו'\"?\nוביארו המפרשים בכמה אופנים, ו­מהם:\nא) שלידת עקודים נקודים כו' היתה על ידי פעולה הטבעית דהמקלות, וכ­ידוע<sup data-n=\"1160\">13</sup> שצורת התולדות תלוי' בצורה המצטיירת במחשבת האם, וחלומו של",[["1148","1","פרשתנו לא, י."],["1149","2","בדפוס ראשון ושני וכמה כת\"י רש\"י (ש­תח\"י) \"כתרגומו\"."],["1150","3","בדפוס ראשון ושני וכמה כת\"י רש\"י (ש­תח\"י) \"חברבורת (חברבורה)\", בלי וא\"ו — ל' יחיד (וכן ליתא וא\"ו בתחלתו). ולכאורה כצ\"ל, שהרי ממשיך (גם בדפוסים הנפוצים) בל' יחיד \"פתוחה ומפולשת\"."],["1151","4","בדפוסי רש\"י הנפוצים הובא ס\"א \"מזן אל זן\", וכ\"ה בדפוס ראשון ושני וכמה כת\"י רש\"י (שתח\"י)."],["1152","5","לעיל ל, לט. וראה גם שם, לה."],["1153","6","אלא שמסיים שם \"כי שם כלל הוא\", ד\"טלוא\" הוא שם כללי. וכ\"כ שם, לא (לט) ואילך."],["1154","7","וכ\"כ בס' השרשים שלו ערך ברד \"שיש להם כתמים לבנים כמו ברד וכן סוסים ברדים אמצים\" (זכרי' ו, ג)."],["1155","8","ולפ\"ז גם להרד\"ק הוא אותה הצורה ד­טלואים אלא דברוד מתאר לבנוניתו. וראה גם ראב\"ע לעיל ל, לא (לט). רלב\"ג כאן בביאור המלות."],["1156","9","ל, לב. לג. לה. לט."],["1157","10","ל, לט."],["1158","11","לא, י­יב."],["1159","12","ל, לז ואילך."],["1160","13","ראה גם ראב\"ע ל, לט. ועוד."]]],[1301670194,"מלאך ודברי המלאך היו נבואה מאת ה', שהבטיח לו הצלחה טבעית בהשתדלותו בפעולות טבעיות<sup data-n=\"1161\">14</sup> אלה.\nב) שהלידה דעקודים נקודים כו' היתה בדרך נס<sup data-n=\"1162\">15</sup>, וכבשורת המלאך, ו­פעולת יעקב עם המקלות היתה רק \"כדי<sup data-n=\"1163\">16</sup> להעלים הנס ולהסתירו במעשה הטבע, ע\"ד שמצינו באלישע שאמר לגחזי<sup data-n=\"1164\">17</sup> קח משענתי בידך גו' ושמת משענתי על פני הנער גו', וכמו שאמר הקב\"ה ליהושע<sup data-n=\"1165\">18</sup> במלחמת עי שים לך אורב לעיר כו' אף על פי שמלחמה זו על ידי נס היתה ופועל המקלות אחר דברי המלאך הי'\".\nג) שהיו כאן שני ענינים נפרדים, הן לידת עקודים וכו' שבאה באופן טבעי ע\"י המקלות דיעקב, והן לידה שהיתה בדרך נס בלי כל קשר לפעולת המקלות (ועל זה בא כאן סיפור החלום ודברי המלאך)<sup data-n=\"1166\">19</sup>.\nוהנה את\"ל (כב' האופנים הראשונים) שב' ענינים אלו שייכים זל\"ז והשגחת ה' המוזכרת בחלום יעקב קשורה עם פעו­לות יעקב בהמקלות<sup data-n=\"1167\">20</sup>, מובן בפשטות, שלא מסתבר כלל לומר שכאן אומר הפסוק דבר חדש במין וצורת הצאן שנולדו, אלא עקודים נקודים ברודים הן הן המינים שנפרטו לעיל, עקודים נקו­דים טלואים.\nאבל את\"ל (כאופן הג') שחלום יעקב ונבואת ה' הם ענין בפ\"ע מפעולת המק­לות, יש לומר בפשטות, שפעולות יעקב במקלות והנס שהובטח לו בחלום גרמו להולדת שני מיני צאן: פעולת יעקב במקלות גרמה שיוולדו \"עקודים נקודים וטלואים\", ואילו על ידי נס נולדו \"עקו­דים נקודים וברודים\".\nג. והנה רש\"י כאן בד\"ה \"והנה העתו­דים\" פי' \"אע\"פ שהבדילם לבן כולם שלא יתעברו הצאן דוגמתן, היו המלאכים מביאין אותן מעדר המסור ביד בני לבן לעדר שביד יעקב\" — הרי מפורש, שלדעת רש\"י, הבטחת השם בחלום יעקב היתה ענין בפני עצמו מהולדת הצאן על ידי המקלות, שנולדו עקודים נקודים כו' על ידי זכרים כאלו שהובאו בדרך נס<sup data-n=\"1168\">21</sup> על ידי המלאכים מעדרו של לבן<sup data-n=\"1169\">22</sup>.",[["1161","14","ראה רלב\"ג כאן. אברבנאל כאן. ולדברי­הם מה שלקח יעקב המקלות לא עשה זה מעצמו אלא על פי המלאך [וכן מפורש במדרש לקח טוב ל, לט. רבינו בחיי שם, לח (אבל ביאורו בזה הוא לכאורה דלא כדבריהם)].\nובטור הארוך (ל, מב בסופו), לאחרי שהביא יש מפרשים כי איננו טבע שיולידו נקודים כו' בכח המקלות אלא דרך נס, ומה שהוצרך מקלות לנס כי כן דרך כל הנסים למעט הנס כו', מסיים \"ואינו נראה כי ודאי טבע הוא וכן דעת רבותינו ז\"ל\"."],["1162","15","ראה כלי יקר לא, ח. אוה\"ח לא, י."],["1163","16","ל' הרא\"ם (ל, לט), והוא ע\"פ האמונה והבטחון להרמב\"ן (פט\"ו). רבינו בחיי שם. ועד\"ז הובא ביפה תואר השלם לב\"ר פע\"ג, ז ד\"ה מלאכי השרת. הואיל משה (באר התורה) כאן."],["1164","17","מלכים ב ד, כט."],["1165","18","יהושע ח, ב."],["1166","19","ראה ראב\"ע לא, ט. רמב\"ן שם, יוד. פי' הב' ברא\"ם הנ\"ל."],["1167","20","וראה גם רבינו בחיי שם ל, לז בסופו: והי' הענין הזה ליעקב דבר חכמה וסוד הטבע מעורב בנס כי הי' ענין טבעי מצד פצול המקלות ומצד אחר הי' נס גמור. ע\"ש. וראה גם מדרש לקח טוב שם. רבינו בחיי שם, לח בטעם הב'."],["1168","21","ודוחק גדול לומר לפרש\"י שרצה יעקב להעלים הנס בטבע בפעולת המקלות (כי מפשטות ל' הכתוב ורש\"י משמע שע\"י המקלות נולדו בפועל עקודים נקודים וטלאים). ובפרט דאז הו\"ל לרש\"י לכותבו בפירוש."],["1169","22","במשכיל לדוד, דאף שהמלאכים הביאו הצאן מעדר לבן, אפ\"ה יעקב לקח לו מקל לבנה כו', שלא רצה לסמוך על הנס כו', ועוד דחש יעקב ליהנות ממעשה נסים. ועד\"ז בבאר בשדה (ל, לט).\nומשמע קצת דמפרש שפעולת המלאכים (בדרך נס) היתה רק בתחלה.\nאבל מזה שרש\"י לא פירש כאן מתי היתה פעו­לת המלאכים ומתי המקלות וכיו\"ב (ראה רמב\"ן עה\"ת ובחיי הנ\"ל שקו\"ט בזה), משמע לכאורה, דפעולת המלאכים היתה בסוף הזמן, או במשך כל הזמן \"משעה ראשונה עד אחרונה\" (גו\"א כאן. וראה שם שעכצ\"ל שדבר המלאך הי' רק בסוף שני ה­עבודה דאל\"כ \"איך יעבור. . ארץ אבותיך\"). ולהעיר מנחלת יעקב לא, ז."]]],[1301670195,"ומש\"ה מפרש רש\"י, דזה שהכתוב שינה בלשונו מ\"טלואים\" ל\"ברודים\" הוא לפי שהם שתי צורות שונות, ד\"טלואים\" הם סתם \"חברבורות רחבות\"<sup data-n=\"1170\">23</sup> ואילו \"ברודים\" היינו \"פציחין\", ש\"חוט של לבן מקיף את גופו סביב וכו'\"<sup data-n=\"1171\">24</sup>.\nאלא שצריך ביאור (עכ\"פ בפנימיות הענינים), מאי טעמא לחילוק זה, שהצאן שנולדו על ידי פעולת המקלות היו \"עקודים נקודים וטלואים\", ואילו ע\"י המלאכים הובאו (בדרך נס) \"עקודים נקודים וברודים\" — ברודים במקום טלואים?\nד. ויש לומר, שהביאור בזה נרמז ב­פרטי לשונות רש\"י גופא בפי' \"ברודים\" — וכפי שהובא הרבה פעמים פתגם אדמו\"ר הזקן שפירוש רש\"י על התורה הוא \"יינה של תורה\"<sup data-n=\"1172\">25</sup>, היינו, שבלשון רש\"י נרמזים כמה ענינים שע\"ד הסוד (\"נכנס יין יצא סוד\"<sup data-n=\"1173\">26</sup>).\nוכמו\"כ בעניננו, דהנה ידוע ש\"עקו­דים נקודים ברודים\" מרמזים על ג' העולמות הכלליים (כמבואר בכתבי ה­אריז\"ל<sup data-n=\"1174\">27</sup>), וכל זה הוא \"אשר לבן עושה לך\"<sup data-n=\"1175\">28</sup>, כי \"לבן הוא סוד לובן העליון אשר הוא קודם כל האצילות הזה\"<sup data-n=\"1174\">27</sup>, היינו א\"ס ב\"ה שהוא פשוט בתכלית הפשיטות (בדוגמת מראה לבן, שאינו גוון המתהווה \"על ידי צבע\" אלא מורה על פשיטות)<sup data-n=\"1177\">29</sup>, וההתגלות של \"לובן העליון\" בג' העולמות דעקודים נקודים וברודים היא על ידי יעקב דוקא<sup data-n=\"1178\">30</sup>.\nועפ\"ז יש לבאר גם פרטי הלשונות והענינים בלשון רש\"י בפירוש \"ברודים\" — (א) חוט של לבן, חוט דוקא, (ב) \"מקיף את גופו סביב\", (ג) \"חברבורות שלו פתוחה ומפולשת מזו אל זו\" — שג' עני­נים אלו מכוונים לג' הענינים שבהמשכת \"לובן העליון\" בעולם הברודים, כדלקמן ס\"ו.\nוע\"פ הקדמה זו יתבאר ג\"כ מדוע חידוש זה שייך דוקא לפעולת המלאכים",[["1170","23","רש\"י לעיל ל, לב."],["1171","24","ואין להקשות (ראה אוה\"ח עה\"פ) שבתנאי שהתנה יעקב עם לבן לא נאמר אלא \"כל אשר איננו נקוד וטלוא בעזים וחום בכשבים\" (ל, לג) — שהרי זהו מה ש\"ותחלף את משכורתי\" — \"היית משנה תנאי שבינינו מנקוד לטלוא ומעקודים<sup data-n=\"e30\">*</sup> לברודים\" (לא, מא ובפרש\"י).\nוראה בארוכה גו\"א, דלפרש\"י (ל, לו) הסיר לבן גם מה שלא התנו ביניהם. ולכן לאחר שהסיר כל אשר לבן בו (לא כפי המדובר) הרי כל אשר לבן בו נשאר בשכרו של יעקב."],["1172","25","\"היום יום\" כט שבט."],["1173","26","עירובין סה, סע\"א. וראה בארוכה אמרי בינה לאדמו\"ר האמצעי (בעל יום ההולדת ויום ההילולא דט' כסלו, ובעל הגאולה דיו\"ד כסלו — כדלקמן בפנים) שער הק\"ש ספנ\"ג ואילך, ש\"יינה של תורה\" הוא רזין דאורייתא."],["1174","27","ע\"ח שער העקודים בתחלתו."],["1175","28","לא, יב."],["1174","27","ע\"ח שער העקודים בתחלתו."],["1177","29","תו\"א סוף פרשתנו (כד, ב). תו\"ח שם (לז, ד ואילך). וראה בארוכה (ע\"ד מראה לבן) עטרת ראש שער יוהכ\"פ פ\"ה. מאמרי אדמו\"ר האמצעי ויקרא (כרך ב) ע' תפד ואילך."],["1178","30","ראה תו\"ח שם."],["e30","*","כ\"ה בדפוסי רש\"י לפנינו. ובדפוס ראשון \"לעקודים\", — שלפ\"ז הכל המשך אחד, מנקוד ל­טלוא לעקודים לברודים. ובדפוס שני \"בנקוד וטלוא עקודים וברודים\". וראה רא\"ם ומפרשי רש\"י. וא­כ\"מ."]]],[1301670196,"ולא לפעולת יעקב עם המקלות, כדלקמן שם.\n[ויש להוסיף ולהעיר על ההשגח\"פ, שהפרטים האמורים ב\"עולם הברודים\" המרומזים בלשון רש\"י בפרשתנו, נת­בארו בארוכה בדרושי כ\"ק אדמו\"ר ה­אמצעי<sup data-n=\"1179\">31</sup> — שיום ההילולא ויום ההולדת שלו (ט' כסלו), וכן חג הגאולה שלו (יו\"ד כסלו), חלים בכמה שנים בשבוע דפ' ויצא, או עכ\"פ \"מתברכים\" הם מש\"פ ויצא (ובשנה זו{*} חל יום ההולדת ויום ההילולא בש\"ק פ' ויצא עצמה)].\nה. וביאור הענין:\nידוע מה שאיתא בס' העקידה<sup data-n=\"1180\">32</sup> שע\"י שני אופנים יכולים אנו לידע גדולת הבורא, הא' מהנהגת הטבע, היינו מזה שהעולם מתנהג תמיד באותו טבע וסדר בלי שינוי ובלי הפסק, שבזה ניכר כח הא\"ס, והב' מההנהגה שלמעלה מהטבע, היינו מענין הנסים וביטול הטבע, שבזה ניכרת גדולת הבורא עוד יותר.\nוב' הנהגות אלו, שרשן מב' המשכות מהקב\"ה<sup data-n=\"1181\">33</sup>, ההמשכה שבבחי' בלי גבול וההמשכה שבבחי' גבול ומדה, דהנהגת הטבע היא מההמשכה שבבחי' גבול ו­מדה, שהוא בחי' האור והחיות הפנימי המתלבש בעולמות בפנימיותם להחיותם, שזהו מקור הנהגת כל העולמות וה­נבראים, וההנהגה שלמעלה מהטבע שרשה מההמשכה שבבחי' בלי גבול.\nועפ\"ז יש לבאר שתי הדיעות הנ\"ל (ס\"ב) אם עיקר הולדת הצאן עקודים נקודים כו' היתה על ידי פעולה טבעית (אלא שהיתה לו בזה נבואה מאת ה' שיצליח בזה בהשגחתו ית'), או שעיקר הולדת הצאן היתה בדרך נס — בפני­מיות הענינים:\nובהקדם המבואר דבחי' יעקב — אותיות \"יבקע\"<sup data-n=\"1182\">34</sup> (וכדאיתא בזהר<sup data-n=\"1183\">35</sup> לענין האושפיזין דסוכות, שיעקב אומר ה­כתוב<sup data-n=\"1184\">36</sup> \"אז יבקע כשחר אורך\") — מורה על המשכת ובקיעת אור ה\"קו\"<sup data-n=\"1185\">37</sup> לאחרי הצמצום, וזו היתה כל עבודת יעקב ב­צאן לבן, להמשיך בחי' \"לובן העליון\", אור א\"ס שלמעלה מהצמצום, בעולמות עקודים נקודים כו', שהמשכה זו היא על ידי אור הקו, שבוקע את חושך הצמצום.\nוהנה ידוע<sup data-n=\"1186\">38</sup>, שיש ב' שיטות בנוגע לאור הקו: א) הקו הוא ההמשכה שבבחי' מדה וגבול, והיינו דשרשו הוא מבחי' הגבול שבאין סוף (כי הא\"ס, כשם שיש לו כח בבלתי בעל גבול כן יש לו כח בגבול<sup data-n=\"1187\">39</sup>), ב) הקו הוא ההמשכה שבבחי' בלי גבול, והיינו דשרשו הוא מבחי' אור א\"ס הבלתי בעל גבול, אלא שזהו כמו",[["1179","31","בתו\"ח פרשתנו. וביאור בחי' עקודים נקודים וברודים בארוכה — בתו\"ח פ' נח (סה, ד ואילך)."],["1180","32","פ' בא עה\"פ החודש גו' (שער לח), הובא ונת' באוה\"ת בראשית יח, ב ואילך. ד\"ה החודש תרנ\"ד (סה\"מ תרנ\"ד ע' קלא ואילך), תרס\"ו (המשך תרס\"ו ע' קנו ואילך) ותרע\"ח (הב' — סה\"מ תרע\"ח ע' רכה ואילך). ועוד."],["1181","33","ראה סד\"ה החודש תרס\"ו (ע' קסג). ובכ\"מ."],["1182","34","עץ חיים שער הכללים פ\"י. שם שער לב (שער הארת המוחין) ספ\"א. וראה לקו\"ת צו ח, סע\"ד ואילך (ושם מע\"ח של\"א ספ\"א. והוא בשל\"ב הנ\"ל). סידור שער הסוכות רנז, סע\"ד ואילך. מאמרי אד­מו\"ר האמצעי לנ\"ך ריש ע' רלד."],["1183","35","ח\"ג קד, א (וראה ניצוצי אורות שם)."],["1184","36","ישעי' נח, ח."],["1185","37","ראה ספר הליקוטים דא\"ח דהצ\"צ מע' יעקב סעיף ד. וש\"נ."],["1186","38","ראה המשך תרס\"ו ע' קסב ואילך. ע' קצד ואילך. ועוד."],["1187","39","עבודת הקודש ח\"א רפ\"ח. דרך אמונה לב­על עבוה\"ק פ\"ב (בהוצאת קה\"ת, תשמ\"ח — ע' יג)."]]],[1301670197,"שהאור אין סוף הבלתי בעל גבול מאיר בעולמות.\nוזהו תוכן שתי הדיעות, מה הי' העיקר בהולדת הצאן, דלהדיעה שהקו הוא המשכה שבבחי' גבול ומדה, היינו שבא\"ס גופא ישנו שורש מקור הקו (שורש האורות), הרי עיקר המעלה וה­שלימות אינו בפעולה נסית היוצאת מדרכי הטבע, אלא שהמשכת אלקות היא בטבע גופא, כפי שהטבע הוא במציאותו<sup data-n=\"1188\">40</sup>, ולכן מפרשים שעיקר פעו­לתו של יעקב, המשכת הקו היא בפעולה הטבעית דהמקלות, שזו היתה הצלחה מיוחדת מאת ה';\nוהפירוש שעיקר הולדת הצאן היתה בדרך נס, הוא כהשיטה שהמשכת אור הקו היא מהאור שבבחי' בלי גבול, והיינו מה שאור א\"ס הבלי גבול צמצם את עצמו להיות בבחי' \"קו\" (כדי שיוכל להאיר בעולמות), אבל זהו מה שאור א\"ס הבלי גבול מאיר בעולם.\nואופן הג' הנ\"ל שהיו כאן ב' הענינים, הן פעולת יעקב באופן טבעי ע\"י ה­מקלות, וגם הפעולה בדרך נס בלי קשר לפעולת הטבע, הוא לפי המבואר בכ\"מ<sup data-n=\"1189\">41</sup>, שבקו עצמו ישנם שני הענינים — חיצוניות הקו ופנימיות הקו. דחיצוניות הקו הוא הגילוי הנמשך בעולמות באופן של התלבשות, ובא בבחי' התחלקות, וענינו שיהי' על ידו התהוות העולמות, וגילוי האור בעולמות הוא בכל עולם לפי מצי­אותו; ואילו פנימיות הקו הוא ההמשכה מבחי' פנימיות א\"ס ב\"ה, ופעולתו ב­עולמות היא המשכת האור האלקי הבלי גבול בעולם, בלשון הזהר<sup data-n=\"1190\">42</sup> \"איהו מקשר ומיחד זינא לזיני' עילא ותתא\".\nוהיינו דבחיצוניות הקו, הרי כל מה שיורד ונמשך, נתצמצם ונתמעט האור, ובפנימיות הקו (ששרשו מפנימיות א\"ס, \"תפארת הנעלם\") אין בו התחלקות ו­נמשך בכל מקום בשווה. והם הם שני ה­ענינים בהולדת הצאן כו', דפעולת יעקב ע\"י המקלות (השייך להצלחה אלקית שבהנהגת הטבע), הוא מצד המשכת חיצוניות הקו, שורש הנהגת הטבע; והו­לדת הצאן בדרך נס הוא מצד המשכת פנימיות הקו, שורש הנהגה נסית.\nו. ועפ\"ז יש לבאר הטעם, שדוקא בענין הולדת הצאן שעל ידי המלאכים (פעולה נסית) נולדו \"ברודים\", כי הגילוי דפנימיות הקו בא לידי ביטוי ב\"עולם הברודים\".\nויש לומר, שזהו שמרמז כאן רש\"י בפי' \"ברודים\" — \"תרגומו ופציחין כו' חוט של לבן מקיף את גופו סביב וחברבורות שלו פתוחה ומפולשת מזו אל זו\" — שבזה נרמז החידוש שעל ידי המשכת פנימיות אור הקו:\n\"חוט של לבן\", היינו שגם בהמשכתו לאחרי הצמצום, שהוא קו וחוט קצר, מ\"מ ה\"ה \"לבן\", שבו מתגלה פשיטות האין סוף<sup data-n=\"1191\">43</sup>.\nו\"חוט\" זה \"מקיף את גופו סביב\", ש­יש לומר שזה מרמז על זה שאור הקו מלבד המשכתו בבחי' \"יושר\", הרי הוא מתעגל ומקיף כל עולם ועולם<sup data-n=\"1192\">44</sup>, דזה שאור הקו מקיף כל עולם ועולם הוא מצד המשכתו מבחי' העיגול הגדול<sup data-n=\"1193\">45</sup>,",[["1188","40","ראה לקו\"ש חי\"ז ע' 151 ואילך. וראה ספר המאמרים מלוקט ח\"ד ע' רכז ואילך. וש\"נ."],["1189","41","המשך תער\"ב ח\"ב ע' א'קסט ואילך. סה\"מ עטר\"ת ס\"ע תמג ואילך."],["1190","42","ח\"ג רכה, א. הובא בשער היחוד והאמונה פ\"ז (פג, ב ואילך)."],["1191","43","ויש לומר שזהו שמסיים רש\"י \"ואין לי לה­ביא עד כו'\", שעל בחינה זו דפנימיות הקו שהיא בבחי' פשיטות הא\"ס, אין \"עד\" ודוגמא בדרגת הגילויים."],["1192","44","ראה ע\"ח שער א' ענף ב."],["1193","45","ראה לקו\"ת ר\"פ קרח. ובכ\"מ."]]],[1301670198,"היינו אור הסובב כל עלמין (ההמשכה שבבחי' בלי גבול)<sup data-n=\"1194\">46</sup>.\nומסיים \"חברבורות שלו פתוחה ו­מפולשת כו'\", דיש לומר שזה מרמז על חיבור הקו והחוט (גם) עם תחתיתו של העיגול, כמבואר בכ\"מ<sup data-n=\"1195\">47</sup> שלעתיד לבוא יהי' הקו נוגע ודבוק באוא\"ס הסובב גם בקצהו התחתון, דבזמן הזה יש הפסק בין אור הקו ואור הסובב מתחת לעולמות<sup data-n=\"1192\">44</sup>, אבל לעתיד לבוא יהי' \"פתוח ומפולש\", עד שיהי' נוגע ודבוק גם בתחתיתו.\nוענין זה שייך ל\"ברודים\" דוקא, כ­מבואר בכ\"מ, ובפרט בדרושי אדמו\"ר האמצעי<sup data-n=\"1197\">48</sup> (בעל יום ההולדת ויום ההי­לולא), שדוקא עולם הברודים, שהוא עולם התיקון<sup data-n=\"1198\">49</sup>, שיש בו ריבוי ההתכל­לות<sup data-n=\"1199\">*49</sup>, שכל הספירות כלולות זע\"ז וזמ\"ז, שרשו בעצמות אור א\"ס ממש (שלמעלה מעקודים, אף שגם בעולם העקודים כל העשר ספירות עקודים<sup data-n=\"1200\">50</sup> בכלי אחד).\nויש לומר שזהו גם הרמז בהתחלת לשון רש\"י \"וברודים — תרגומו ופציחין כו' חוט של לבן כו'\", היינו, שה\"תרגום\" — ה\"פירוש\" וההתגלות — של ענין \"ברודים\", הוא גילוי פנימיות הקו, \"חוט של לבן כו'\".\nז. והענין בעבודה:\n\"חוט של לבן\" מורה על העבודה ה­קשורה עם פשיטות<sup data-n=\"1201\">51</sup> הנפש — \"לבן\", גוון עצמי ופשוט שאין בו ציור, היינו עצם הנפש (שלמעלה גם מבחי' יחי­דה<sup data-n=\"1202\">52</sup>); ודוקא על ידי גילוי פשיטות הנפש נעשים שני הענינים: א) פועל על כללות האדם, \"מקיף את גופו סביב\", ב) חודר בתוך כל עניניו, כל כוחותיו, באופן שחודר בתוך תוכם עד שזה נעשה מציאות הכוחות ומחדו\"מ שלו, שזהו מה ש\"חברבורות שלו פתוחה ומפולשת מזו אל זו\".\nשהכח על כל זה הוא מפנימיות התורה, דחיצוניות התורה יש לה מדה ושיעור, דכל עניני התורה הם במדידה והגבלה, אבל פנימיות התורה הוא מבחי' אין סוף<sup data-n=\"1203\">53</sup>, ולכן על ידו מתגלה פשיטות הנפש (שלמעלה ממדידה והגבלה) ה­מקיפה את כל האדם וחודרת בתוך כל כוחותיו.\n<span data-k=\"q\">(משיחת ש\"פ ויצא תשמ\"ג) </span>",[["1194","46","ואף שענין זה בהקו שמקיף כל עולם כו', מבואר לענין הקו בכלל, חיצוניות הקו, הרי מובן, שענין זה אין זה בו מצ\"ע אלא מצד פנימיותו, כבפנים."],["1195","47","סה\"מ תרנ\"ט ס\"ע קי ואילך (בשם \"יש מקובלים\". וראה אוה\"ת בראשית מא, ב מ\"ביאור דמים רבים תקס\"ט\"<sup data-n=\"e31\">*</sup>). המשך תער\"ב ח\"א ריש ע' קיז. סה\"מ תש\"ב ס\"ע 122."],["1192","44","ראה ע\"ח שער א' ענף ב."],["1197","48","תו\"ח נח עג, א (פל\"ז) ואילך."],["1198","49","ע\"ח שער התיקון רפ\"ד. מאמרי אדה\"ז — פרשיות ח\"א ע' סד ואילך. תו\"ח בראשית מה, א. נח סה, ד ואילך. ובכ\"מ."],["1199","*49","ראה אוה\"ת בשלח ע' שצה: ועולם התיקון נק' ברודים כו' פי' ברודים הוא התכללות כמה גוונין יחד כמ\"ש (בזכרי' סי' ו) סוסים ברודים הפי' שיש בהם הרבה גוונין."],["1200","50","ע\"ח שער העקודים שם. מבוא שערים ש\"ב ח\"ג פ\"ז. וראה בארוכה מאמרי אדה\"ז שם. תו\"ח נח שבהערה הקודמת. ובכ\"מ."],["1201","51","ראה עטרת ראש שם."],["1202","52","ראה בארוכה ס' השיחות תשנ\"ב ע' 127 ואילך."],["1203","53","ראה סה\"מ עטר\"ת שם (ע' תמד), דב' הבחי' דנגלה ופנימיות התורה הם מבחי' חיצוניות ופנימיות הקו. וראה המשך תער\"ב שם ח\"ב (ע' א'קע), ד\"אמיתית מדריגה זו [דפנימיות הקו] אינו בא בבחי' התלבשות כלל וכמו פנימי' סודות התורה הנק' רזי דרזין\"."],["e31","*","והוא שם בסוף המאמר. — במאמרי אדה\"ז תקס\"ט (קה\"ת, תשמ\"א) נדפסה הנחת אדמו\"ר האמצעי, ושם (ע' לב) חסר סוף הביאור. אבל נמצא בבוך 554 (עז, ד). ועוד."]]],[1301670199,"<h3>שיחה א</h3>\nא. \"ויקרא יעקב שם המקום פניאל כי ראיתי אלקים פנים אל פנים גו' ויזרח לו השמש כאשר עבר את פנואל גו'\"<sup data-n=\"1204\">1</sup>. וכבר עמדו במפרשים<sup data-n=\"1205\">2</sup> על השינוי שבכתוב, ששינה שם המקום מ\"פניאל\" (ביו\"ד) ל\"פנואל\"<sup data-n=\"1206\">3</sup> (בוא\"ו).\nולכאורה צ\"ע בפרש\"י עה\"ת, שלא ביאר ענין זה בפירושו.\n[וכמשנ\"ת כמה פעמים, שדרכו של רש\"י בפירושו עה\"ת ליישב כל שאלה המתעוררת בלימוד המקרא, כדמוכח מזה שבכ\"מ בפירושו<sup data-n=\"1207\">4</sup> כ' רש\"י על ענין מסויים \"איני יודע\" (וכיו\"ב), שמזה מובן, שבשאר כל המקומות שיש קושי, לכ­אורה, בקרא, ורש\"י סתם ולא כ' \"איני יודע\", ה\"ז משום שלשיטתו אין זו שאלה הדורשת ביאור בפשש\"מ, או שהשאלה מיושבת כבר ע\"י פרש\"י שלפנ\"ז].\nוהנה לכאורה יש לומר, שע\"ד הפשט אין שאלה זו דורשת יישוב, כי אין מדייקין בשמות. וכדמוכח לכאורה מהא דמצינו שינוי כעין זה גם לעיל בפ' בראשית<sup data-n=\"1208\">5</sup> — \"ועירד ילד את מחויאל ומחייאל ילד את משותאל\", שהכתוב שינה מ\"מחויאל\" (בוא\"ו) ל\"מחייאל\" (ביו\"ד)<sup data-n=\"1209\">6</sup> — ולא עמד רש\"י לתרץ שינוי זה.\nומפורש שיטה זו בהראב\"ע שכתב \"אל תבקש דקדוק בשמות\"<sup data-n=\"1210\">7</sup>, \"השמות אינם נשמרים כמו הפעלים\"<sup data-n=\"1211\">8</sup>, היינו שאין לדייק באותיות ונקודות השם, דאין הכ­רח שיהיו בדיוק בהתאם לטעם השם. ועפ\"ז אין להקשות על שינוי השם מ­\"פניאל\" ל\"פנואל\" (וכפי שמביא<sup data-n=\"1212\">9</sup> עוד דוגמאות שהכתוב משנה קצת ב(כתיבת) השם ממקום א' לחבירו).\nאבל לכאורה קשה לתרץ כן בנדו\"ד, דאף שאין הכתוב מדייק בשמות, וכנ\"ל השינוי מ\"מחויאל\" ל\"מחייאל\" (וכהנה רבות) — הרי יש חילוק גדול בין סתם שמות שנזכרו בקרא (מבלי לפרש טעם השם), שבזה י\"ל שאין דיוק בשמות אלו — לנדו\"ד, שהכתוב מפרש טעם השם, שבשמות אלו ס\"ל לרש\"י שיש לדייק באותיות השם כפי האפשרי, שיבחרו תיבה שפירושה הוא בהתאם מדויק ל­טעם השם<sup data-n=\"1213\">10</sup>. וכפרש\"י עה\"פ<sup data-n=\"1214\">11</sup> \"ויקרא את שמו נח לאמר זה ינחמנו גו'\", \"יניח ממנו את עצבון ידינו כו' ואם לא תפרשהו כך",[["1204","1","פרשתנו לב, לא­לב."],["1205","2","בחיי, אלשיך, אוה\"ח ועוד."],["1206","3","ובפרט שכך נשאר שמו גם אח\"כ (ס' שופ­טים ח, ח­ט. שם, יז), כמ\"ש באוה\"ח כאן [ומ\"ש באוה\"ח שרק יעקב לבד קראו פניאל, משא\"כ \"כל חוץ ממנו ואפי' דבר תורה תקראהו פנואל\" — הא גופא טעמא בעי, למה שינו את השם (ורק באות אחת)?]."],["1207","4","פרשתנו לה, יג. ובכ\"מ — נסמנו בלקו\"ש ח\"ה ע' 1 הערה 2."],["1208","5","ד, יח."],["1209","6","ראה גם פי' ר\"ש בן חפני גאון (ירושלים, תשל\"ט) פרשתנו כאן."],["1210","7","פינחס כו, יב."],["1211","8","שמות ב, י — גבי שם משה (שלא נקרא \"משוי\"). וראה לקמן הערה 12."],["1212","9","בפ' פינחס שם. וראה גם פי' ר\"ש בן חפני גאון (הנ\"ל הערה 6) לויגש מו, י."],["1213","10","ראה גם לקו\"ש חכ\"ה ע' 65 ובהערה 24 שם."],["1214","11","בראשית ה, כט."]]],[1301670200,"אין טעם הלשון נופל על השם ואתה צריך לקרות שמו מנחם\", הרי דס\"ל ש­מדייקין בשמות שיהיו בהתאם מדויק לטעם השם, שלכן א\"א לומר ד\"נח\" הוא שם מקוצר מתיבת \"נחמה\" אלא הוא לשון \"יניח\"<sup data-n=\"1215\">12</sup>.\nוכיון שכן תמוה: לאחרי שהכתוב מפרש טעם השם \"פניאל\" — \"ראיתי אלקים פנים אל פנים\" (\"פניאל\" — \"פני א­ל\"), מה מקום לשנות השם ל\"פנואל\"?\n[ואע\"פ שגם בשמות שנתפרש טעמם בקרא אין מוכרח שאותיות השם תהיינה בדומה ממש לאותיות שבטעם השם, ומספיק שהם דומים באותיות העיקריות (כמוכח משמות השבטים<sup data-n=\"1216\">13</sup> ועוד) — עדיין אין זה מתרץ השינוי שבכתוב כאן, ד­לאחרי שכבר קרא שם המקום \"פניאל\", שהוא בדיוק כטעם השם, מה מקום ל­שנות ל\"פנואל\" (שבו אין משמעות הטעם ברורה)].\nב. לכאורה יש לומר, שהשינוי מ­\"פניאל\" ל\"פנואל\" אינו שינוי אמתי, כי אות יו\"ד ואות וי\"ו מתחלפות זע\"ז<sup data-n=\"1217\">14</sup>, וכ­דמצינו לעיל (בפ' בראשית<sup data-n=\"1218\">15</sup>) גבי שם \"חוה\" — \"ויקרא האדם שם אשתו חוה כי היא היתה אם כל חי\", ובפרש\"י \"חוה, נופל על לשון חי' שמחי' את ולדותי'<sup data-n=\"1219\">16</sup>, כאשר תאמר מה הוה לאדם<sup data-n=\"1220\">17</sup> בלשון הי'\". ולפום ריהטא נראה שכוונת רש\"י כמ\"ש הראב\"ע (ועוד מפרשים<sup data-n=\"1221\">18</sup>) שם, ש\"חוה נופל על לשון חי'\" כי הוי\"ו והיו\"ד מתחלפים<sup data-n=\"1222\">19</sup>.\nוא\"כ גם בנדו\"ד לא קשה, כי \"פניאל\" ו\"פנואל\" אינו שינוי אמתי, כיון שהיו\"ד והוי\"ו מתחלפים.\nאבל בלשון רש\"י שם מובן, שאין כוונת רש\"י (כבמפרשים הנ\"ל) שהיו\"ד והוי\"ו מתחלפים — שהרי ענין החילוף לא נזכר ברש\"י שם<sup data-n=\"1223\">20</sup> — אלא שזהו ע\"ד החילוק בין תיבת \"הי'\" ו\"הוה\" (כהדוגמא שבפרש\"י שם):\nהפירוש של תיבת \"הוה\" (בכתוב \"מה הוה לאדם\") הוא — תיבת \"הי'\" בתוכן הוה, ד\"הי'\" הוא לשון עבר, ו\"הוה\" הוא לשון הוה [וע\"ד מ\"ש<sup data-n=\"1224\">21</sup> \"הנה יד ה' הוי' במקנך גו'\", ובפרש\"י \"לשון הוה, כי כן יאמר בלשון נקבה על שעבר היתה ועל העתיד תהי' ועל העומד הוי' כמו עושה רוצה רועה\", וכן בלשון זכר, ד\"על ה­עומד\" אמרינן \"הוה\"<sup data-n=\"1225\">22</sup>].\nוזהו גם הטעם לשם \"חוה, כי היא היתה אם כל חי\", דזה ששם \"חוה נופל על לשון חי'\" הוא לפי ש\"חוה\" ו\"חי'\" הם",[["1215","12","משא\"כ להראב\"ע שם בפי' הב' (ומסיים \"כי העברים ישמרו הטעמים ולא המלות\". ועיין בארוכה ראב\"ע יתרו כ, א. ואתחנן ה, ה)."],["1216","13","ראה בארוכה בזה לקו\"ש ח\"י ע' 93 ובהערות שם."],["1217","14","דאותיות אהו\"י מתחלפים (ראה ראב\"ע שמות (ג, טו) ובחידתו הנדפסת בהקדמת פירושו עה\"ת. ובכ\"מ). וראה הערה 19."],["1218","15","ג, כ."],["1219","16","ראה לקמן הערה 23."],["1220","17","קהלת ב, כב."],["1221","18","ראה מדרש לקח טוב שם. מושב זקנים. ועוד."],["1222","19","וכמ\"ש בגו\"א שם \"כי אותיות אהו\"י מתחל­פים\" (וכ\"כ באמרי שפר שם). וראה גם רש\"י חוקת (כא, יד) \"את והב, כמו את יהב\". ובכמה מפרשים (באר מים חיים (לאחי המהר\"ל) ובאר יצחק) שכוונת רש\"י כי אותיות אהו\"י מתחלפות. וראה מדרש לקח טוב ורשב\"ם שם."],["1223","20","ע\"ד לשונו במ\"א \"שכל האותיות שמו­צאיהם ממקור אחד מתחלפות זו בזו\" (רש\"י קדושים יט, טז. וראה רש\"י ח\"ש כה, ג). וראה רש\"י נשא (ז, כ) בענין חילוף אותיות ע\"י א\"ת ב\"ש."],["1224","21","וארא ט, ג."],["1225","22","ראה באר יצחק על פרש\"י שם."]]],[1301670201,"שורש אחד, והשינוי בין היו\"ד והוי\"ו הוא רק בשימוש התיבה<sup data-n=\"1226\">23</sup> (ע\"ד \"הי'\" ו­\"הוה\"<sup data-n=\"1227\">24</sup>).\nוהטעם שלא הסתפק רש\"י בהפי' שה­יו\"ד והוי\"ו מתחלפים, י\"ל, שהוא בהתאם לשיטתו הנ\"ל דכאשר נתפרש בכתוב טעם השם, יש לדייק כפי האפשרי ש­אותיות השם תהיינה בדיוק ממש כטעם השם.\nועפ\"ז צריך ביאור בנדו\"ד, דכיון ש­לשיטת רש\"י יש לדייק בשמות כפי האפשרי, א\"כ [גם את\"ל ששם פנואל \"נופל על לשון\" \"ראיתי אלקים פנים אל פנים\" (פני א­ל), כי הוי\"ו והיו\"ד מתחל­פים, מ\"מ] מדוע משנה הכתוב מ\"פניאל\" ל\"פנואל\" (שאינו בדיוק)?\nג. ויש לומר, שגם \"פניאל\" ו\"פנואל\" הוא ע\"ד הא ד\"חוה נופל על לשון חי'\", ד\"פניאל\" ו\"פנואל\" היינו הך, כי החילוק בין היו\"ד והי\"ו אינו בעיקר התיבה אלא רק בשימוש התיבה.\nואין רש\"י צריך לפרש טעם החילוק בין שימוש היו\"ד ושימוש הו' בב' ה­שמות ד\"פניאל\" ו\"פנואל\" — כי מובן הוא מהכתוב עצמו:\nבטעם השם \"פניאל\" נאמר \"כי ראיתי אלקים פנים אל פנים\", ונמצא ששני \"פנים\" יש כאן, פני יעקב ופני האלקים. ועפ\"ז מובן בפשטות, שב' השמות הם על אותו המאורע, אלא שבהיות יעקב במקום שבו ראה פני האלקים, קרא המקום \"פניאל\" על שם \"פני א­ל\", ואילו \"כאשר עבר\" מן המקום, נקרא \"פנואל\" על שם פניו (של יעקב) שראו אלקים — \"פנו א­ל\" [ד\"פנו\" נופל על לשון \"פניו\", כאילו נאמר \"פניו (אל) א­ל\"].\nופירוש זה מתאים גם עם הפירוש הפנימי בכתוב זה, דהנה מבואר באוה\"ת להצ\"צ<sup data-n=\"1228\">25</sup>, ד\"פניאל כי ראיתי אלקים פנים אל פנים\" הוא כענין מה שנאמר<sup data-n=\"1229\">26</sup> \"לך אמר לבי בקשו פני את פניך הוי' אבקש\", שהיא העבודה מצד פנימיות הלב, שבה מתגלית בחינת \"פניך הוי'\", הפנימיות שלמעלה, להיות בגילוי \"פנים אל פנים\".\nונמצא שיש כאן שני ענינים: \"בקשו פני\" — שהקב\"ה \"מבקש\" את הפנימיות דהאדם, ו\"את פניך הוי' אבקש\", שהאדם מבקש ונמשך להפנימיות דלמעלה. והם הם שני הענינים ד\"פניאל\" ו\"פנואל\", הפנימיות דלמעלה (פני א­ל) ופנימיות הלב שלמטה (פנו א­ל)<sup data-n=\"1230\">27</sup>.",[["1226","23","ועפ\"ז יש לבאר זה שרש\"י מוסיף שם \"(נו­פל על לשון חי') שמחי' את ולדותי'\" — דלכאורה, הרי מפורש בכתוב שטעם השם הוא לפי ש\"היא היתה אם כל חי\", ולמה הוצרך רש\"י להוסיף \"ש­מחי' את ולדותי'\" (וראה באר מים חיים (לאחי המה­ר\"ל) ובאר בשדה על פרש\"י שם)?\nאלא יש לומר\n[נוסף על פשטות הענין, שבזה מתורץ הטעם שנקראה \"חוה\" ש\"נופל על לשון חי'\" (בתוספת ה\"א, \"לא \"חי\"), ד\"חי'\" היינו מיילדת, ש\"מחי' את ולדותי'\", ועד\"ז נקראת ה\"אם\" (\"אם כל חי\") בשם \"חי'\" — הנה עוד זאת]\nשבזה יומתק הטעם שנקט \"חוה\" באות ו' (ולא \"חי'\"), המורה על ענין הווה ותמידי (ע\"ד תיבת \"הוה\"), ולכן מפרש \"שמחי' את ולדותי'\", ולא רק \"היא היתה אם כל חי\", ענין שבעבר."],["1227","24","ולהעיר מחזקוני בראשית שם \"חוה, לשון חיות, מגזירת הי' הוה\"."],["1228","25","פרשתנו רמ, ב ואילך. שם כרך ה' תתעח, ב ואילך. וראה גם פלח הרמון פרשתנו (צה, סע\"ד ואילך)."],["1229","26","תהלים כז, ח."],["1230","27","ראה אוה\"ת שם רמב, א (בחצע\"ג). שם כרך ה' תתעט, סע\"א ואילך [ושם, ד\"פנואל\" היינו \"פנו אליו ית'\", ולכאורה מפרש \"פנו\" מלשון \"פני'\", שהאדם פונה אליו ית'. וראה לקמן בפנים ס\"ד וס\"ו]. וראה פלח הרמון שם (צו, ג­ד)."]]],[1301670202,"ד. והנה באוה\"ת שם<sup data-n=\"1231\">28</sup> יש עוד פירוש בהשינוי מ\"פניאל\" ל\"פנואל\", ד\"פניאל\" היא עצם העבודה שמצד פנימיות הלב כנ\"ל, וזהו גם מה שנאמר \"פניאל\" ביו\"ד, כי ההתקשרות והדביקות עם הפנימיות דאלקות קשורה עם ביטול מציאות ה­תחתון, עד שלא נשאר ממנו אלא נקודה בעלמא, בדוגמת הנקודה דאות יו\"ד; אמנם תכלית העבודה היא — להמשיך אלקות בעולם, וזהו שלאחרי \"פניאל, כי ראיתי אלקים פנים אל פנים\", בא הענין ד\"ויזרח לו השמש כאשר עבר את פנו­אל\", בוא\"ו, שהוא המשכת אלקות בעולם (כידוע דאות ו' \"מורה על (וציורה) המשכה מלמעלה למטה\"<sup data-n=\"1232\">29</sup>).\nופירוש זה, ד\"פנואל\" בוא\"ו מורה על ההמשכה למטה בעולם, מתאים עם פירוש הבחיי<sup data-n=\"1233\">30</sup> בטעם השינוי מ\"פניאל\" ל\"פנו­אל\", ד\"בהיות מחשבתו משוטטת בענין המלאך קרא את שם המקום פניאל ביו\"ד לרמוז על המלאך הזה שהוא העשירי במעלות המלאכים הנקראים אישים<sup data-n=\"1234\">31</sup> ו­כאשר עבר את המקום ההוא ונתפשט מן המחשבה הזאת חזר כבתחילה להרגשות העולם הזה שהוא שש קצוות על כן הזכיר פנואל בוי\"ו\".\nועד\"ז פירש הרב המגיד<sup data-n=\"1235\">32</sup>, ד\"מתחילה כשגבר יעקב [על] שרו של עשו עדיין לא הי' התגלות [בעולם]. . כתיב פניאל ביו\"ד, בנעלם, ואח\"כ כתיב ויזרח לו ה­שמש כאשר עבר, דהיינו שעבר המשכה שנית להתגלות והי' לו כח שיגביר ידו על עשו [לא רק על \"שרו של עשו\" הרוחני, אלא על עשו כפשוטו] קרא ה­מקום פנואל בו' שכבר נמשך בהתגלות\".\nויש לומר, שחילוק זה בין \"פניאל\" (ביו\"ד) ו\"פנואל\" (בו') מתאים גם עם החילוק שבפירוש ב' תיבות אלו — \"פני א­ל\" או \"פנו א­ל\": \"פני א­ל\" היינו הפנימיות דאלקות, היינו האור האלקי שלמעלה מן העולם; ו\"פנו א­ל\" — מלשון פני'<sup data-n=\"1236\">33</sup> ונטי' — היינו כפי שהאור האלקי \"פונה\" (נוטה) ונמשך מלמעלה למטה להאיר בעולם.\nובפשטות נראה, שפירוש זה ב\"פנו­אל\" הוא היפך מפירוש הנ\"ל (ס\"ג) ב­\"פנואל\" שקאי על פנימיות הלב דהאדם (ה\"מבקשת\" הפנימיות דלמעלה, \"פניך הוי'\"), שהרי לפירוש זה קאי על ההמש­כה למטה בעולם.\nאבל כיון שב' השמות ד\"פניאל\" ו­\"פנואל\" הם של מקום אחד, מסתבר לומר, שלכל הפירושים, גם השם \"פנו­אל\" שייך להעבודה שמצד פנימיות הלב.\nה. ויובן זה בהקדם השאלה בפירוש הנ\"ל ב\"פניאל\", דקאי על העבודה מצד פנימיות הלב שבה מתגלה הפנימיות דאלקות (\"פניך הוי'\") — דלכאורה, כיצד מתאים פירוש זה עם הפירוש הפשוט בכתוב, ש\"ראיתי אלקים פנים אל פנים\" קאי על מלחמת יעקב עם \"שרו של עשו\", שאין הם רק שני פירושים שונים והפכיים<sup data-n=\"1237\">34</sup>, אלא תנועות בעבודת ה', הפכיות מן הקצה אל הקצה.",[["1231","28","ראה אוה\"ת שם רמב, ב ואילך. וראה שם כרך ה' תתפא, א­ב. וראה סה\"מ עת\"ר ע' צא. וראה ע\"ד הקבלה לקוטי לוי\"צ אגרות קודש (ע' רכא­ב). ועוד."],["1232","29","ל' אדה\"ז בתניא אגה\"ת פ\"ד (צד, ב)."],["1233","30","פרשתנו לב, ל (בסופו)."],["1234","31","וראה גם רמב\"ם הל' יסוה\"ת פ\"ב ה\"ז."],["1235","32","בספרו אור תורה פרשתנו עה\"פ."],["1236","33","ראה תוס' השלם (ירושלים, תשד\"מ) פרשתנו כאן (אות ד'), \"ולכשעבר קראו פנואל כלומר לבני אדם פנו אל אותו מקום\"."],["1237","34","ראה תו\"א פרשתנו ד\"ה ויאבק, שמלחמה זו (דשרו של עשו עם יעקב) היא מלחמת הס\"מ בסטרא דקדושה. ע\"ש."]]],[1301670203,"דהנה החילוק בין העבודה שמצד חיצוניות הלב הקשורה עם החיצוניות דאלקות, להעבודה ד\"בקשו פני את פניך הוי' אבקש\", הוא:\nהעבודה מצד חיצוניות הלב, קשורה עם ההתבוננות בגדלות הא­ל כפי שבאה לידי ביטוי בבריאת העולמות, \"מה רבו מעשיך ה'\" ו\"מה גדלו מעשיך ה'\", שזהו ענין החיצוניות דאלקות, היינו כפי ש­הקב\"ה מצמצם את עצמו כביכול לברוא את העולמות ולהחיותם, שזוהי השפלה לגבי הקב\"ה עצמו; אך ישנה עבודה נעלית יותר, שהאדם \"מבקש\" את הפני­מיות דאלקות, פנימיותו של הקב\"ה כפי שהוא ית' למעלה מכל העולמות — \"ולגדולתו אין חקר\", שהתגלות הפני­מיות דאלקות היא בפנימיות הלב וה­נשמה.\nוהנפק\"מ בעבודה בפועל — דכאשר האדם \"מבקש\" ומגלה רק את החיצוניות דאלקות, שמצד בחינה זו יש תפיסת מקום לעולמות, הרי עבודתו היא בדרך מלחמה, שצריך להתגבר על המניעות ועיכובים, הן מבפנים (מצד יצרו הרע כו') והן מבחוץ, עד שמצליח לנצחם כו'; משא\"כ כאשר מתגלה אצלו \"פניך הוי'\", הפנימיות דאלקות שלמעלה מהעולמות, ה\"ה בתכלית ההתקשרות והדביקות בו ית', באופן שאין שייך אצלו שום מונע ומעכב.\nועפ\"ז, כיצד מתאים הפירוש הנ\"ל ב\"ראיתי אלקים פנים אל פנים\", דקאי על העבודה מצד פנימיות הלב שבה מתגלה \"פניך הוי'\", עם הפירוש הפשוט דקאי על מלחמתו של יעקב עם שרו של עשו (באופן של \"ויאבק<sup data-n=\"1238\">35</sup> איש עמו\", בדרך התאבקות זע\"ז)?\nויש לומר, שהתיווך בין הפירוש ה­פנימי והפירוש הפשוט ב\"פניאל\", מובן ע\"פ הביאור הפנימי בשני השמות \"פני­אל\" ו\"פנואל\", דלאמיתתו הרי הם ענין אחד (כשם שהם שמות למקום אחד), כי אין השינוי בין הי' לו' שבשם זה עושה שינוי וחילוק בתוכן השם.\nו. הסברת הענין:\nזה שאות יו\"ד שהיא נקודה בלבד, ואות ו' ה\"מורה על ההמשכה מלמעלה למטה\", הם שני הפכים זמ\"ז — שהביטול דאות יו\"ד מורה על הגילוי דפנימיות האלקות, שמצדה אין מקום לשום דבר בלעדו ית', ואילו הו' מורה על האור ה­אלקי כפי שנמשך מלמעלה למטה בתוך גדרי העולם — ה\"ז רק מצד ה\"גילויים\" דאלקות, שההתגלות דפנימיות האלקות היא למעלה מגדר העולמות (ופועלת בהם ביטול, נקודה דאות יו\"ד), ורק ה­התגלות המצומצמת של האור האלקי נמשכת במציאות העולמות (והיא הנרמזת באות וי\"ו);\nאבל מצד הפנימיות והעצמיות ד­אלקות, כפי שהוא ית' למעלה מהגדרים ד\"מעלה\" ו\"מטה\", הרי הוא נמשך בכל מקום בשווה, למטה כמו למעלה. ואזי אין חילוק בין הביטול דאות י' לההמ­שכה דאות ו', שהביטול דאות יו\"ד, שהוא ביטול מוחלט (מצד התגלות ה­אלקות שלמעלה מן העולמות), נמשך במציאות העולם עצמה, חיבור דאות יו\"ד ואות ו'.\nויש לומר, שענין זה נרמז בפירוש שני השמות \"פניאל\" ו\"פנואל\" — \"פני\nא­ל\" ו\"פנו א­ל\":\nעה\"פ<sup data-n=\"1239\">36</sup> \"ונתתי פני בכם\" פרש\"י \"כמו",[["1238","35","פרשתנו לב, כה. ובפרש\"י שם \"לשון ויתקשר. . שכן דרך שנים כו'\"."],["1239","36","בחוקותי (כו, יז), בפי' השני מ\"אגדת תו\"כ\" (משא\"כ בפי' הא' שם \"ונתתי פני, פנאי שלי פונה אני כו'\". וראה הערה 38)."]]],[1301670204,"שנאמר בטובה<sup data-n=\"1240\">37</sup> ופניתי אליכם כך נאמר ברעה ונתתי פני משלו משל למלך ש­אמר לעבדיו פונה אני מכל עסקי ועוסק אני עמכם כו'\", שמפשטות ל' רש\"י מובן, שמפרש תיבת \"פני\" מלשון \"פני'\"<sup data-n=\"1241\">38</sup> (כמו ל' \"ופניתי\"), וענינה של \"פני'\" הנרמזת בלשון \"פני\" (מלשון פנים) הוא — ש­\"פונה אני מכל עסקי ועוסק אני עמכם\", היינו \"פני'\" בכל מהותו ועצמותו<sup data-n=\"1242\">39</sup> (של­כן נרמזת בלשון \"פני\", המורה על הפני­מיות והעצמיות, כפרש\"י עה\"פ<sup data-n=\"1243\">40</sup> \"פני ילכו\" — \"אני בעצמי אלך\"), ש\"פני'\" זו אינה קשורה עם צמצום כו', אלא זהו כפי שהוא ית' פונה בכל עצמותו לישר­אל.\nו\"פני'\" זו שמצד עצמותו ית', נמשכת למטה כמו למעלה, חיבור דאות יו\"ד ואות ו' כנ\"ל.\nוזהו גם התיווך בין שני הפירושים ב\"פניאל\" — העבודה שמצד פנימיות הלב, ומלחמתו עם \"שרו של עשו\" — שאין הם שני ענינים שונים, אלא היינו הך, כי שלימות העבודה ד\"בקשו פני את פניך הוי' אבקש\" היא כאשר הביטול שמצד פנימיות הלב נמשך בגלוי בכל תוקפו בכל עניניו (גם בחיצוניות שלו), וכן הי' אצל יעקב, דמלחמתו עם \"שרו של עשו\" היתה בכח דביקותו בה' מצד פנימיות הלב, דגם כפי ש\"ירד\" ונמשך להתעסק עם \"שרו של עשו\" (להתגבר עליו ולנצחו) לא נתמעט מדרגת דבי­קותו וביטולו לה', שהי' בביטול מוחלט זה בכל מצב.\nשזהו גם מה שנצחונו על שרו של עשו הי' באופן של \"שרית עם אלקים\"<sup data-n=\"1244\">41</sup>, מלשון שררה, שענין ההתאבקות הי' רק מצד ה\"איש\" (ויאבק איש), שרו של עשו, אבל מצד יעקב הי' הנצחון באופן של \"שררה\", כיון שנצחונו הי' בכח דביקותו באלקות באופן ד\"ראיתי אלקים פנים אל פנים\", כנ\"ל.\n<span data-k=\"q\">(משיחות יו\"ד כסלו, ש\"פ וישלח וש\"פ וישב תשמ\"א)</span>",[["1240","37","בחוקותי שם, ט."],["1241","38","משא\"כ ל' \"פני\" שבפ' אחרי (יז, י) וקדושים (כ, ג) שפרש\"י \"פונה אני מכל עסקי כו'\", הרי מקדים שם \"פנאי שלי\", ומשמע שמפרש תיבת \"פני\" מלשון \"פנאי\" (אבל ראה גו\"א שם). ועד\"ז בבחוקותי שם בפי' הא', כנ\"ל הערה 36.\nמשא\"כ לפי \"אגדת תו\"כ\" ד\"ונתתי פני\" הוא \"כמו שנאמר בטובה ופניתי אליכם\", מובן, שפירושו מלשון \"פני'\" (כמו \"ופניתי\", וכפרש\"י שם), ולא מלשון \"פנאי\" (והרי בפי' זה לא הקדים רש\"י \"פנאי שלי\". וראה באר יצחק שם. אבל ראה רא\"ם קדושים שם). — וראה גם לקו\"ש חי\"ז ע' 322 הערה 11. וש\"נ."],["1242","39","ראה בארוכה בזה לקו\"ש שם ע' 328 ואילך."],["1243","40","תשא לג, יד."],["1244","41","פרשתנו לב, כט."]]],[1301670205,"<h3>שיחה ב</h3>\nא. בפסוק<sup data-n=\"1245\">1</sup> \"וישב ביום ההוא עשו לדרכו שעירה\" מעתיק רש\"י את התי­בות<sup data-n=\"1246\">2</sup> \"וישב ביום ההוא עשו לדרכו\", ומפרש: \"עשו לבדו<sup data-n=\"1247\">3</sup>, וד' מאות איש ש­הלכו עמו נשמטו מאצלו אחד אחד\".\nוכבר שקו\"ט במפרשים מנין לו ל­רש\"י בפשוטו של מקרא שהד' מאות איש נשמטו מאצל עשו, ולא הלכו עמו. וכמו גבי יעקב, שנאמר<sup data-n=\"1248\">4</sup> \"ויעקב נסע סכותה\" ולא נזכר ע\"ד \"העם אשר אתו\"<sup data-n=\"1249\">5</sup> — (כיון שטפלים אליו) — כך גם בעשו לא חש הכתוב לפרטם להיותם טפלים אליו.\nהרא\"ם מחלק, דכיון שעשו ביקש מ­יעקב \"אציגה נא עמך מן העם אשר אתי\"<sup data-n=\"1250\">6</sup>, הי' צריך הכתוב לפרש שהעם לא נשאר עם יעקב, כי יעקב לא רצה טובה זו<sup data-n=\"1251\">7</sup>. וכבר השיגו עליו<sup data-n=\"1252\">8</sup>, שדבר זה כבר מובן ממענה יעקב \"למה זה אמצא חן בעיני אדוני\"<sup data-n=\"1250\">6</sup> (וכפרש\"י \"למה זה תעשה לי טובה זו שאיני צריך לה, אמצא חן. . ולא תשלם לי עתה שום גמול\").\nבגור ארי' פי' שרש\"י דייק לה<sup data-n=\"1254\">9</sup> כי \"הוי למיכתב וישב עשו ביום ההוא, מאי וישב ביום ההוא עשו, אלא כך פירוש וישב ביום ההוא ומי הוא ששב — עשו ולא אנשיו\".\nולכאורה גם פירוש זה צ\"ע, שהרי דרך הכתובים לדבר כך, וכדמצינו ברי­בוי מקומות כגון דא [לדוגמא — לעיל בפ' לך לך<sup data-n=\"1255\">10</sup> \"ויחלק עליהם לילה הוא ועבדיו\", ופירש\"י \"לפי פשוטו סרס ה­מקרא, ויחלק הוא ועבדיו עליהם לילה\"].\nגם אינו מובן, למה העתיק רש\"י בהד\"ה גם תיבת \"לדרכו\"<sup data-n=\"1256\">11</sup> — הרי אינו מפרש אלא התיבות<sup data-n=\"1257\">12</sup> \"וישב גו' עשו\"<sup data-n=\"1258\">13</sup>.\nולכאורה נ\"ל, שההכרח של רש\"י ש­פירוש הכתוב הוא \"עשו לבדו\" אינו מדיוק לשון הכתוב, אלא מתוכן תיבות הכתוב (שהועתקו בהד\"ה) — \"וישב ביום ההוא עשו לדרכו\", כדלקמן.",[["1245","1","פרשתנו לג, טז."],["1246","2","כ\"ה בדפוסי רש\"י הנפוצים. וראה לקמן הערה 11, 13."],["1247","3","כ\"ה בדפוסי רש\"י הנפוצים. אבל בדפוס א' וב' דפרש\"י, ובכת\"י רש\"י (שתח\"י), ליתא תיבות אלו."],["1248","4","שם, יז."],["1249","5","פרשתנו לב, ח."],["1250","6","לג, טו."],["1251","7","ובעוד מפרשים (הואיל משה (באר היטב) ומלאכת הקודש) חילקו בין לשון \"נסע\" [דלשון נסיעה הוא דוקא במי שהלך עם בני ביתו — ביאורי מהרא\"י (לבעל תרוה\"ד) על פרש\"י פרשתנו לג, יב] ולשון \"וישב\". אבל ראה ויצא לב, א (\"וישב לבן\"), ועוד. וצ\"ע."],["1252","8","יפה תואר (השלם) לב\"ר כאן (פע\"ח, טו). וראה נחלת יעקב על פרש\"י."],["1250","6","לג, טו."],["1254","9","וכ\"ה בהואיל משה (באר היטב). באר מים חיים (לאחי המהר\"ל). דבק טוב.\nבבאר בשדה על פרש\"י תי' שרש\"י מדייק לה מתיבות \"ביום ההוא\" שלכאורה מיותרות, וע\"ז פי' שרק עשו שב ביום ההוא, משא\"כ הד' מאות איש שנשמטו מאצלו לפנ\"ז. אבל פירושו צ\"ע, שהרי גם בריחת ד' מאות איש היתה \"ביום ההוא\" (ראה לקמן הערה 37). ועוד."],["1255","10","יד, טו."],["1256","11","ולהעיר, שבדפוס א' וב' דפרש\"י, וכן ב­כת\"י רש\"י (שתח\"י), לא נעתק \"לדרכו\"."],["1257","12","אבל מ\"ש \"ביום ההוא\" י\"ל (לפי הגו\"א) שזה מדגיש שתיבת \"עשו\" היא שלא במקומה."],["1258","13","ולהעיר, שבדפוס שני וכמה כת\"י רש\"י (שתח\"י) הד\"ה הוא \"וישב עשו\"."]]],[1301670206,"ב. בסוף פרשת ויצא<sup data-n=\"1259\">14</sup> מסופר, שכ­אשר ברח יעקב מלבן, רדף לבן (עם קרוביו<sup data-n=\"1260\">15</sup>) אחרי יעקב, ולולא שבא אל­קים אל לבן בחלום לילה<sup data-n=\"1261\">16</sup> והזהירו מלדבר עם יעקב \"מטוב ועד רע\" הי' מרע לו<sup data-n=\"1262\">17</sup>.\nועפ\"ז קשה להבין בנדו\"ד גבי עשו, שרצונו להרע ליעקב הי' הרבה יותר מלבן, כמ\"ש<sup data-n=\"1263\">18</sup> \"וישטום עשו את יעקב גו' ויאמר גו' ואהרגה את יעקב גו'\" — ולתכלית זו הלך לקראת יעקב עם ד' מאות איש<sup data-n=\"1264\">19</sup>, שהיתה שנאה זו כבושה אצלו במשך הרבה שנים — וכיצד יתכן שוויתר לגמרי על מזימותיו ושב ל­דרכו?\nואע\"פ שבראות עשו את יעקב, \"ויחב­קהו גו' וישקהו ויבכו\"<sup data-n=\"1265\">20</sup> — הרי לא מי­בעי לפירוש הראשון ברש\"י שם \"שלא נשקו בכל לבו\", ודאי קשה מדוע לא המשיך במזימותיו; אלא אפילו לפירוש השני (דעת רשב\"י) \"שנכמרו רחמיו ב­אותה שעה ונשקו בכל לבו\" — הרי מדייק רש\"י שזה הי' רק \"באותה שעה\" [שזהו הטעם<sup data-n=\"1266\">21</sup> ש\"נקוד עליו\" (על תיבת \"וישקהו\"), שניקוד בכל מקום מורה על מיעוט בהמנוקד — כי אף שנשק אותו \"בכל לבו\", מ\"מ לא היתה אהבה אמי­תית, רק דרך עראי, \"באותה שעה\"].\nואדרבה: בפירוש הב' גופא, מקדים רשב\"י \"הלכה היא, בידוע שעשו שונא ליעקב\", וכמשנ\"ת במ\"א<sup data-n=\"1267\">22</sup> דיוק ל' זה (ששנאת עשו ליעקב הו\"ע של \"הלכה\") — דכמו שלא יתכן ביטול או שינוי בהלכות של תורה<sup data-n=\"1268\">23</sup>, כך שנאת עשו היא תמידית ונצחית.\n[וזהו גם דיוק ל' רש\"י \"אלא שנכמרו רחמיו באותה שעה ונשקו בכל לבו\" — ע\"ד שמצינו ב\"הלכה\", שישנו ענין של \"הוראת שעה\", שעושים שלא כהלכה (כאליהו בהר הכרמל)<sup data-n=\"1269\">24</sup>, שגם אז ההלכה היא בתקפה ולא נשתנית<sup data-n=\"1270\">25</sup>, אלא שיש הוראה לאותה שעה לעשות היפך ה­הלכה; וכך בעניננו, שגם בשעה ההיא לא נתבטלה שנאת עשו ליעקב (כי היא \"הלכה\"), אלא שלפי שעה נשקו בכל לבו].\nומזה מובן, שאחרי זה חזר עשו למצב של שנאה גלוי' ליעקב<sup data-n=\"1271\">26</sup>. ועד שגם יעקב חשש מזה, וכמפורש בפרש\"י על דברי יעקב לעשו \"כי על כן ראיתי פניך כראות פני אלקים\"<sup data-n=\"1272\">27</sup>, שיעקב \"הזכיר לו ראיית המלאך כדי שיתירא הימנו ויאמר ראה מלאכים וניצול, איני יכול לו מ­עתה\" (שזה הי' כבר לאחרי ש\"וישקהו\"); וכן פרש\"י על דברי יעקב \"עד אשר אבוא אל אדוני שעירה\"<sup data-n=\"1273\">28</sup> (שיעקב לא רצה שעשו ילך עמו, אלא \"יעבר<sup data-n=\"1273\">28</sup> נא אדוני לפני עבדו ואני אתנהלה לאטי גו' עד אשר אבוא גו'\") — \"הרחיב לו הדרך,",[["1259","14","לא, כב ואילך."],["1260","15","רש\"י שם, כג."],["1261","16","שם, כד."],["1262","17","שם, כט. וראה רש\"י פרשתנו לג, יח. רש\"י תבוא כו, ה."],["1263","18","תולדות כז, מא."],["1264","19","ריש פרשתנו (לב, ז), וברש\"י שם \"עודנו בשנאתו\"."],["1265","20","לג, ד."],["1266","21","ראה בכ\"ז בארוכה לקו\"ש ח\"כ ע' 149."],["1267","22","לקו\"ש שם ע' 150."],["1268","23","רמב\"ם הל' יסוה\"ת רפ\"ט. וראה גם סוף הל' מגילה. ועוד."],["1269","24","רש\"י ראה (יב, יג) ושופטים (יח, כב)."],["1270","25","ראה רמב\"ם הל' יסוה\"ת שם ה\"ג."],["1271","26","ראה גם עץ הדעת טוב (להרח\"ו) פרשתנו כאן."],["1272","27","לג, יו\"ד."],["1273","28","שם, יד."],["1273","28","שם, יד."]]],[1301670207,"שלא הי' דעתו ללכת אלא עד סוכות, אמר אם דעתו לעשות לי רעה ימתין עד בואי אצלו והוא לא הלך\" — הרי שגם יעקב חשש<sup data-n=\"1275\">29</sup> שעשו ירצה לעשות לו רעה.\nועפ\"ז י\"ל עוד יותר, שחשש יעקב שזו היא כוונת עשו בבקשתו \"ואלכה לנגדך\"<sup data-n=\"1276\">30</sup>, וכן \"אציגה נא עמך מן העם אשר אתי\"<sup data-n=\"1250\">6</sup> — שחיפש אופנים איך יוכל להפיק זממו במשך הזמן<sup data-n=\"1278\">31</sup> (וזהו הטעם שיעקב לא הסכים לכך, כי הרגיש בזה).\nוע\"פ כ\"ז תמוה — מדוע שב עשו לדרכו תיכף \"ביום ההוא\", ולא המשיך בתחבולותיו להרע ליעקב<sup data-n=\"1279\">32</sup>?\nולתרץ שאלה זו פרש\"י — \"עשו לב­דו, וד' מאות איש שהלכו עמו נשמטו מאצלו\", ולכן לא הי' ביכולתו של עשו לעשות מאומה נגד יעקב (שהלך עם מחנה גדול כו'), כיון שנשאר לבדו. ולכן \"וישב ביום ההוא עשו לדרכו\".\nג. עפ\"ז מתורץ גם דיוק לשון רש\"י, שכ' \"(נשמטו מאצלו) אחד אחד\" — דלכ­אורה מנ\"ל לרש\"י הא (ולא שהלכו כולם בב\"א). גם — למאי נפק\"מ?\nיש מפרשים<sup data-n=\"1280\">33</sup>, דכיון שא\"ל \"אציגה נא עמך וכו', ש\"מ דאכתי הוו גברי עמי', וליכא למימר דכולהו בתר הכי נש­מטו<sup data-n=\"1281\">34</sup>, דלמה נשארו ע\"ע ולא נשמטו מיד, אלא שצ\"ל שהיו נשמטים א' א' כדי שלא ירגיש עשו שהולכים, ובשעה דא\"ל אציגה וכו' אכתי הוו קיימי קצתם\". ויש שפירשו<sup data-n=\"1282\">35</sup> שרש\"י כ' זה מסברא, \"כיון שעשו הי' אדוניהם מסתמא יראים היו לילך מבלי רשותו והיו בורחים ונגנבים מעמו אחד אחד\".\nבכל אופן השאלה למאי נפק\"מ באיזה אופן נשמטו מאצלו, אם בבת אחת או א' א', במקומה עומדת?\nוע\"פ הנ\"ל י\"ל דרש\"י קמ\"ל, כי בזה מודגש עוד יותר שעשו לא נשתנה כלל, ומצדו הי' ממשיך להפיק זממו להרע ליעקב אלא שנשאר לבדו — והראי', ש­אפילו הד' מאות איש שנשמטו מאצלו לא נתבטלה שנאתם ליעקב,\nכדמוכח מזה שלא נתקו את עצמם מעשו כולם ביחד בריש גלי (לעשות היפך רצונו של עשו), ורק נשמטו מאצלו א' א'; והיינו, כי היו ממשיכים להשאר עם עשו כדי להלחם עם יעקב, אלא שהיו יראים לנפשם ולכן נשמטו וברחו\n[וסיבת יראתם מובנת ע\"פ פרש\"י לעיל<sup data-n=\"1283\">36</sup> שעשו ואנשיו פגעו \"כתות של מלאכים. . שהיו דוחפין אותו ואת אנשיו ואומרים להם כו' הכו הכו כו' (עד שהיו אומרים) אחיו של יעקב הוא\"<sup data-n=\"1284\">37</sup>]\n— וא\"כ כ\"ש וק\"ו שעשו לא נהפך לבו כלל.\nויש להוסיף ולהמתיק הענין ע\"פ",[["1275","29","וי\"ל שזהו דיוק ל' רש\"י \"הלכה היא בידוע כו'\" ש\"הלכה\" זו היא ידועה ומפורסמת לכל, ולכן חשש יעקב מעשו (אף שבאותה שעה נשקו בכל לבו). — בפשטות מוכרחת הוספת \"בידוע\" — שזהו פשוטו של מקרא."],["1276","30","שם, יב."],["1250","6","לג, טו."],["1278","31","אבל ראה לקו\"ש שם (ע' 151) באו\"א."],["1279","32","ובתיב\"ע כאן \"ואתעביד ניסא ליעקב ותב ביומא ההוא עשו כו'\"."],["1280","33","משכיל לדוד."],["1281","34","להעיר מריב\"א ורע\"ב עה\"ת כאן."],["1282","35","באר בשדה."],["1283","36","לג, ח. — וראה גם מדרש אגדה (באָבער) כאן. באר בשדה על פרש\"י."],["1284","37","אלא שצע\"ק למה לא התחילו להשתמט מאצלו תיכף אז (ומפורש בכתוב (לג, א) שכולם היו עם עשו כשפגש את יעקב)."]]],[1301670208,"פרש\"י הנ\"ל עה\"פ<sup data-n=\"1273\">28</sup> \"עד אשר אבוא גו'\" — \"הרחיב לו הדרך כו' אם דעתו לע­שות לי רעה ימתין כו', ואימתי ילך בימי המשיח שנאמר<sup data-n=\"1286\">38</sup> ועלו מושיעים בהר ציון לשפוט את הר עשו\", שיש לומר, שבזה מרמז רש\"י, ששנאת עשו ליעקב באופן של \"הלכה\", היא (לא רק בעשו עצמו, אלא) גם בכללות האומה דעשו, \"עשו הוא אדום\"<sup data-n=\"1287\">39</sup> [וכמובן גם מפרש\"י לפני זה עה\"פ<sup data-n=\"1288\">40</sup> \"ולאום מלאום יאמץ\" — \"אין לאום אלא מלכות\", \"כשזה קם זה נופל\"], ולכן \"הרחיב לו הדרך\" עד עת קץ, כי עד אז ישנה ה\"הלכה\" ד\"עשו שונא ליעקב\" ודעתו לעשות לו רעה.\nוזהו שמדייק רש\"י, שגם אצל אנשי עשו לא נתבטלה שנאתם ליעקב, ובעצם היו נלחמים עמו, אלא שמצד יראתם אותו נשמטו וברחו לנפשם.\nד. ובדרך זו יש לבאר גם המשך פרש\"י כאן, וז\"ל: \"והיכן פרע להם הקב\"ה (לד' מאות איש), בימי דוד ש­נאמר<sup data-n=\"1289\">41</sup> כי אם ד' מאות איש נער אשר רכבו על הגמלים\".\nותמוה, שהרי לכאורה, זה אינו אלא דברי אגדה, ואינו ענין לפשוטו של מקרא, ומה מקום להביאו בפרש\"י על התורה<sup data-n=\"1290\">42</sup> (שלא בא אלא לפשוטו של מקרא, או לאגדה המיישבת דברי המקרא<sup data-n=\"1291\">43</sup>). ורש\"י לא הקדים שהם דברי אגדה.\nוביותר תמוה לשון רש\"י \"והיכן פרע כו'\", כאילו שזהו ברור בפשוטו של מקרא שמגיע להם שכר, והשאלה היא רק \"והיכן פרע\"?!\nויש לומר, ע\"פ פרש\"י לעיל<sup data-n=\"1292\">44</sup> גבי בנות לוט, ששם מפרש שהצעירה ש­\"קראתו בלשון נקי'\", \"קבלה שכר בימי משה כו'\" — למדים מזה, שאף שכללות מעשי' לא היו כדבעי, מ\"מ קבלה שכר על הפרט ש\"קראתו בלשון נקי'\", וכן לומדים מזה שפרעון שכר זה יכול להיות לאחרי כמה דורות; וזהו גם פי­רוש רש\"י כאן — \"היכן\" הוא השכר של ד' מאות איש אלה, ומפרש \"בימי דוד\"<sup data-n=\"1293\">45</sup>.\nועדיין צ\"ע: פשוט שאין ענינו של רש\"י בפירושו לבאר בכלל הנהגת ה­קב\"ה (אם ואיך פרע הקב\"ה את ד' מאות אנשי עשו), אלא ודאי שדבר זה נוגע להבנת המקרא כאן.\n[בגור ארי' כ' שרש\"י מביא זה לראי' שהם נשמטו מעשו. אבל פירוש זה צע\"ג, דערבך ערבא צריך: מהי הראי' בפשט",[["1273","28","שם, יד."],["1286","38","עובדי' א, כא."],["1287","39","פרשתנו לו, א. שם, ח."],["1288","40","תולדות כה, כג ד\"ה ושני לאומים וד\"ה מלאום יאמץ."],["1289","41","ש\"א ל, יז."],["1290","42","ובמדרש לקח טוב כאן הביא רק הא דנשמטו מאצלו, ולא ההמשך \"והיכן פרע כו'\"."],["1291","43","רש\"י בראשית ג, ח. ובכ\"מ."],["1292","44","וירא יט, לז. וראה גם רש\"י שם יח, ד. נח ט, כג. — וברש\"י משפטים (כב, ל) \"אין הקב\"ה מקפח שכר כל ברי'\"."],["1293","45","והיינו ג\"כ לאחרי כמה דורות (ולא שהם הם ד' מאות אנשי עשו) — ראה מלאכת הקודש על פרש\"י. וראה גם יפה תואר (השלם) ונזר הקודש (השלם) לב\"ר כאן.\nוי\"ל שלכן העתיק רש\"י מהכתוב תיבת \"נער\"<sup data-n=\"e32\">*</sup> — להדגיש שאינם אנשים ההם (שאז לא היו נערים, אלא אדרבה, זקנים קרובים לז' מאות שנה!). ובלאה\"כ מופרך לפרש כן, כי לא נזכר בשום מקום שקרה נס כזה באנשים אלה."],["e32","*","אלא שבדפוס שני דפרש\"י (ועוד), וכן בכמה כת\"י רש\"י (שתח\"י), לא נעתק תיבת \"נער\". וראה ב\"ר הוצאת תיאודור­אלבק שם בחילופי נוסחאות והערות."]]],[1301670209,"שהצלת ד' מאות איש בימי דוד היא השכר של ד' מאות אנשי עשו?! ובכלל, מה חסר בראי' מלשון הכתוב (כפירוש הגו\"א הנ\"ל ס\"א), או מתוכן הכתוב (כנ\"ל ס\"ב), עד שהוצרך רש\"י להוסיף ראי' זו?].\nגם יש לדייק בלשון רש\"י:\nא) מקורו של פירוש זה הוא בברא­שית רבה על אתר<sup data-n=\"1294\">46</sup>, אבל שם הלשון \"אימתי פרע\", ורש\"י שינה וכתב \"והיכן פרע\"?\nב) במדרש הלשון \"(ואימתי פרע כו') להלן ולא נותר מהם איש כי אם ד' מאות איש נער אשר רכבו על הגמלים וינוסו\", ואילו בפרש\"י הלשון \"בימי דוד שנאמר כי אם ארבע מאות איש נער אשר רכבו על הגמלים\".\nוצ\"ע בלשון רש\"י, שמחד גיסא נחית לפרש יותר, שלכן לא סתים (כבמדרש) \"להלן\" אלא מוסיף ומבאר שזה הי' \"בימי דוד\"; ולאידך, בנוגע לגוף השכר, משמיט התיבות שבהן מפורט השכר — דהיינו תחילת הכתוב \"ולא נותר מהם איש\" (שהשאר נהרגו), וסיום הכתוב \"וינוסו\"<sup data-n=\"1295\">47</sup> (שהם ניצלו)!\nג) לאידך, אף שרש\"י קיצר בהבאת לשון הכתוב, מ\"מ דייק להעתיק התיבות \"אשר רכבו על הגמלים\" שלכאורה אינן מוסיפות בהבנת השכר.\nה. אבל, ע\"פ משנת\"ל שכוונת רש\"י היא לדייק ולהדגיש שגם הד' מאות איש לא נשתנה לבם לטוב כלל, י\"ל, שזוהי גם כוונתו בהמשך פירושו, לחזק ענין זה, כי באופן שכרם של אנשים אלה מודגש איך שבעצם לא נשתנו לטוב.\n[ולכן מדייק רש\"י \"והיכן פרע כו'\" (ולא נקט \"ואימתי\"), כי כאן לא נוגע מתי נפרע להם אלא באיזה אופן פרע להם הקב\"ה, וזה נכלל בשאלת \"והיכן\", היינו לא רק \"באיזה זמן\", אלא באיזה ענין ואופן].\nוע\"ז מביא רש\"י שזה הי' \"בימי דוד\", והיינו שהם נלחמו נגד דוד, כלומר, שאלה שקיבלו השכר לא היו אנשים צדיקים, אדרבה, הם נלחמו נגד דוד מלך ישראל. ועוד זאת, שפרעון השכר הי' במצב זה עצמו, שבה בשעה שנלחמו נגד דוד ניצלו.\nוע\"פ הנ\"ל מובן טעם הדבר, כי זה מדגיש תוכן הענין שעבורו בא להם שכר זה. שהרי אנשי עשו לא נשתנה לבם, ועוד זאת, שמה שנשמטו מעשו, הוא לא מפני שנשתנו לטובה, אלא אך ורק כדי להציל את עצמם (מיראת יעקב כנ\"ל). אך מ\"מ, כיון שבפועל באה עי\"ז טובה ליעקב, שעשו נשאר לבדו ולא הי' יכול להזיקו, לכן קיבלו שכר<sup data-n=\"1296\">48</sup>, ושכר עד\"ז, שאע\"פ שלחמו נגד דוד, והפסידו במלחמה, מ\"מ בפועל ניצלו מהריגה ממש.\nויש לומר, שזהו הטעם שרש\"י משמיט תחילת הכתוב וסופו ומביא רק \"אשר רכבו על הגמלים\", כי אין כוונתו להג­דיל שכרם (שניצלו אף שהשאר נהרגו), אלא אדרבה, להקטין אותו<sup data-n=\"1297\">49</sup> (בהתאם",[["1294","46","פע\"ח, טו."],["1295","47","כ\"ה בדפוס שני דפרש\"י ודפוסים הנפוצים. ובדפוס א' וכמה כת\"י רש\"י (שתח\"י) נעתק גם \"וינוסו\"."],["1296","48","ע\"ד שנת' במ\"א (לקו\"ש חכ\"א ע' 50) בפירוש \"פעולתו אשר עבד בה\" הנאמר גבי נבוכד­נאצר (יחזקאל כט, כ)."],["1297","49","ולהעיר מל' רש\"י \"פרע להם הקב\"ה\", ולא נקט ל' \"שלם\"<sup data-n=\"e33\">*</sup> (וכיו\"ב), הרגיל יותר בענין שכר (ע\"ד לשון רש\"י במקומות שבהערה 44), ואדרבה — ל' \"פרע\" רגיל יותר לענין עונש (ראה רש\"י ר\"פ וארא. אחרי יח, ב. ועוד. ולהעיר מל' רש\"י שמות (ה, א) \"נשמטו א' א'. . ובסיני נפרע להם כו'\")."],["e33","*","ובא' מכת\"י רש\"י (שתח\"י) \"שילם הקב\"ה גמול להם\"."]]],[1301670210,"לכך שלא היתה כאן כוונת טובה ליעקב מצד אנשי עשו). ולרמז זה מעתיק רש\"י רק התיבות \"אשר רכבו על הגמלים\", והיינו, שלא היתה כאן הצלה נסית, שהרי ד' מאות איש אלה \"רכבו על הגמלים\" ולכן היו יכולים לברוח.\nוע\"ד החידוד יש להוסיף, שבהעתקת התיבות \"אשר רכבו על הגמלים\" מרמז רש\"י למחז\"ל<sup data-n=\"1298\">50</sup> על כתוב בתוכן זה — \"ותקם<sup data-n=\"1299\">51</sup> רבקה ונערותי' ותרכבנה על הגמלים\" — \"מה גמל זה יש בו סימן טומאה וסימן טהרה, כך העמידה רבקה צדיק ורשע\".\nומעין זה בנדו\"ד, שהי' כאן תערובת טוב ורע, שבפועל נצמחה מזה טובה ליעקב, בדוגמת הגמל ש\"יש בו סימן טומאה וסימן טהרה\".\nו. והנה פרשת וישלח קוראין לעולם בסמיכות לי\"ט כסלו, חג הגאולה של אדמו\"ר הזקן, בעל התניא והשולחן ע­רוך, וע\"פ דברי השל\"ה הידועים<sup data-n=\"1300\">52</sup>, ש­יש רמז למועדי השנה (כולל מועדים דרבנן) בהפרשיות שחלות בהן, מובן, שיש לחפש רמז להגאולה די\"ט כסלו בפרשת וישלח. — נוסף על אגה\"ק השייכת לי\"ט כסלו בתוכנה ובהתחלתה קטונתי<sup data-n=\"1301\">53</sup> (פסוק שמיני בפ' שמינית — וישלח).\nויש לקשר ענין האמור בפרש\"י עם גאולת י\"ט כסלו, ע\"פ דברי אדמו\"ר הזקן הידועים<sup data-n=\"1302\">54</sup>, שגאולתו היתה בעת שאמר הפסוק<sup data-n=\"1303\">55</sup> \"פדה בשלום נפשי מקרב לי כי ברבים היו עמדי\". ומבואר בכמה מקומות<sup data-n=\"1304\">56</sup> הפירוש בכתוב זה, דמ\"ש \"פדה בשלום\" היינו שהפדי' גופא היא באופן של שלום, ופירוש זה מתאים עם מה שאמרו בירושלמי<sup data-n=\"1305\">57</sup> על \"כי ברבים היו עמדי\", דקאי על אנשי אבשלום, שגם הם התפללו לנצחונו של דוד.\nוהנה פשטות הפירוש במרז\"ל זה הוא, שבה בשעה שאנשי אבשלום נלחמו נגד דוד, התפללו (בלבבם) לנצחונו של דוד. ועפ\"ז נמצא, שזהו ע\"ד מאמר רשב\"י הנ\"ל בנוגע לעשו, \"הלכה היא בידוע שעשו שונא ליעקב אלא שנכמרו רחמיו באותה שעה ונשקו בכל לבו\", שבזה מודגשים שני הקצוות, שאף ש\"הלכה היא בידוע שעשו שונא ליעקב\", וכנ\"ל הפירוש בזה ששנאת עשו ליעקב היא כמו הלכה שלא שייך בה ביטול, מ\"מ, אפשר לפעול עליו שלפי שעה יתהפך לאוהב (ע\"ד הנ\"ל שאנשי אבשלום הת­פללו בעודם מנגדים לדוד לנצחונו של דוד).\nוזהו גם הרמז לי\"ט כסלו, יום גאולת",[["1298","50","ב\"ר פ\"ס, יד."],["1299","51","ח\"ש כד, סא."],["1300","52","חלק תושב\"כ ר\"פ וישב."],["1301","53","תניא אגה\"ק סי' ב'."],["1302","54","באגרת שכ' לאחרי גאולתו — נדפסה בבית רבי ח\"א פי\"ח. ס' אגרות קודש אדמו\"ר הזקן סל\"ח. וש\"נ."],["1303","55","תהלים נה, יט."],["1304","56","מאמרי אדה\"ז הקצרים (ע' רטז). ובארוכה ד\"ה פדה בשלום בשעה\"ת (לאדהאמ\"צ) ח\"א פי\"א. ועוד."],["1305","57","סוטה פ\"א סה\"ח (וקרבן העדה שם)."]]],[1301670211,"אדמו\"ר הזקן, כי ענין זה, לפעול על המנגד כאשר הוא בתוקפו, עד להפכו (לפי שעה) לאוהב, קשור עם פנימיות התורה, וכמבואר בכ\"מ<sup data-n=\"1306\">58</sup> במאמר רש­ב\"י<sup data-n=\"1307\">59</sup> \"מותר להתגרות ברשעים\" (אפילו כאשר \"השעה משחקת לו\"<sup data-n=\"1308\">60</sup>), שזהו כחו ותוקפו של רשב\"י, להכניע את הרשעים גם כשהם בתוקפם. ויש לבאר השייכות לרשב\"י דוקא<sup data-n=\"1309\">61</sup>, כי רשב\"י גילה פנימיות התורה<sup data-n=\"1310\">62</sup>, סתים דאורייתא, שבה מתגלה סתים דקוב\"ה, וכחו ית' הבלתי מוגבל<sup data-n=\"1306\">58</sup> להכניע את הרשעים בעודם בתוקפם.\nומזה מובן גם הקשר לרבינו הזקן, שבגילוי תורת חסידות חב\"ד, המשיך תורת רשב\"י בהבנה והשגה, באופן ש­\"יתפרנסון\"<sup data-n=\"1312\">63</sup> מיני' כאו\"א, היינו שכאו\"א יכול להבין ולהשיג אותה עד שתתאחד עם שכלו (כמו מזון הגוף שנעשה דם ובשר כבשרו)<sup data-n=\"1313\">64</sup>.\nועל ידי הפצת מעיינות התורה חוצה, נזכה לקאתי מר דא מלכא משיחא<sup data-n=\"1314\">65</sup> ויקויים היעוד<sup data-n=\"1315\">66</sup> ד\"ועלו מושיעים בהר ציון לשפוט את הר עשו והיתה לה' המלוכה\", תיכף ומיד ממש.\n<span data-k=\"q\">(משיחות ש\"פ וישלח תשל\"ג, תשמ\"ה) </span>",[["1306","58","ראה אוה\"ת וארא ע' רלא. ד\"ה ראה נתתיך תרע\"ז (ע' קלג­ד). לקו\"ש חט\"ז ע' 74 ואילך."],["1307","59","ברכות ז, ב. מגילה ו, ב."],["1308","60","ל' הגמרא שם. וראה לקו\"ש שם הערה 55."],["1309","61","נוסף על המבואר במקומות שבהערה 58 שרשב\"י הוא ניצוץ של משה רבינו. ע\"ש. ולהעיר מסידור עם דא\"ח (דש, סע\"ב. שז, ב) ועוד, שגם זה שייך להא שרשב\"י גילה פנימיות התורה."],["1310","62","ולהעיר מד\"ה פדה בשלום (הב') תרע\"ט, השייכות דפדי' בשלום לרשב\"י (ופנימיות התורה) דוקא."],["1306","58","ראה אוה\"ת וארא ע' רלא. ד\"ה ראה נתתיך תרע\"ז (ע' קלג­ד). לקו\"ש חט\"ז ע' 74 ואילך."],["1312","63","ל' תקו\"ז ת\"ו בסופה. ובכסא מלך שם."],["1313","64","ראה תניא פ\"ה."],["1314","65","אגרת הבעש\"ט המפורסמת (נדפסה בכתר שם טוב בתחלתו. ובכ\"מ)."],["1315","66","עובדי' א, כא. רמב\"ם הל' מלכים פי\"א ה\"א בסופה. וראה שם בסוף הפרק."]]],[1301670212,"<h3>שיחה ג</h3>\nא. \"ותצא דינה בת לאה אשר ילדה ל­יעקב לראות בבנות הארץ\"<sup data-n=\"1316\">1</sup>, ובפרש\"י \"בת לאה — ולא בת יעקב, אלא על שם יציאתה נקראת בת לאה שאף היא יצאנית היתה שנאמר<sup data-n=\"1317\">2</sup> ותצא לאה לקראתו\" (ויש גורסין בסוף פירושו<sup data-n=\"1318\">3</sup> — \"ועלי' משלו ה­משל כאמה כבתה\"<sup data-n=\"1319\">4</sup>).\nולכאורה צ\"ע, למה נקט רש\"י, שפי­רושו ע\"ד הפשט, פירוש זה, שתוכנו שבא הכתוב לדבר בגנות לאה — והרי אפילו בגנות בהמה טמאה לא דיבר הכתוב<sup data-n=\"1320\">5</sup>, וכבר פרש\"י<sup data-n=\"1321\">6</sup> \"זכר צדיק לברכה\"<sup data-n=\"1322\">7</sup>.\nואין לומר שכוונת רש\"י היא למעט בגנותה של דינה (וכעין לימוד זכות עלי'), שיציאתה היתה שלא באשמתה, אלא ל­היותה \"בת לאה\" שאף היא יצאנית היתה, שאין מקום ללמד זכות על הבת על ידי פרסום גנותה של לאה.\n[ואם בכדי ליישב שינוי וכפל לשון הכתוב \"ותצא דינה בת לאה אשר ילדה ל­יעקב\", ולא בקיצור \"בת יעקב\", הרי אפשר לומר ע\"פ פרש\"י לעיל (בפ' ויצא<sup data-n=\"1323\">8</sup>) שלידת דינה היתה ע\"י תפילת לאה<sup data-n=\"1324\">9</sup>, ש­\"דנה לאה דין בעצמה אם זה זכר לא תהא רחל אחותי כאחת השפחות והתפללה עליו ונהפך לנקבה\"<sup data-n=\"1325\">10</sup>].\nוביותר יוקשה: הרי יציאת לאה לק­ראת יעקב לא הי' בה דבר בלתי רצוי, ואדרבה, מפורש ברש\"י<sup data-n=\"1326\">11</sup> \"וישמע אלקים אל לאה — שהיתה מתאוה ומחזרת להר­בות שבטים\"<sup data-n=\"1327\">12</sup> — ואין לומר שיציאה זו חסרון הוא ונחשבת \"יצאנית\".\nולכן נ\"ל, שכוונת רש\"י, שבזה שדינה נקראת כאן \"בת לאה\", משמיענו הכתוב, דכשם שפשוט (בפשש\"מ) שיציאת לאה היתה דבר טוב, כך היתה יציאת דינה כש­לעצמה דבר רצוי<sup data-n=\"1328\">13</sup> (כדלקמן) [שלכן לא הביא רש\"י דברי המדרש<sup data-n=\"1329\">14</sup> עה\"פ כאן, ששם מפורש היפך הצניעות דדינה ולאה], ואין רש\"י צריך לפרש איזה ענין טוב ישנו ביציאת דינה, כי מובן הוא מפירוש רש\"י לפנ\"ז.\nב. והביאור בזה:",[["1316","1","פרשתנו לד, א."],["1317","2","ויצא ל, טז."],["1318","3","כ\"ה בדפוסי רש\"י הנפוצים (והוא ממקומות שנסמנו בהערה 14) וליתא בדפוס ראשון, דפוס שני וכת\"י רש\"י (שתח\"י)."],["1319","4","יחזקאל טז, מד (ושם: בתה)."],["1320","5","ב\"ב קכג, א."],["1321","6","ר\"פ נח."],["1322","7","משלי י, ז."],["1323","8","ל, כא — מברכות ס, א. תנחומא ויצא ח (משא\"כ לפי' הב\"ר (ספע\"ב) הי' זה ע\"י תפלת רחל, או כל האמהות)."],["1324","9","ראה תנחומא (באבער) פרשתנו יח (וראה לקוטי תורה להאריז\"ל פרשתנו עה\"פ. ש\"ך עה\"ת עה\"פ. וכ\"ה בכמה מפרשים בפרשתנו) במ\"ש \"בת לאה אשר ילדה ליעקב\". ובש\"ך עה\"ת, דלכן ותצא דינה כי \"היא היתה זכר ודרך הזכר לצאת כו'\". וראה עץ הדעת טוב (להרח\"ו) כאן כמה פירושים."],["1325","10","ואף שרש\"י כתב ע\"ז \"פירשו רבותינו\", הרי רק זהו פירושו בפסוק זה ולא הביא פי' אחר בזה בפשש\"מ. וראה רבותינו בעה\"ת שם, ההכרח לפי­רוש זה ע\"פ פשט."],["1326","11","ל, יז."],["1327","12","ראה באר בשדה על פרש\"י פרשתנו עה\"פ."],["1328","13","להעיר גם מפני משה לירושלמי שבהערה הבאה: ואף היא (דינה) לא נתכוונה כו'."],["1329","14","ב\"ר פ\"פ, א בסופה (ובמפרשי המדרש). וראה ירושלמי סנהדרין ספ\"ב (לפי' הקרבן העדה). תנחומא כאן ז."]]],[1301670213,"רש\"י כבר פירש לעיל בפרשתנו בהאי ענינא<sup data-n=\"1330\">15</sup> \"ויקח. . ואת אחד עשר ילדיו\" — \"ודינה היכן היתה, נתנה בתיבה ונעל בפני' שלא יתן בה עשו עיניו ולכן נענש יעקב שמנעה מאחיו שמא תחזירנו למוטב ונפלה ביד שכם\".\nולכאורה תמוה: היתכן שיעקב יעמיד את דינה בסכנה שעשו יקח אותה על הספק \"שמא תחזירנו למוטב\", ועוד יותר שבגלל זה שלא הניחה שעשו יראנה נענש יעקב בעונש קשה כזה \"שנפלה ביד שכם\"?\nולכן נ\"ל, אשר: א) מעלתה של דינה היתה גדולה כ\"כ, עד שהי' בכוחה להחזיר למוטב את עשו הרשע. ב) החזרת איש<sup data-n=\"1331\">16</sup> רשע למוטב יש בה מעלה גדולה כ\"כ, שהי' כדאי להכניס את דינה לזה, אפילו על הספק \"שמא תחזירנו למוטב\".\n[ועוד זאת: מזה שיעקב נענש ע\"ז נ\"ל, שאין זה בגדר ספק, אלא ברור שתחזירו למוטב, ומ\"ש רש\"י \"שמא תחזירנו למוטב\" הוא לפי דעתו של יעקב — שאין ליעקב לקבוע בודאות שתחזירנו למוטב, כי סו\"ס הדבר תלוי בבחירתו של עשו].\nולפי פרש\"י זה יש לומר, דגם כוונת רש\"י כאן ע\"ד יציאת דינה, היא למעל­יותא<sup data-n=\"1332\">17</sup>, דכיון שהי' בכחה של דינה להח­זיר למוטב אפילו את עשו הרשע, מובן דזה ש\"ותצא דינה גו' לראות בבנות ה­ארץ\", לא היתה ח\"ו יציאה של היפך הצניעות, אלא אדרבה, \"לראות בבנות הארץ\", כדי להחזירן למוטב.\nוזהו מ\"ש רש\"י \"על שם יציאתה נקראת בת לאה שאף היא יצאנית היתה\", שתכונה טובה זו של דינה, שהי' ביכולתה לצאת לראות בבנות הארץ ולהחזירן למוטב, באה לה מאמה, שאף היא יצאנית כזו הי­תה<sup data-n=\"1333\">18</sup>.\nוזהו שמדגיש רש\"י \"בת לאה ולא בת יעקב\", כי ענין זה ירשה וקיבלה דינה מלאה, משא\"כ מצד יעקב, הרי אדרבה, הוא הסתיר אותה מעשו ומנעה מפעולות מסוג זה, ועד שנענש יעקב ע\"ז (כנ\"ל).\nג. וצ\"ע בזה, דלכאורה לא דמי יציאת דינה ליציאת לאה, דיציאת לאה היתה לפי \"שהיתה מתאווה ומחזרת להרבות שבטים\", היינו שעל ידה יולדו השבטים ליעקב, ואילו תוכן יציאת דינה הי' כדי לתקן את בנות הארץ, ומהי השייכות של היכולת להחזיר למוטב את עשו הרשע ובנות הארץ, ליציאתה של לאה שענינה הולדת השבטים?",[["1330","15","לב, כג."],["1331","16","אף שעיקר ההדגשה שם היא \"שמנעה מ­אחיו\", החזרת עשו למוטב (וראה ב\"ר ספע\"ו; פ\"פ, ד ובמפרשים שם), הרי מובן שמעין זה הוא גם לגבי שאר בני אדם, וכפי שהיתה הנהגת אברהם ושרה, בהנפש אשר עשו בחרן ש\"הכניסן תחת כנפי ה­שכינה, אברהם מגייר את האנשים ושרה מגיירת ה­נשים\" (רש\"י לך יב, ה), שגם בפשש\"מ מובן ש­הודיעו זאת לבניהם אחריהם."],["1332","17","ולא כתוכן הענין \"שלא תהא יצאנית\" שבפרש\"י לעיל (בראשית א, כח. וראה רש\"י וירא יח, ט. רש\"י תצא כב, כג. ועוד), אלא כיציאה דלאה, שהיתה לשם שמים בתכלית (וכמובן מפרש\"י ל, יז שהובא לעיל)."],["1333","18","לאחר זמן העירני ח\"א שעד\"ז פי' בבאר מים חיים (לבעהמ\"ס סידורו של שבת) עה\"ת כאן, שיציאת דינה היתה לש\"ש להכניסן תחת צל כנפי השכינה כו'.\n[אלא שמסיים \"אחר כ\"ז הנה הכתוב צווח ואמר כל כבודה בת מלך פנימה כו' ודינה שיצתה ע\"כ וירא אותה שכם\". ע\"ש. אבל ע\"פ פרש\"י פרשתנו הנ\"ל, דזה שנפלה ביד שכם הי' עונש ליעקב על זה שמנעה מעשו, י\"ל, שבגוף יציאתה לא הי' ענין בלתי רצוי (ע\"ד יציאת לאה שהיתה למעליותא בשלימות), ומה שאירע לה הי' עונש ליעקב (וראה לקמן סעיף ה). — ובבאמ\"ח שם לא הביא מפרש\"י הנ\"ל]."]]],[1301670214,"ובפרט שמפורש בפרש\"י לעיל עה\"פ<sup data-n=\"1334\">19</sup> \"ועיני לאה רכות\", \"שהיתה סבורה לעלות בגורלו של עשו ובכתה שהיו הכל אומ­רים שני בנים לרבקה ושתי בנות ללבן הגדולה לגדול והקטנה לקטן\"<sup data-n=\"1335\">20</sup>, והיינו שלא רצתה לעלות בגורלו של עשו, אף שעי\"ז יכולה להחזירו למוטב<sup data-n=\"1336\">21</sup>.\nוהביאור בזה — ע\"פ פנימיות הענינים:\nאע\"פ שכל שלשת האבות, אברהם יצ­חק ויעקב, נקראים בשם \"אבות\" (כמרז\"ל \"אין קורין אבות אלא לשלשה\"<sup data-n=\"1337\">22</sup>), לפי שהמדות דאברהם יצחק ויעקב עברו ב­ירושה לכל אדם מישראל<sup data-n=\"1338\">23</sup>, מ\"מ, יש מע­לה ביחסם של כל ישראל ליעקב אבינו לגבי היחס לאברהם ויצחק. דלהיות שרק יעקב היתה \"מטתו שלימה\"<sup data-n=\"1339\">24</sup> (דלא כאבר­הם שיצא ממנו ישמעאל ויצחק שיצא ממנו עשו<sup data-n=\"1339\">24</sup>), הרי מובן, שהוא עיקר ה\"אבות\" של עם ישראל, ה\"כלל\" של כל בנ\"י עד סוף כל הדורות (ובלשון רבינו הזקן<sup data-n=\"1341\">25</sup>, ד­נשמת יעקב היתה \"כלולה מכל הנשמות שבישראל\"), ולכן נק' \"אומה זו\" בשם \"עם ישראל\" (שמו של יעקב).\nוהנה אף שכל חילוקי המדריגות שב­ישראל שרשם מהאבות, כפי שהם ביעקב הרי הם בגדר \"כלל\", והחילוקים שבישר­אל נתגלו בפועל ע\"י בני יעקב, י\"ב שב­טים, שכנגד הי\"ב אופנים וחילוקי עבודה שישנם בישראל<sup data-n=\"1338\">23</sup>.\nויש לומר, שחילוקי הדרגות שבעבודת השבטים, גילוי מקורם מיעקב, הוא באמ­צעות האמהות, רחל לאה (בלהה וזלפה), שבנו את בית ישראל<sup data-n=\"1343\">26</sup> [וזהו בהתאם לה­הפרש בין חלק האב וחלק האם בולד הנולד, שמציאות הבן באה מטיפת האב<sup data-n=\"1344\">27</sup>, והתחלקות הולד לציורים פרטיים באה על ידי שהייתו תשעה חדשים בבטן ה­אם<sup data-n=\"1345\">28</sup>].\nולכן מצינו שקריאת שמות השבטים, שכל שם יש לו פירוש וביאור שלו המורה על תכונתו הפרטית של בעל השם, היתה על ידי האמהות רחל ולאה דוקא, ולא על ידי יעקב, כמבואר במק\"א<sup data-n=\"1346\">29</sup>.\nד. והנה אף שבפרטיות ישנם י\"ב שבטים שהם י\"ב דרכים ואופנים בעבודת ה', בכללות הרי הם נחלקים לשני אופני עבודה — צדיקים ובעלי תשובה [כידוע שעבודת התשובה אינה רק במי שחטא ופגם ועבר את הדרך, אלא היא סדר מיו­חד בעבודת ה', ושייכת גם בצדיקים<sup data-n=\"1347\">30</sup>]: עבודת הצדיקים היא בעולם הקדושה, בקיום התורה והמצוות, ואילו עבודת התשובה מורה על העבודה להפוך את הרע לטוב, ובכללות יותר, להעלות את החול לקודש.\nוזהו החילוק בין עבודת בני לאה ועבודת בני רחל, וכמובן ממ\"ש בזהר<sup data-n=\"1348\">31</sup> בטעם שעיקר יסוד המזבח הי' בחלקו של",[["1334","19","ויצא כט, יז."],["1335","20","והוא כדעת רב בב\"ב קכג, א. וראה ב\"ר פ\"ע, טז. תנחומא ויצא ד. ועוד. וראה לקמן הערה 45."],["1336","21","ראה בארוכה במפרשי רש\"י פרשתנו שם לב, כג (נחלת יעקב, משכיל לדוד, באר בשדה, וכן בבאר בשדה ויצא שם)."],["1337","22","ברכות טז, ב."],["1338","23","ראה תו\"א ר\"פ וארא."],["1339","24","ראה פסחים נו, א. ויק\"ר פל\"ו ה. ספרי ואתחנן ו, ד. האזינו לב, ט."],["1339","24","ראה פסחים נו, א. ויק\"ר פל\"ו ה. ספרי ואתחנן ו, ד. האזינו לב, ט."],["1341","25","תניא אגה\"ק ס\"ז (קיא, סע\"ב)."],["1338","23","ראה תו\"א ר\"פ וארא."],["1343","26","רות ד, יא."],["1344","27","ראה פירוש המלות לאדמו\"ר האמצעי פרק קיא (עא, ג)."],["1345","28","ראה תניא פ\"ב. וראה סה\"מ תרנ\"ט ע' ג."],["1346","29","ראה בארוכה לקו\"ש ח\"י ע' 96 ואילך. ו­ראה בהערות שם."],["1347","30","תו\"א ר\"פ ויחי (מה, סע\"א). לקו\"ת דרושים לר\"ה ס, ד. ר\"פ האזינו. ובכ\"מ."],["1348","31","ח\"א רנט, א."]]],[1301670215,"בנימין דוקא ולא בחלקו של יהודה<sup data-n=\"1349\">32</sup>, אף שיהודה הוא \"גבוה מכל השבטים\", לפי שבנימין הי' צדיק, משא\"כ יהודה, שהי' מבני לאה ש\"וישנאו\"<sup data-n=\"1350\">33</sup> והשתתפו בחטא מכירת יוסף, הרי אף שעשה תשובה, אין יסוד המזבח עומד בחלק של בע\"ת אלא בחלקו של בנימין שהי' צדיק<sup data-n=\"1351\">34</sup>. ומזה מובן, ש(עשרת<sup data-n=\"1352\">35</sup>) השבטים שהשתתפו ב­מכירת יוסף, אף שעשו תשובה, אינם ב­דרגת דיוסף ובנימין, בני רחל, שהם דוקא בדרגת צדיק דמעיקרא<sup data-n=\"1353\">36</sup>.\nואולי יש לומר, שיסוד החילוק בין עבודת השבטים, מה שבני לאה ענינם (בעיקר) עבודת התשובה<sup data-n=\"1354\">37</sup> ויוסף<sup data-n=\"1355\">38</sup> ובני­מין עבודת הצדיקים, שרשו בהאמהות, דלאה שייכת לעבודת בעלי תשובה<sup data-n=\"1356\">39</sup> ור­חל לעבודת הצדיקים<sup data-n=\"1357\">40</sup>.\nועפ\"ז יש לפרש מה שנאמר \"ועיני לאה רכות ורחל היתה יפת תואר ויפת מראה\": רחל מורה על עבודת הצדיקים, צדיק דמעיקרא, \"יפת תואר ויפת מראה\", בלי מום ופגם [ד\"תואר היא<sup data-n=\"1358\">41</sup> בציור תמונת האברים שהם כל אבר לפי הראוי לו בתמונתו הנצרכת. . ומראה הוא<sup data-n=\"1358\">41</sup> זיו קלסתר פנים כו'\", שקאי על השלימות ברמ\"ח מצות עשה, הנק' רמ\"ח אברין דמלכא, ושס\"ה ל\"ת כנגד שס\"ה גידין השייכים להארת פנים<sup data-n=\"1357\">40</sup>]; ולאה מורה על עבודת התשובה, שזהו ענין הבכי' דלאה, \"ועיני לאה רכות\", דבכי' קשורה עם עבודת התשובה.\nוהנה ביעקב נאמר<sup data-n=\"1361\">42</sup> \"ויאהב יעקב את רחל\", כי מצד יעקב עיקר העבודה היא עבודת הצדיקים, כמ\"ש \"ויעקב איש תם יושב אהלים\"<sup data-n=\"1362\">43</sup>, העבודה ב\"פנים\" בתחום הקדושה עצמה<sup data-n=\"1363\">44</sup>, ולא לצאת לחוץ לה­עלות החוץ לקדושה.\nוזהו הפירוש הפנימי במרז\"ל \"שהיו הכל אומרים שני בנים לרבקה ושתי בנות ללבן, הגדולה לגדול והקטנה לקטן\", ד­מצד עבודת לאה שהיא בחי' עבודת בעלי תשובה, הרי היא שייכת<sup data-n=\"1364\">45</sup> להחזיר עשו למוטב, משא\"כ רחל שענינה עבודת ה­צדיקים<sup data-n=\"1365\">46</sup>.",[["1349","32","בזהר שם: אוכל במזרח חצי אמה ובדרום חצי אמה. וראה משנה מדות רפ\"ג. ניצוצי זהר שם. עזרת כהנים למדות שם (בית יוסף) אות ב' ד\"ה בדרום."],["1350","33","וישב לז, ד."],["1351","34","ראה סה\"מ תרכ\"ו ע' קיא (בהוצאת תשמ\"ט. ובהוצאות שלפנ\"ז (צילום כת\"י הר\"ש סופר) ע' קל)."],["1352","35","כ\"ה בסה\"מ שם. ובזהר שם מובן דבעיקר הוא בבני לאה, ד\"וישנאו אותו\", משא\"כ בבני השפ­חות. ע\"ש."],["1353","36","ראה גם אוה\"ת שה\"ש (כרך ב) ע' תרנ."],["1354","37","להעיר שראובן, בנה הבכור של לאה, הוא שפתח בתשובה תחלה (ב\"ר פפ\"ד, יט)."],["1355","38","לפעמים מבואר דיוסף ע\"ש \"יוסף ה' לי בן אחר\" (ויצא ל, כד) ענינו לעשות מ\"אחר\" \"בן\", ענין התשובה (ראה אוה\"ת ויצא רכ, א ואילך. שם ויחי שפו, סע\"א ואילך. ועוד). וראה תו\"א וישב ד\"ה והנה אנחנו מאלמים אלומים (כח, ב) ובביאור ע\"ז בתו\"ח, אוה\"ת כו' — דיוסף הוא בחי' בירור שני, למעלה מבירורים דבי\"ע."],["1356","39","ראה תו\"א ר\"פ ויחי (ועוד), בפי' \"ראה ה' בעניי\" (ויצא כט, לב), \"שמע ה' כי שנואה אנכי\" (שם, לג), שהוא בחי' המרירות והריחוק, השייכת לעבודת התשובה. ע\"ש."],["1357","40","סה\"מ תרכ\"ח ע' קה ואילך."],["1358","41","ראה גם פרש\"י ויצא שם (כט, יז)."],["1358","41","ראה גם פרש\"י ויצא שם (כט, יז)."],["1357","40","סה\"מ תרכ\"ח ע' קה ואילך."],["1361","42","ויצא כט, יח."],["1362","43","תולדות כה, כז."],["1363","44","ראה בארוכה לקו\"ש ח\"כ ע' 110 ואילך."],["1364","45","להעיר שרש\"י בפי' עה\"ת לא כתב כלשון הגמ' בדברי רב \"לא גנאי הוא לה אלא שבח הוא לה\". וראה ב\"ר שם (פ\"ע, טז. פע\"א, ב): קשה היא התפלה שבטלה את הגזירה ולא עוד אלא שקדמה לאחותה."],["1365","46","להעיר מפרש\"י ויצא (ל, כב) \"זכר לה כו' ושהיתה מצירה שלא תעלה בגורלו של עשו שמא יגרשנה יעקב לפי שאין לה בנים ואף עשו הרשע כך עלה בלבו כששמע שאין לה בנים\", ובפרש\"י שם, כג \"והיו אומרים עלי שאעלה לחלקו של עשו הרשע\". אבל מובן דשאני \"שהיו הכל אומרים\" הנאמר בלאה, שנקבעו ב' הבנות לב' הבנים (ראה ב\"ר שבהערה שלפנ\"ז. וראה עץ הדעת טוב עה\"פ כאן), מזה ש\"היתה (רחל) מצירה כו' ואף עשו הרשע כך עלה בלבו כו' שאין לה בנים\"."]]],[1301670216,"וזהו מ\"ש רש\"י \"על שם יציאתה נקראת בת לאה, שאף היא יצאנית היתה שנאמר ותצא לאה לקראתו\", והיינו לפי שתכונה זו של דינה לפעול בחוץ, באה לה בירושה מלאה, להיותה \"בת לאה\", שתוכן עבודתה היא בחוץ, להפוך את הרע שבחוץ לטוב.\nאלא שכפי שענין זה הוא במקורו, אינו בגלוי כ\"כ, ולכן לא רצתה לאה ליפול ביד עשו, משא\"כ כשבא בפירוט ובהת­חלקות אצל השבטים, אזי מתגלה תוכן עבודה זו דיציאה, העבודה דעשיית בע\"ת.\nה. ויש להוסיף, דאע\"פ שבפועל הי' מכשול אצל דינה, הרי הטעם לזה הוא כפרש\"י (כנ\"ל) לפי שזה הי' עונש ליעקב על שמנעה מאחיו, שמזה גופא מובן שאין יציאתה מעשה בלתי רצוי, כי הי' בכוונה לשם שמים להחזירן למוטב.\nואולי יש לומר, שדבר זה — שהיציאה היתה כדי להחזירן למוטב והוא דבר טוב — בא לידי ביטוי בכך, שנתקיים מעין מטרת יציאת דינה להחזירן למוטב, שהרי בני יעקב פעלו על אנשי שכם שימולו כל זכר<sup data-n=\"1366\">47</sup>, שזהו ענין של גיור<sup data-n=\"1367\">48</sup> שהי' נהוג בימים ההם כדי להיכנס למשפחת אבר­הם, ומובן בפשטות, שכניסה זו היתה לא רק בנוגע לאנשים אלא גם בנוגע ל\"בנות הארץ\", הנשים והבנות, כמפורש בקרא<sup data-n=\"1368\">49</sup> \"בזאת נאות לכם גו' להמול גו' ואת בנותיכם נקח לנו גו'\".\nכלומר: אף שבפועל נתחייבו אנשי שכם מיתה מפני חטאם<sup data-n=\"1369\">50</sup>, ולכן נהרגו ע\"י שמעון ולוי, אחי דינה, מ\"מ, כדי שרצונה של אותה צדקת, \"דינה בת לאה\", יתקיים במקצת עכ\"פ, הרי קודם הריגתם נמולו<sup data-n=\"1370\">51</sup>, שזהו הסימן של כריתת ברית עם משפחת אברהם.\nזאת ועוד: בנות שכם — שאליהן יצאה דינה להחזירן למוטב — נלקחו בשבי על ידי בני יעקב<sup data-n=\"1371\">52</sup>, ובפשטות נעשו שפחות בביתם של בני יעקב.\nו. ומכאן — הוראה לנשי ישראל:\nאע\"פ ש\"כל כבודה בת מלך פנימה\"<sup data-n=\"1372\">53</sup>, ונשים נקראות \"עקרת הבית\"<sup data-n=\"1373\">54</sup>, לפי ש­עיקר תפקידם הוא לבנות בית בישראל, שבשביל זה הן צריכות להשאר ב\"פנים\", \"פנימה\" דוקא — הרי אותן הנשים שחוננו בתכונות מיוחדות שביכולתן להשפיע גם בחוץ, עליהן לנצל תכונה זו באופן דצני­עות לשם שמים, לקרב את הלבבות לעבו­דת ה' ולהחזיר בנות ישראל הנמצאות ב\"חוץ\" למוטב.\nואף שמובן ופשוט, שהשתדלות זו צריכה להיות כיאות לבת ישראל באופן",[["1366","47","פרשתנו לד, כד."],["1367","48","ראה רדב\"ז להל' מלכים ספ\"ט. כלי יקר לד, כה. תורה שלימה שם, כו (אות נט). וראה ב\"ר שם (פע\"ו, ט. פ\"פ, ד ובמפרשים) הדיעה שדינה נשאה לאיוב וגיירה אותו."],["1368","49","לד, טו­טז."],["1369","50","ראה לקו\"ש ח\"ה ע' 190 הטעם שנתחייבו מיתה ע\"ד הפשט. וראה בהנסמן שם דיעות ה­ראשונים הטעם שנתחייבו מיתה."],["1370","51","להעיר מל\"ת להאריז\"ל פרשתנו: בחטא אדה\"ר נתערבו הניצוצין. . הקליפות, לכן שכם שהי' בו ניצוץ אדה\"ר חשק כ\"כ בדינה לכן נהרג אחר תקונו אחר שעשה ברית מילה. וראה נחל קדומים פרשתנו עה\"פ."],["1371","52","פרשתנו לד, כט."],["1372","53","תהלים מה, יד."],["1373","54","ולהעיר שזה נאמר על רחל (רש\"י ויצא לא, ד. ויגש מו, יט. וראה ב\"ר פע\"א, ב. במדב\"ר פי\"ד, ח)."]]],[1301670217,"צנוע, ועד שבה\"יציאה\" בחוץ צ\"ל ניכר עלי' ד\"כל כבודה בת מלך פנימה\", מ\"מ, ביחד עם הזהירות בתכלית של הליכה בגדרי הצניעות, עליהן להחזיר למוטב את בנות ישראל התועות.\nואדרבה, טבע הקירוב והרכות של נשים מסייע אותן להצליח בקירוב הלב­בות לעבודת ה' עוד יותר מאנשים, כפי שרואים במוחש, דכאשר משדלים את השני להתקרב לתורת ה' ועבודתו בדרכי נועם ודרכי שלום, יש הרבה יותר הצלחה (והפעולה היא פנימית יותר ויש לה קיום יותר) מאשר על ידי הפעולה על ידי ויכוחים ומלחמה כו' (כטבע האנשים, ש­\"איש<sup data-n=\"1374\">55</sup> דרכו לכבוש\").\nוכיון שהקב\"ה ברא את הנשים בתכונה זו, הרי מובן שעליהן לנצל אותה במי­לואה, לא רק בהנהגת הבית, אלא גם ב­השפעה בחוץ, לקרב את בנות ישראל לאביהן שבשמים<sup data-n=\"1375\">56</sup>.\n<span data-k=\"q\">(משיחות ש\"פ וישלח וש\"פ וישב תשמ\"ו)</span>",[["1374","55","פרש\"י בראשית א, כח."],["1375","56","ראה בארוכה בכ\"ז ס' השיחות תנש\"א ח\"א ע' 83 ואילך."]]],[1301670218,"<h3>שיחה א</h3>\nא. \"ויספר<sup data-n=\"1376\">1</sup> אל אביו ואל אחיו ויגער בו אביו ויאמר לו מה החלום הזה אשר חלמת הבוא נבוא אני ואמך ואחיך ל­השתחוות לך ארצה\", ובפרש\"י מעתיק מן הכתוב \"הבוא נבוא\" ומפרש \"והלא אמך כבר מתה והוא לא הי' יודע שה­דברים מגיעין לבלהה שגדלתו כאמו ורבותינו למדו מכאן שאין חלום בלא דברים בטלים ויעקב נתכוין להוציא הדבר מלב בניו שלא יקנאוהו לכך אמר לו הבוא נבוא וגו' כשם שא\"א באמך כך השאר הוא בטל\".\nולפי דברי כמה מפרשי רש\"י<sup data-n=\"1377\">2</sup> נמצא, שרש\"י כותב כאן שני פירושים: א) ש­יעקב \"לא הי' יודע שהדברים מגיעין לבלהה\" (שהוא ע\"פ בראשית רבה על אתר<sup data-n=\"1378\">3</sup>), ב) פי' רבותינו ד\"אין חלום בלא דברים בטלים\" (והוא ע\"פ דברי הגמ­רא<sup data-n=\"1379\">4</sup>).\nולכאורה משמע, שלפי' הא' חשב יעקב שאין ממש בחלום והוא חלום שווא<sup data-n=\"1380\">*4</sup>, כיון שגם \"אמך\" היתה משתחווה (וטעה בזה, כי \"לא הי' יודע שהדברים מגיעין לבלהה\"); ואילו לפי' רבותינו ידע יעקב שהחלום הוא חלום אמיתי, והפרט ד\"אמך\" משתחווה אינו סותר לאמיתיות החלום (אף שלשיטת רבותינו א\"א לומר שהדברים מגיעים לבלהה), כי \"אין חלום בלא דברים בטלים\", ופרט זה הוא מה\"דברים בטלים\" שבו. ומה שמס­יים רש\"י \"ויעקב נתכוין להוציא הדבר מלב בניו שלא יקנאוהו לכך אמר לו הבוא נבוא וגו' כשם שא\"א באמך כך השאר הוא בטל\", זהו סיום הפירוש הב', דאף שהוא ידע שהחלום אמת, מ\"מ אמר כן \"להוציא מלב בניו\".\nאבל לכאורה פירוש זה (בדברי רש\"י) דחוק הוא, שהרי בכתוב ממשיך<sup data-n=\"1381\">5</sup> \"ואביו שמר את הדבר\", ופרש\"י \"הי' ממתין ומצפה מתי יבוא\", הרי מפורש שברור הי' ליעקב שהוא חלום אמיתי ובודאי יתקיים<sup data-n=\"1382\">6</sup>, אלא שהי' ממתין ומצפה מתי יתקיים<sup data-n=\"1383\">7</sup>.",[["1376","1","פרשתנו לז, יו\"ד."],["1377","2","ראה רא\"ם, גו\"א ובכמה מפרשים."],["1378","3","פפ\"ד, יא."],["1379","4","ברכות נה, סע\"א ואילך."],["1380","*4","כמפורש בלבוש. וראה הערה 7."],["1381","5","לז, יא."],["1382","6","ומטעם זה יש מפרשים בפרש\"י ש\"הוא לא הי' יודע\" קאי על יוסף — ראה מדרשי התורה (להקדוש אשתרוק). באר מים חיים (לאחי המהר\"ל)."],["1383","7","ואולי י\"ל בפירוש הרא\"ם והגו\"א, שגם לפי' הא' ידע יעקב שהוא חלום אמת<sup data-n=\"e34\">*</sup>, אף שלא הי' יודע פתרון החלום (שהרי לא הי' יודע שהדברים מגיעין לבלהה), וזה ש\"אביו שמר את הדבר\" היינו ש\"הי' ממתין ומצפה\" שיתקיים<sup data-n=\"e35\">**</sup> אף שלא ידע איך יתקיים. ע\"ד מ\"ש בחי' ופי' מהרי\"ק (על פרש\"י) ונחלת יעקב בפרש\"י."],["e34","*","ראה גו\"א ונחלת יעקב בפרש\"י בד\"ה לפי שהי' מטיל שנאה, לא שלא הי' מחזיק החלום אמת שהרי כתיב ואביו שמר את הדבר."],["e35","**","אבל בלבוש כאן, שלפי' הא' הא ד\"אביו שמר את הדבר\" הוא לא לקיים החלום (כבפי' הב'), אלא לקיים חשקו ורצונו של יוסף, ומפרש דפרש\"י \"ממתין ומצפה מתי יבוא\" (\"כי ודאי לו שיבוא\"), \"זה פי' לדברי רז\"ל. אבל לפי פי' הראשון פירושו הי' ממתין ומצפה ומתפלל שיבוא למלאות משאלות לב יוסף. אלא שרש\"י פירשו לפי משמעות פשוטו כדרכו בכל מקום\". וצ\"ע, דלפ\"ז סותם רש\"י בפי' \"ואביו שמר את הדבר\" כפי' רבותינו (בפסוק שלפנ\"ז), ולא כפי פי' הראשון (שם) שהוא לפי פשוטו של מקרא."]]],[1301670219,"ואולי י\"ל, שאין כאן שני פירושים ברש\"י, אלא כל דבריו הם המשך אחד. וכדיוק לשונו \"ורבותינו למדו מכאן\" [ולא כתב, כדרכו בכ\"מ כשמביא שני פירושים, \"דבר אחר\" או \"ורבותינו דר­שו\" וכיו\"ב], שאין במשמעות לשון זו שזהו פירוש חדש, אלא רק הוספת ענין<sup data-n=\"1384\">8</sup>. ושיעור לשון רש\"י כך הוא: כיון שיעקב לא ידע שהדברים מגיעים לבלהה, ו­אעפ\"כ הי' ברור לו שהחלום יתקיים (כ­המשך הכתוב \"ואביו שמר את הדבר\"), הנה מזה למדו רבותינו שאין חלום בלא דברים בטלים. וזו היתה דעתו של יעקב, שאף שכללות החלום יתקיים, מ\"מ פרט זה שבחלום (שאמו תבוא להשתחוות לפניו) הוא מהדברים בטלים שבו<sup data-n=\"1385\">9</sup>. אבל לפי האמת לא הי' זה מהדברים בטלים כי אכן היו הדברים מגיעים לבלהה<sup data-n=\"1386\">10</sup>. וע\"ז מסיים רש\"י, דאף שיעקב ידע ש­כללות החלום יתקיים, מ\"מ אמר \"הבוא נבוא גו'\", כדי \"להוציא הדבר מלב ב­ניו\", שהם לא ידעו \"שאין חלום בלא דברים בטלים\", ובמילא אפשר לומר להם, ש\"כשם שא\"א באמך כך השאר הוא בטל\"<sup data-n=\"1387\">11</sup>.\nב. אלא שלפ\"ז צריך ביאור: כיון שלפי האמת \"הדברים מגיעין לבלהה\", א\"כ מה הם הדברים בטלים שבחלום<sup data-n=\"1388\">12</sup>?",[["1384","8","וצ\"ע בפרש\"י לך יג, יג. צו ו, ה. קדושים יט, ה (ד\"ה לרצונכם). שם, כ (ד\"ה בקורת תהי')."],["1385","9","ראה גם חדא\"ג מהרש\"א ברכות שם."],["1386","10","ברמב\"ן כאן \"ולפי דעתי כי בעת שירד יעקב למצרים כבר מתה בלהה גם זלפה כו'\". אבל דברי רש\"י מפורשים בב\"ר על אתר, כנ\"ל בפנים (והערה 3). וראה תרגום יונתן וירושלמי ויחי (נ, טז) בפי' ויצוו אל יוסף \"ופקידו ית בלהה\"<sup data-n=\"e36\">*</sup>. הרי שהיתה קיימת גם לאחר פטירת יעקב. וכ\"ה ביל\"ש ומדרש לקח טוב שם. ובכמה מדרשים (תנחומא צו ז. תנחומא (באבער) שמות ב. ועוד).\nוראה בראשית רבתי (לר\"מ הדרשן) ויחי נ, יח בכתוב \"וילכו גם אחיו\" — \"מהו גם, מלמד שהלכה בלהה תחלה ונפלה לפניו ואח\"כ באו אחיו ונפלו לפניו אותה שעה נתקיים בו השמש והירח כו'\". ע\"ש. וכבר שקו\"ט במפרשי רש\"י בקושיית הרמב\"ן — ראה מהר\"י אבוהב. אמרי שפר. ועוד. ואכ\"מ."],["1387","11","בכמה מפרשים פירשו דדברי רש\"י \"ויעקב נתכוין להוציא הדברים מלב בניו\" קאי גם על פי' הא' — ראה חי' ופי' מהרי\"ק, משכיל לדוד ועוד. אבל לפי פירושם יש כאן ב' פירושים ברש\"י אלא שסיום לשון רש\"י קאי על שניהם (ובמשכיל לדוד מפרש ע\"פ הב\"ר (הנ\"ל הערה 3) שיעקב סבור שתחה\"מ מגעת בימיו כו'). וראה נחלת יעקב, דברי דוד (להט\"ז) כאן. נזר הקודש לב\"ר כאן. ועוד."],["1388","12","ומה שרש\"י לא פירש שלפי האמת לא היו הדברים מגיעים לבלהה והם הדברים בטלים שבה­חלום — יש לומר, כי בפשטות מסתבר לומר ש­\"אמך\" קאי על בלהה כיון \"שגדלתו כאמו\", כפי שמצינו בפירוש לעיל (ויצא ל, ג­ו ובפרש\"י) \"ותלד על ברכי. . ואנא ארבי. . ויתן לי בן\" — אלא שכיון שדוחק גדול לומר שיעקב ידע מזה ואעפ\"כ אמר \"והלא אמך כבר מתה\", שזהו כעין שקר (וראה גם במפרשי רש\"י כאן), הוצרך רש\"י לחדש שיעקב לא הי' יודע שהדברים מגיעים לבלהה (וראה יפה תואר השלם שם ד\"ה סבור).\nויש לומר, שסברתו של יעקב דלא קאי על בלהה (אף שמפורש כעין זה בדברי רחל כנ\"ל), כי אע\"פ שמתאים לקרוא להאשה המגדלת \"אם\" בשם המושאל (ואפילו בהרגש הבן המתגדל ה\"ה ע\"ד \"אמו\"), מ\"מ לא מתאים להשוותה להאב בחדא מחתא, ע\"ד נדו\"ד שראה \"השמש והירח\". וראה חדא\"ג מהרש\"א שם. לבוש האורה כאן. ועוד.\nועפ\"ז יומתק דיוק הלשון \"הדברים מגיעין לבלהה\", כי עצם הענין ד\"(שמש ו)ירח\" שבחלום לא קאי באופן ישר על בלהה (כמו ש\"שמש\" קאי על יעקב), אלא כיון ש\"אמו כבר מתה\" ה\"ז יכול \"להגיע\" גם לבלהה כיון ש\"גדלתו כאמו\" (ולכן חשב יעקב שזהו מהדברים בטלים שבחלום)."],["e36","*","בפרש\"י \"את מי צוו את בני בלהה\". אבל אין מזה הוכחה שס\"ל שבלהה כבר מתה, כי ברש\"י מפורש הטעם \"שהיו רגילין אצלו\". זאת ועוד, ע\"פ פשש\"מ, אין מסתבר שהבנים (השבטים) יצוו — ישלחו את בלהה ליוסף."]]],[1301670220,"ויובן זה בהקדים תמי' בכללות ה­מסופר בכתוב כאן ש\"ואביו שמר את ה­דבר\", ש\"הי' ממתין ומצפה מתי יבוא\", שמורה על דבר החביב עליו, שרוצה שיבוא ויתקיים כבר, מהו העילוי בזה שבנו ימלוך ואביו ישתחווה לו ארצה? דאע\"פ שהכלל<sup data-n=\"1389\">13</sup> ד\"בכל אדם מתקנא חוץ מבנו ותלמידו\" הוא דבר מובן ופ­שוט<sup data-n=\"1390\">14</sup>, הרי זה רק שאין אדם מתקנא בבנו ותלמידו כאשר מתעלים למדריגה נעלית יותר ממנו, אבל אין מקום שהאב יצפה שבנו ימלוך עליו<sup data-n=\"1391\">15</sup>, ובאופן שכל אחיו המבוגרים וגם האב<sup data-n=\"1392\">16</sup> יהיו עבדים לו וישתחוו לו ארצה.\nיש מפרשים<sup data-n=\"1393\">17</sup> כוונת רש\"י ע\"פ מ\"ש במדרש כאן<sup data-n=\"1378\">3</sup> \"כך הי' אבינו יעקב סבור שתחיית המתים מגעת בימיו\", והיינו דזה שהי' ממתין ומצפה מתי תגיע העת שית­קיים חלומו, הוא (לא ע\"ז שיוסף ימלוך וכולם ישתחוו לו שזה באמת הי' צער גדול ליעקב, אלא) משום שהי' סבור שתחיית המתים מגעת בימיו<sup data-n=\"1395\">18</sup>, ולכן הי' מצפה מתי יבוא העת שתעמוד רחל אמו.\nאבל נוסף על עצם הדוחק לפרש כן בפרש\"י, שאין שום רמז לענין הנ\"ל (שבמדרש) שיעקב הי' סבור שתחיית המתים מגעת בימיו, ועוד זאת שפשטות הכוונה ב\"שמר את הדבר\" קאי על כללות תוכן החלום ולא על ענין צדדי שיתקיים כשיבוא זמן קיום החלום [וב­פרט באופן שעצם הדבר אין בו דבר מיוחד, ורק פרט צדדי הוא דבר שמצפה אליו<sup data-n=\"1396\">19</sup>] — הרי ע\"פ הנ\"ל (ס\"א) כוונת רש\"י היא להיפך ממש, שיעקב חשב שפרט זה דהחלום (שאמו תשתחווה לו) הוא מהדברים בטלים שבחלום.\nועפ\"ז — מהו גודל הענין בחלום זה שיעקב הי' ממתין ומצפה מתי יבוא?\nג. ויש לומר, שזה מתורץ ע\"פ דיוק לשון רבותינו שלמדו מכאן \"שאין חלום בלא דברים בטלים\", דלכאורה ע\"פ הנ\"ל הי' כאן רק דבר אחד בחלום ש­אינו אמיתי (זה שאמו תשתחווה לו), והל\"ל \"אין חלום בלא דבר בטל\"?\nונ\"ל, שבדיוק אמרו \"אין חלום בלא דברים בטלים\" בלשון רבים, שיעקב חשב שיש כמה \"דברים בטלים\" ב­חלום<sup data-n=\"1397\">20</sup>, דכשם שהפרט שאמו תשתחווה לו הוא דבר בטל (שהרי לא ידע שה­דברים מגיעים לבלהה), כך חשב שגם זה שהוא יבוא להשתחוות לו ארצה הוא מהדברים בטלים שבחלום, דאמיתיות החלום היא רק בזה שיוסף יעלה ל­גדולה עד שימלוך על כל אחיו, אבל לא שימלוך גם על אביו עד שיעקב ישתחווה לו ארצה.",[["1389","13","סנהדרין קה, ב."],["1390","14","ראה ספורנו עה\"פ (יא)."],["1391","15","ראה ב\"ר שם, יב: אמר אם נתבקרה פינקסו מה יכול אני לעשות."],["1392","16","וראה מדרשי התורה שבהערה 6: ויש לתמוה איך שם יוסף בלבו לספר בגנות אביו בפניו."],["1393","17","מלאכת הקודש על פרש\"י כאן."],["1378","3","פפ\"ד, יא."],["1395","18","ראה גם יריעות שלמה (להמהרש\"ל) ובה­נסמן בהערה 11."],["1396","19","ראה מלאכת הקודש שם: ולכן הי' מצפה מתי יבוא העת שתעמוד רחל עקרת הבית וממילא יעמוד זקנו אברהם ושם ועבר רבותיו וילמוד מהם התורה אע\"פ שהחלום מצד עצמו הוא רע שיתבקר פנקסו שישתחוה לבנו הוא ובניו עכ\"ז טובה ה­נמשכת ממנו היא יותר מרעתו."],["1397","20","להעיר שבברכות שם הראי' מיוסף לא הובאה בדברי ר\"י משום ר' שמעון \"אי אפשר לח­לום בלא דברים בטלים\", אלא במאמר בפ\"ע \"א\"ר ברכי' חלום אע\"פ שמקצתו מתקיים כולו אינו מתקיים מנא לן מיוסף\", לשון המורה מלכתחילה שרק מקצתו מתקיים. וראה דק\"ס שם, עוד גי' בברכות שם. וש\"נ."]]],[1301670221,"וי\"ל שכן הי' בפועל, שפרט זה ש­יעקב ישתחווה ליוסף הי' מהדברים בטלים שבחלום, כי יעקב לא השתחווה ליוסף \"ארצה\", אלא רק \"וישתחו<sup data-n=\"1398\">21</sup> ישר­אל על ראש המטה\"<sup data-n=\"1399\">22</sup>.\nועפ\"ז יש לבאר גם דיוק לשון רש\"י \"כשם שאי אפשר באמך כך השאר הוא בטל\", ולא נקט הלשון \"כולו<sup data-n=\"1400\">23</sup> בטל\", כי נקט לשון כזו, שבה נרמזת גם סברתו של יעקב לפי האמת, שיעקב סבר, דאף שעיקרו של החלום צריך להתקיים, מ\"מ ישנם כמה פרטים שאינם מוכרחים להת­קיים, ויתירה מזה, שע\"פ סדר מוכרחים להיות פרטים שלא יתקיימו כי \"אין ח­לום בלא דברים בטלים\", ולכן אמר<sup data-n=\"1401\">24</sup> יעקב לשון כזו שלא יהי' בלשונו דבר שקר (דפשוט, דאף שיעקב רצה \"להוציא מלב בניו\", מ\"מ לא יתכן שמשום כך יוציא יעקב שקר מפיו), וזהו שאמר \"כך השאר הוא בטל\", שלא רק פרט זה ד\"אמך\" הוא דבר בטל אלא יש בו עוד פרטים \"בטלים\", אלא שהשבטים הבינו מדבריו שכולו בטל.\nד. אבל עדיין צריך להבין (בפני­מיות הענינים) גם בנוגע לעיקר החלום, שיוסף ימלוך על שאר האחים והם יבואו להשתחוות לו ארצה, דלכאורה, אע\"פ שכיון שיוסף הי' בן זקוניו של יעקב אשר אהב אותו מכל בניו לכן הי' רוצה שיעלה לגדולה, ועוד יותר משאר כל בניו, מ\"מ, מהו העילוי בזה שהוא ימלוך על אחיו עד שישתחוו לו ארצה, ועד כדי כך שיעקב הי' ממתין ומצפה מתי יבוא הדבר?\nויש לבאר זה ע\"פ מ\"ש רש\"י לקמן עה\"פ<sup data-n=\"1402\">25</sup> \"וישלחהו מעמק חברון\" — \"מ­עצה עמוקה של אותו צדיק הקבור ב­חברון לקיים מה שנאמר<sup data-n=\"1403\">26</sup> לאברהם בין הבתרים כי גר יהי' זרעך\", היינו שה­שליחות ששלח יעקב את יוסף היתה \"ל­קיים מה שנאמר לאברהם בין הבתרים\", דלפי זה יש לומר, שגם כללות הסיפור דפרשתנו ע\"ד יוסף ואחיו היתה בו \"עצה עמוקה\" שתתקיים ברית בין הבתרים.\nועפ\"ז יש לומר, שעד\"ז הוא בנוגע לפרש\"י דידן, דזה שיעקב הי' ממתין ומצפה מתי יבוא, הרי בפנימיות אין הכוונה למלכותו של יוסף כשלעצמה (שבכך שאחיו ישתחוו לו אין מעלה), אלא בכך שגזירת בין הבתרים תתקיים",[["1398","21","ויחי מז, לא."],["1399","22","בפרש\"י שם ד\"ה וישתחו ישראל — \"תעלה בעידנא סגיד לי'\". אבל ראה במפרשי רש\"י, שלא היתה השתחוואה זו בגדר הכנעה (כהשתחוואה ע\"ד הרגיל), שזה הי' גנאי ליוסף שאביו הי' משתחווה לו, וכדמוכח גם מזה שלא השתחווה תיכף כשבא אליו אלא רק אחר השבועה — ראה גו\"א ונחלת יעקב שם. וראה פרש\"י שם ד\"ה על ראש המטה \"הפך עצמו לצד השכינה\". ובפרט ע\"פ הד\"א בפרש\"י שם \"על ראש המטה, על שהיתה מטתו שלימה\", וראה רע\"ב וחי' ופי' מהרי\"ק שם. לקמן ע' 211 ואילך. וראה ע\"ד החסידות תו\"א פרשתנו (כח, ג) תו\"ח שם (סט, ד ואילך) דהשתחואה דיעקב היא מלמעלה למטה מן הגבוה לנמוך. עיי\"ש בארוכה."],["1400","23","להעיר שבהעתקת לשון רש\"י ברמב\"ן כאן \"הכל בטל\" (וראה ל' הגמ' ברכות שם (הנ\"ל הערה 20)). אבל בדפוס ראשון ושני \"השאר\", כבדפוסים שלפנינו."],["1401","24","לכאורה אפשר לפרש שהלשון \"כשם שא\"א באמך כך השאר הוא בטל\" אינו מדברי יעקב אלא הם דברי רש\"י שמפרש כוונת דברי יעקב במה שאמר \"הבא נבוא כו'\", שהיתה \"להוציא הדבר מלב בניו\". אבל יש לפרש ג\"כ שיעקב אמר כן (כדמשמע קצת מלשונו \"כשם שא\"א באמך\"), ומ\"ש \"נתכוון להוציא הדבר מלב בניו\" אין פירושו שזו היתה רק כוונה ומחשבה, אלא עשה כן בפועל באמרו \"כשם שא\"א באמך כו'\". ועצ\"ע."],["1402","25","לז, יד."],["1403","26","לך טו, יג."]]],[1301670222,"ע\"י מלכותו של יוסף, שהרי גזירת \"גר יהי' זרעך בארץ לא להם\" היתה יכולה להתקיים בכמה אופנים (וכמחז\"ל<sup data-n=\"1404\">27</sup> ראוי הי' יעקב אבינו לירד למצרים בשלשל­אות של ברזל), אלא יעקב הי' ממתין ומצפה מתי יתקיים חלום יוסף, שיוסף ימלוך, שעי\"ז תהי' ירידת יעקב למצרים בדרך כבוד, וכן שהותם של ישראל בארץ מצרים במשך ריבוי שנים תהי' באופן של מנוחה וכבוד ושלוה, להיות שיוסף הי' משנה למלך שבלעדו לא ירים איש את ידו ואת רגלו<sup data-n=\"1405\">28</sup>, וכפי שהי' בפועל שבני ישראל ישבו בארץ גושן שהיא מיטב הארץ<sup data-n=\"1406\">29</sup>.\nאך גם פירוש זה אינו מחוור, כי פשטות החלום היתה לא על כללות מלכותו של יוסף (כלפי אומות העולם), אלא רק שהשמש והירח ואחד עשר כוכבים משתחווים לי, היינו רק ההש­תחוואה דיעקב ואחיו. גם פשטות הלשון \"הי' ממתין ומצפה מתי יבוא\" אינו מת­אים כ\"כ לפי הנ\"ל, דלשון זו מורה שהי' מצפה שהדבר יבוא בקרוב ובמהרה, ואילו לפירוש הנ\"ל ודאי לא הי' מצפה שהדבר יבוא במהרה (דמדוע יצפה יעקב להתחלה של גלות, ואפילו אם יהי' באופן של כבוד). ומתאים רק לומר שהי' יודע שיתקיים כו', אבל לא ש\"הי' ממתין ומצפה מתי יבוא\".\nה. והביאור בזה:\nידוע הביאור הפנימי בזה שכל יש­ראל נקראים בשם יוסף, \"נוהג כצאן יוסף\"<sup data-n=\"1407\">30</sup>, שהוא לא רק \"לפי שהוא פרנסם וכלכלם בימי הרעב\"<sup data-n=\"1408\">31</sup> כפשוטו, אלא לפי שהמשיך והשפיע מעניניו ותכונותיו הרוחניים לכאו\"א מישראל<sup data-n=\"1409\">32</sup>:\nייחודו של יוסף לגבי שאר השבטים הי' בזה ששאר השבטים היו רועי צאן, מופרשים ומובדלים מעניני העולם בכדי שלא יבלבלום מעבודת השם, משא\"כ יוסף הצדיק הי' בגלות \"נשבה לבין הגוים\"<sup data-n=\"1410\">33</sup>, ויתירה מזו, שהי' שולט בכל ארץ מצרים, ולא הי' זה רק כלפי חוץ ובחיצוניות, אלא שהי' עסוק בכל זה, תחלה בבית פוטיפר, \"ויפקדהו על ביתו וכל יש לו נתן בידו\"<sup data-n=\"1411\">34</sup>, ולאח\"ז \"ועל פיך ישק כל עמי\"<sup data-n=\"1412\">35</sup>, שניהל בפועל כל עניני מצרים כו', שזוהי \"טרדה גדולה ועצומה ביותר\"<sup data-n=\"1413\">36</sup> — ואעפ\"כ, הרי כל טרדות אלו לא נתקו אותו ואפילו לא בלבלו אותו מעבודת השם, וגם בעת עסקו בהם נש­אר בתכלית הדביקות באלקות, עד שהי' \"מרכבה ממש לאלקות\"<sup data-n=\"1414\">37</sup>.\nויתירה מזו, לא רק שהטרדה בעניני העולם לא גרמה אצלו חלישות בדבי­קותו באלקות, אלא שהוא פעל בהם ובעניני מצרים, כמרז\"ל<sup data-n=\"1415\">38</sup> עה\"פ<sup data-n=\"1416\">39</sup> ויוסף הורד מצרימה, \"שלט בהון. . כבש ב­הון\", שפעל על עניני הגלות שיהיו בהתאם לעבודתו דיוסף את השם<sup data-n=\"1417\">40</sup>.\nוזהו מה שכל ישראל נקראים על שם",[["1404","27","שבת פט, ב."],["1405","28","מקץ מא, מד."],["1406","29","ויגש מז, ו."],["1407","30","תהלים פ, ב. ובפרש\"י שם."],["1408","31","ל' רש\"י שם (וראה ויגש מז, יב)."],["1409","32","ראה בכל הבא לקמן לקו\"ש חכ\"ה ע' 253 ואילך. וש\"נ."],["1410","33","רש\"י ויחי מז, לא."],["1411","34","פרשתנו לט, ד. ובת\"א (ועד\"ז בתיב\"ע) שם, יא: למבדק בכתבי חשבני'."],["1412","35","מקץ מא, מ."],["1413","36","ל' התו\"ח ויחי קב, ג. ועוד."],["1414","37","סה\"מ תפר\"ח ריש ע' כז."],["1415","38","ב\"ר פפ\"ו, ב."],["1416","39","פרשתנו לט, א."],["1417","40","ראה בארוכה לקו\"ש שם ע' 194 ואילך. וש\"נ."]]],[1301670223,"יוסף, כי הכח שיש לכל ישראל לעבור את הגלות נמשך ובא מיוסף הצדיק<sup data-n=\"1418\">41</sup>.\nוזהו מה שיעקב \"הי' ממתין ומצפה מתי יבוא\" קיום חלומו של יוסף, שאחי יוסף ישתחוו לו ארצה, דענין ההשת­חוואה מורה על הביטול כלפי המלך שאליו משתחווה, שע\"י ביטול זה להמלך נמשכים<sup data-n=\"1419\">42</sup> אל העם השפעות המלך, הן השפעות גשמיות והן השפעות רוחניות.\nולכן הי' יעקב ממתין ומצפה לקיום חלומו של יוסף שדוקא באופן כזה בכחם של ישראל לעבור את ההעלם והסתר דגלות מצרים<sup data-n=\"1420\">43</sup> (וגלות בכלל, דכל המלכיות נקראו על שם מצרים<sup data-n=\"1421\">44</sup>), כאשר הם תחת מלכותו של יוסף, היינו הנהגה זו שגם בהיותם בגלות שהוא מצב של חושך והעלם והסתר, לא יוט­רדו ויתבלבלו מעבודת השם, ונשארים שלמים במצבם, בלימוד התורה וקיום המצות, ואדרבה, הם שולטים ומושלים על עניני הגלות.\nו. אבל לפי זה הרי מה שיעקב הי' מצפה לו הוא רק מעלה ועילוי במצב ועבודת בנ\"י בגלות לגבי מצבם בלא\"ה בזמן הגלות, אבל סו\"ס ה\"ז מצב וזמן של גלות, ולא מסתבר כ\"כ לומר שיעקב יצפה לזה מתי יבוא.\nולכן י\"ל דזה שיעקב \"הי' ממתין ומצפה מתי יבוא\" קאי ע\"ז שכל אחד מישראל ממתין ומצפה תמיד — על ה­גאולה, גאולת בנ\"י מהגלות, וכמודגש בהמשך לשון רש\"י \"וכן שומר אמו­נים\"<sup data-n=\"1422\">45</sup>, מה שבני ישראל מחכים ומצפים \"לאמונתו של הקב\"ה. . לגאלם\"<sup data-n=\"1423\">46</sup>, מה­גלות<sup data-n=\"1424\">47</sup>.\nוהביאור בזה:\nנתבאר כמה פעמים אשר כללות ה­ענינים המבוארים בפרשה זו קאי לא רק על יעקב אבינו השבטים ויוסף כאנשים פרטיים, אלא מורים על כללות בני יש­ראל שבכל הדורות, ולא רק ככל מעשה אבות המבוארים בספר הישר (ספר ברא­שית) שהם סימן ונתינת כח לבנים<sup data-n=\"1425\">48</sup>, אלא שהדברים עצמם מרמזים על כללות עם ישראל<sup data-n=\"1426\">49</sup>.\nוכמרומז במדרש בפרשתנו<sup data-n=\"1427\">50</sup> \"שבטים היו עסוקין במכירתו של יוסף ויוסף הי' עסוק כו' ראובן הי' עסוק כו' ויעקב הי' עסוק כו' ויהודה הי' עסוק כו' והקב\"ה הי' עוסק בורא אורו של מלך המשיח\", שפנימיות הפירוש בדברי המדרש הוא לא שהשבטים יוסף ראובן יעקב ויהודה הי' כל אחד עוסק בעניניו הפרטיים ו­הקב\"ה הי' עוסק בענין אחר, \"בורא אורו של מלך המשיח\", אלא שזהו אמיתית תוכנו של העסק של כ\"א מהם בפרט<sup data-n=\"1428\">*50</sup>.\nוכשם שבהמשך הפרשה במעשה יהו­",[["1418","41","וראה בארוכה לקו\"ש שנסמן בהערה 32, ושם ע' 255 (וש\"נ) שזה הי' דוקא ביוסף שלא הי' אפילו אצל יעקב."],["1419","42","ראה (בנדו\"ד) תו\"א פרשתנו שם (כח, רע\"ג). תו\"ח שם קה, ד (פ\"י). וראה בארוכה סהמ\"צ להצ\"צ מצות מינוי מלך."],["1420","43","ראה מאמרי אדמו\"ר האמצעי בראשית ע' שא ואילך."],["1421","44","ב\"ר פט\"ז, ד."],["1422","45","ישעי' כו, ב."],["1423","46","רש\"י ישעי' שם."],["1424","47","ראה בארוכה לקו\"ש ח\"ה ע' 181 ואילך בביאור פרש\"י הנ\"ל, ושם ע' 183 ע\"פ פנימיות הענינים."],["1425","48","רמב\"ן עה\"ת לך יב, ו. ובכ\"מ. נסמנו בלקו\"ש חט\"ו ע' 76 הערה 10."],["1426","49","ראה בארוכה עקידה פרשתנו שער כח. וראה צפע\"נ עה\"ת ריש פרשתנו."],["1427","50","ר\"פ פה."],["1428","*50","ראה של\"ה חלק תושב\"כ פרשתנו (רחצ רע\"ב)."]]],[1301670224,"דה ותמר<sup data-n=\"1429\">51</sup> הרי אמיתית תוכנו הוא מה שהקב\"ה הי' עוסק ובורא אורו של משיח, עד\"ז הוא בתחילת הפרשה, ב­חלומו של יוסף, שהיתה הקדמה והכנה לכ\"ז, שיעקב הי' \"ממתין ומצפה מתי יבוא\" מלכותו של יוסף, היינו משיח<sup data-n=\"1430\">52</sup> בן יוסף, שבא כהקדמה והכנה למשיח בן דוד<sup data-n=\"1431\">*52</sup>, כמובא בכ\"מ ברז\"ל<sup data-n=\"1432\">53</sup>.\nוהנה התוכן דממתין ומצפה מתי יבוא מורה על הקירוב והשייכות להדבר ש­אליו מצפים<sup data-n=\"1433\">54</sup>, ומזה גופא הוא הנתינת כח לכאו\"א מישראל בכל משך זמן הגלות להיות ממתין ומצפה מתי יבוא משיח צדקנו לגאול את בני ישראל.\nוכ\"ש וק\"ו בזמן דעקבתא דמשיחא, כשעומדים על סף הגאולה, דאז הוא אמיתית המצב ד\"ממתין ומצפה מתי יבוא\", שהרי אחכה לו בכל יום שיבוא<sup data-n=\"1434\">55</sup>, ולא רק בכל יום ויום, שמחכים שיבוא ביום זה, אלא בכל יום ויום גופא — בכל שעה ושעה, כמו שאומרים ג' פעמים ביום (בימות החול) \"לישועתך קוינו כל היום\"<sup data-n=\"1435\">56</sup>,\nותיכף ומיד מתגלה \"אורו של משיח\", באופן שכאו\"א רואה אותו ומביא את כאו\"א מבני ישראל, אנשים נשים וטף, לארצנו הקדושה, ותיכף ומיד ממש.\n<span data-k=\"q\">(משיחת ש\"פ וישב תשכ\"ז) </span>",[["1429","51","לח, א ואילך. ב\"ר שם."],["1430","52","ראה עקידה שם (רלז, סע\"ב ואילך)."],["1431","*52","ראה בארוכה של\"ה פרשתנו שם (רצט, ב ואילך). וראה תו\"ח שם (קה, ד ואילך), ושם, שהע­ליות דמשיח באות ע\"י בחי' יוסף."],["1432","53","ראה סוכה נב, א­ב. זח\"א בהשמטות רסג, א. ח\"ג רנב, א. ובכ\"מ. — ראה תו\"ש ויחי מט אות של. שערי זהר לסוכה שם, א ובהנסמן שם."],["1433","54","ראה לקו\"ש ח\"ה שם."],["1434","55","נוסח אני מאמין שנדפס בסידורים."],["1435","56","וראה לקו\"ש חלק ל (ע' 83­182) שזה גופא ממהר ומביא את הגאולה."]]],[1301670225,"<h3>שיחה ב</h3>\nא. \"ויהי אחר הדברים האלה חטאו משקה מלך מצרים והאופה גו'\"<sup data-n=\"1436\">1</sup>, ובפ­רש\"י: \"אחר הדברים האלה — לפי ש­הרגילה אותה ארורה<sup data-n=\"1437\">2</sup> [אשת פוטיפר] את הצדיק בפי כולם לדבר בו, הביא להם הקב\"ה סורחנם של אלו שיפנו אליהם ולא אליו<sup data-n=\"1438\">3</sup> [כלומר<sup data-n=\"1439\">4</sup>, לפי שהיו כל דבריהם במה שאירע ליוסף עם אשת אדוניו, מה עשה הקב\"ה, סבב סורחנם של אלו כדי שישובו מלהתעסק בו ולא יזכרו עוד ענין יוסף], ועוד שתבוא הרווחה לצדיק על ידיהם\".\nוהנה משמע שכוונת רש\"י בפירושו היא לבאר ההמשך של פרשה זו (חלומות שר המשקים ושר האופים) לפרשה שלפני' (מעשה יוסף עם אשת פוטיפר), וכלשון הכתוב \"אחר הדברים האלה\", שלשון זו מורה שהוא המשך למ\"ש לפנ\"ז<sup data-n=\"1440\">5</sup>; ומבאר שני טעמים<sup data-n=\"1441\">6</sup> על זה: א) שזה הי' לבטל הלעז שהוציאה אשת פוטיפר על יוסף, ב) על ידי שר המשקים ושר האופים באה הרווחה ליוסף (כמסופר בפ' מקץ<sup data-n=\"1442\">7</sup>).\nולכאורה תמוה, שהרי המשך הספורים בפרשיות אלו ברור ומפורש בפשוטו של מקרא (בריש פרשת מקץ<sup data-n=\"1442\">7</sup>), שע\"י שר המשקים באה הרווחה ליוסף הצדיק — ומה הכריח את רש\"י לחדש, בפשוטו של מקרא, שהסיפור עם שר המשקים ושר האופים הי' כדי לבטל את הלעז שהוציאה אשת פוטיפר על יוסף (ובפרט שכלל לא נזכר בקרא<sup data-n=\"1444\">8</sup>)?!\nיש מפרשים<sup data-n=\"1445\">9</sup>, שמחמת הטעם הנ\"ל, כדי \"שתבוא הרווחה לצדיק על ידיהם\", \"הי' ראוי להביא המעשה הזה בסמוך לחלום — אבל השתא הרי כבר היו י\"ב חודש ב­משמר<sup data-n=\"1446\">10</sup>, ולפיכך צריך לומר טעם הרא­שון ג\"כ\" [כדי לבטל הלעז תומ\"י. ויש לומר, שזה שייך גם כן לשהייתם בבית האסורים י\"ב חודש, כי כדי לבטל ול­",[["1436","1","פרשתנו מ, א."],["1437","2","דיוק ל' רש\"י \"ארורה\" (ולא \"מרשעת\") [וב­פרט שבב\"ר כאן (פפ\"ח, א) ליתא תואר זה, והיא הוספת רש\"י] — י\"ל, כי כבר פרש\"י לעיל (לט, א) \"מה זו (תמר) לשם שמים אף זו לשם שמים\", ולכן לא נק' \"מרשעת\" אלא רק \"ארורה\"<sup data-n=\"e37\">*</sup>, ע\"ד לשון רש\"י לעיל (ח\"ש כד, לט) בנוגע לאליעזר עבד אברהם \"בני ברוך ואתה ארור ואין ארור מדבק בברוך\", שמוכח מזה שלשון \"ארור\" מתאימה גם אם אין שם הנהגה רעה. ונת' בארוכה בההתועדות. ו­אכ\"מ."],["1438","3","ראה גם ב\"ר עה\"פ (שם) — בשינוי לשון."],["1439","4","ל' ספר זכרון על פרש\"י כאן."],["1440","5","ראה גם יפה תואר (השלם) לב\"ר שם. באר יצחק על פרש\"י כאן.\nבמשכיל לדוד כאן פי' שרש\"י בא לתרץ מ\"ש \"אחר\" שפירושו \"סמוך\" (כפרש\"י לעיל לט, ז), \"וביאר. . דמיד אירע דבר זה לפי כו'\". אבל לכאו­רה א\"כ הו\"ל לרש\"י לכתוב בפירוש \"מיד\" (כלשון רש\"י לעיל שם)."],["1441","6","אבל אין הם שני פירושים, דא\"כ הול\"ל \"ד\"א\" (וכיו\"ב), וממ\"ש \"ועוד\" מוכח שכוונתו דתר­ווייהו איתנהו בי'."],["1442","7","מא, ט ואילך."],["1442","7","מא, ט ואילך."],["1444","8","דבכתוב (לט, יד) נאמר רק \"ותקרא לאנשי ביתה\", לא \"בפי כולם\". אלא שבב\"ר עה\"פ שם (פפ\"ז, ח) איתא \"נתנה אותו בפיהם של כולם\"."],["1445","9","גו\"א ועוד כאן.\nאבל מה שכ' צריכותא גם לטעם הב' לכאורה צע\"ג, שהרי זה מפורש בקרא, כנ\"ל בפנים."],["1446","10","לקמן מ, ד ובפרש\"י."],["e37","*","וצע\"ק מפרש\"י פרשתנו לעיל עה\"פ (לז, לג) \"חי' רעה אכלתהו\""]]],[1301670226,"השכיח את הלעז שהוציאה עליו \"בפי כולם\", היו צריכים \"שיפנו אליהם\" במשך זמן רב, י\"ב חודש<sup data-n=\"1447\">11</sup>].\nאבל לכאורה אין ביאור זה מיישב עיקר התמי' בפרש\"י כאן [נוסף לזה שצ\"ע, אם קושי זה (למה היו במשמר י\"ב חודש) הוא טעם מספיק ע\"ד הפשט<sup data-n=\"1448\">12</sup> להכריח דבר שלא נזכר בכתוב, שחטא שר האופים ושר המשקים בא לבטל הלעז כו']: הטעם ד\"תבוא הרווחה לצדיק על ידיהם\" הביא רש\"י רק כטעם שני, בדרך טפל להטעם ד\"לפי שהרגילה כו'\" (\"ועוד שתבוא הרוו­חה כו'\") — ותמוה ביותר, שהרי גם את\"ל שיש הכרח בכתובים שהיתה כוונה נוספת בחטא שר האופים ושר המשקים (לבטל הלעז כו'), למה שבק רש\"י הטעם המבואר בפשוטו של מקרא (\"שתבוא הרווחה לצדיק כו'\") והביא כטעם הראשון (וה­עיקרי) \"לפי שהרגילה כו'\"?\nב. ויש לומר הביאור בזה, ובהקדם:\nבדרך כלל, מפרשים \"אחר הדברים האלה\" — \"אחר המאורעות האלה\", \"דבר\" מלשון \"ענין\"<sup data-n=\"1449\">13</sup>. אבל בפרש\"י מוכח, של­דעת רש\"י עיקר פירוש \"אחר הדברים\" הוא — \"אחר הדיבורים הללו\", \"דבר\" מ­לשון דיבור:\nבתחילת פרשת העקידה, עה\"פ<sup data-n=\"1450\">14</sup> \"ויהי אחר הדברים האלה\", מפרש רש\"י — \"יש מרבותינו אומרים אחר דבריו של שטן שהי' מקטרג כו' וי\"א אחר דבריו של ישמעאל שהי' מתפאר כו'\", שמדיוק לשונו \"אחר דבריו של שטן. . דבריו של ישמע­אל\" מובן, שמפרש \"אחר הדברים\" מלשון דיבור<sup data-n=\"1451\">15</sup> [היינו שמעשה העקידה הי' ב­המשך לדיבורים מיוחדים שלא נתפרשו להדיא בקרא<sup data-n=\"1452\">16</sup>]; וכן אחרי מעשה העקי­דה, עה\"פ<sup data-n=\"1453\">17</sup> \"ויהי אחרי הדברים האלה ויוגד לאברהם גו'\", פרש\"י \"בשובו מהר המורי' הי' אברהם מהרהר ואומר אילו הי' בני שחוט כו' וזהו אחרי הדברים האלה הרהורי דברים שהיו ע\"י העקידה\", הרי מפורש בדבריו שמפרש \"דברים\" מלשון דיבור [שלכן מדייק \"הי' אברהם מהרהר ואומר\", ולא מספיק \"מהרהר\" בלבד].\nועפ\"ז מבואר גם דיוק לשון רש\"י בפ' לך<sup data-n=\"1454\">18</sup> (בפעם הא' שהובא בקרא הלשון \"אחר הדברים אלה\") — \"אחר הדברים האלה הי' דבר ה' אל אברם במחזה גו' אל תירא גו'\", שכתב בפירושו — \"אחר הדב­רים האלה, אחר שנעשה לו נס זה שהרג",[["1447","11","להעיר ממחז\"ל (ברכות נח, א) שהמת משתכח מן הלב לאחר י\"ב חודש. וראה רש\"י שם ד\"ה ככלי אובד, \"סתם כלי לאחר י\"ב חודש משתכח מן הלב\"."],["1448","12","דלכאורה ע\"ד הפשט לא קשה למה עשה ה' ככה שיהיו במשמר י\"ב חודש, שהרי זוהי דרכו של עולם כו' (ובפרט שי\"ל שהי' צ\"ל שהיית זמן עד שיכירו את יוסף עד כדי להגיד לו את חלומותיהם). ולהעיר מסיפור המגילה, שרואים שכל פרטי ה­מאורע היו ע\"י השגחה העליונה מסבב הסיבות כו', ומ\"מ ארך זמן רב מתחילת הסיפור עד להישועה כו'. וכהנה רבות."],["1449","13","כל' רש\"י לעיל לט, יט. וכן צריך לפרש בריבוי מקומות [כמו: היפלא מה' דבר (וירא יח, יד); אל תעשו דבר (שם יט, ח); עשית את הדבר הזה (שם כ, י); הדברים אשר עשה (ח\"ש כד, סו). וכיו\"ב בכ\"מ]."],["1450","14","וירא כב, א."],["1451","15","וההכרח לפרש כן י\"ל מדלא כתיב \"ויהי בעת ההיא\" (ע\"ד פרשתנו לח, א) שג\"כ מורה על סמיכות (ראה רש\"י שם), או \"ויהי אחרי כן\" וכיו\"ב (ראה נזר הקודש הנסמן לקמן הערה 23) — ולכן מפרש שבזה משמיענו הכתוב שבא בהמשך לדיבורים כו'."],["1452","16","ומ\"ש \"הדברים האלה\" — י\"ל עפמ\"ש בגו\"א שם, שזהו \"כאילו כתיב בפירוש דברי השטן\". ע\"ש. וכן בגו\"א לקמן שם כב, כ."],["1453","17","שם, כ."],["1454","18","טו, א."]]],[1301670227,"את המלכים והי' דואג ואומר שמא קבלתי שכר על כל צדקותי לכך אמר לו המקום אל תירא אברם כו'\" — דלכאורה הי' מספיק לומר \"והי' דואג\", ומהו שמוסיף רש\"י \"(דואג) ואומר\"? אלא משום דס\"ל, שכיון שנאמר \"אחר הדברים האלה\", עכצ\"ל שהיו כאן דיבורים שבהמשך אלי­הם בא מאורע זה.\nועד\"ז בפרשתנו לעיל, לאחרי שיוסף הופקד על בית פוטיפר, \"ויעזוב כל אשר לו ביד יוסף גו' ויהי יוסף יפה תואר ויפה מראה\"<sup data-n=\"1455\">19</sup>, נאמר<sup data-n=\"1456\">20</sup> \"ויהי אחר הדברים ה­אלה ותשא אשת אדוניו את עיני' אל יוסף גו'\", ופרש\"י — \"ויהי יוסף יפה תואר, כיון שראה עצמו מושל התחיל אוכל ושותה ומסלסל בשערו, אמר הקב\"ה אביך מת­אבל ואתה מסלסל בשערך אני מגרה בך את הדוב, מיד ותשא אשת אדוניו וגו', כל מקום<sup data-n=\"1457\">21</sup> שנאמר אחר סמוך\" — דגם כאן מדייק רש\"י \"אמר הקב\"ה אביך מתאבל כו'\".\nובפשטות כוונתו לפרש שני ענינים בטעם שהוסיף הכתוב \"אחר הדברים ה­אלה\" [אף שהמשך הענין מובן בפשטות, דכיון ש\"ויהי יוסף יפה תואר ויפה מראה\" לכן \"ותשא אשת אדוניו את עיני' אל יוסף גו'\"]: א) מ\"ש \"אחר\" — \"סמוך\", מלמדנו, שהסיפור עם אשת פוטיפר אירע מיד ל­אחרי שהתחיל לאכול ולשתות ולסלסל בשערו, \"מיד ותשא אשת אדוניו וגו'\", ב) ממ\"ש \"(אחר) הדברים האלה\" למדים, שזה ש\"ותשא אשת אדוניו גו'\" בא בהמשך לדיבורים מיוחדים, \"אמר הקב\"ה אביך מתאבל גו'\"<sup data-n=\"1458\">22</sup>.\nג. ע\"פ כ\"ז מתורץ בפשטות גם פרש\"י דידן, דקשה לי' לרש\"י מ\"ש כאן \"ויהי אחר הדברים האלה חטאו גו'\" — הרי לא מצינו לעיל שום דיבורים שיש להם איזו שייכות לחטא שר המשקים ושר האופים? ולזה מפרש דכוונת הכתוב בהוסיפו \"אחר הדברים האלה\" [אף שבלאו הכי מובן ההמשך בין חלומות שר המשקים ושר ה­אופים להמסופר לפנ\"ז] היא<sup data-n=\"1459\">23</sup> להשמיענו שהיו כאן דיבורים שלא נתפרשו בכתוב — \"שהרגילה אותה ארורה את הצדיק בפי כולם לדבר בו\", ובהמשך לדיבורים אלה \"הביא להם הקב\"ה סורחנם של אלו שיפנו אליהם ולא אליו\".\nאלא שא\"א לרש\"י להסתפק בזה לחוד, דא\"כ הי' משמע שרק זה הוא הטעם ש­סיבב הקב\"ה הסיפור דשר המשקים ושר האופים, והרי בכתובים לקמן מפורש ש­חטא שר המשקים והאופים הביא לידי הרווחת יוסף — ולכן מוסיף רש\"י \"ועוד שתבוא הרווחה לצדיק על ידיהם\", דנוסף על ההמשך בין שני הסיפורים האלה ה­מרומז בלשון \"אחר הדברים האלה\" (שעל זה קאי פרש\"י כאן), היתה גם כוונה (עיק­רית) \"שתבוא הרווחה לצדיק על ידיהם\".\nועפ\"ז מובן ג\"כ זה שרש\"י הביא טעם זה כטעם שני, שאין זה מפני שהוא טפל (בכלל) לטעם הראשון, אלא לפי שרש\"י קאי כאן על התיבות \"אחר הדברים האלה\", שבפירוש תיבות אלו, הרי העיקר הם הדיבורים שהיו לפנ\"ז כו' (\"הדברים האלה\"), אף שבנוגע לכללות שני הסי­פורים, עיקר ההמשך בין שני הסיפורים הוא בטעם השני דוקא, שתבוא הרווחה וכו'.\nויש לומר, שאין כוונת רש\"י בלשון \"ועוד\" שזהו ענין טפל, אלא שזהו לפי",[["1455","19","לט, ו."],["1456","20","שם, ז."],["1457","21","וכ\"ה בפרש\"י לך שם."],["1458","22","ומ\"ש \"אחרי הדברים האלה\" לקמן ר\"פ ויחי (מח, א), לא הוצרך רש\"י לפרש מה הם הדיבורים, כי הם מפורשים בקרא שם (מז, כט­לא)."],["1459","23","ועד\"ז פי' בנזר הקודש (השלם) לב\"ר כאן."]]],[1301670228,"שמפרש הטעמים על פי סדר הזמנים, כי לכל לראש פעל הסיפור דחטא שר ה­משקים והאופים לבטל הלעז, שזה נעשה תומ\"י, ורק אח\"כ — \"ועוד\" — הביא לידי הרווחת אותו צדיק, לאחרי שנתיים ימים כו'.\nד. מ\"יינה של תורה\" שבפירוש רש\"י:\nידוע, שירידת יוסף למצרים היתה ה­התחלה לגלות מצרים<sup data-n=\"1460\">24</sup>, שהיא השורש לכל הגליות, כמחז\"ל<sup data-n=\"1461\">25</sup> \"כל המלכיות (גליות) נקראו על שם מצרים על שם שהם מצירות לישראל\", וגאולתם של ישראל קשורה עם ביטול ה\"מצירים\" והגלות.\nובזה גופא יש, בכללות, שני ענינים: א) ביטול ה\"מצירים\" שלא יוכלו להצר ול­הזיק את ישראל. ב) אתהכפא חשוכא ל­נהורא, שלא זו בלבד שאינם מצירים כו', אלא אדרבה, הם עצמם מסייעים בגאו­לתם של ישראל.\nויש לומר, שזהו התוכן הפנימי בשני הטעמים שבפירוש רש\"י:\nבשלב הראשון, הכוונה בחטא שר המשקים והאופים היתה כדי לבטל הלעז שהוציאה אותה ארורה על יוסף הצדיק, ביטול ה\"מיצר\" כו'; אבל עיקר הכוונה הוא בשלב השני הבא אח\"כ — \"ועוד\" — כדי \"שתבוא הרווחה לצדיק על ידיהם\", שעל ידי שרי פרעה גופא תבוא הרווחה וגאולה ליוסף הצדיק, עד שנעשה \"משנה למלך\".\n(משיחות ש\"פ וישב וש\"פ מקץ תש\"מ)\n{*} {*} {*}\nה. ע\"פ הנ\"ל יש לבאר דרשת ר' ירמי' בר אבא במס' חולין<sup data-n=\"1462\">26</sup> עה\"פ<sup data-n=\"1463\">27</sup> \"ובגפן של­שה שריגים\" (בחלומו של שר המשקים): \"גפן אלו ישראל. . שלשה שריגים אלו ג' רגלים שישראל עולין בהן בכל שנה ושנה, והיא<sup data-n=\"1463\">27</sup> כפורחת<sup data-n=\"1465\">28</sup> הגיע זמנן של ישראל לפרות ולרבות. . עלתה נצה<sup data-n=\"1463\">27</sup> הגיע זמנן של ישראל ליגאל. . הבשילו אשכלותי' ענבים<sup data-n=\"1463\">27</sup> הגיע זמנה של מצרים לשתות כוס התרעלה. . א\"ל ר' אבא לר' ירמי' בר אבא כי דריש להו רב להני קראי באגדתא כוותך דריש להו\" (ולא כדרשות התנאים על פסוק זה שהובאו בגמ' שם לפנ\"ז<sup data-n=\"1468\">29</sup>).\nויש לדייק בסדר הענינים שבדרשת ר' ירמי', דלפי דרשתו נמצא, שקודם \"הגיע זמנן של ישראל ליגאל\" ורק אח\"כ \"הגיע זמנה של מצרים לשתות כוס התרעלה\" — דלכאורה צ\"ל בסדר הפוך, דתחלה צ\"ל ביטול כחה של מצרים, ואח\"כ אפ\"ל ה­גאולה ממצרים?\nגם צריך ביאור — למה הי' רב דורש כפי דרשת ר' ירמי' בר אבא, ולא כדרשות התנאים שלפנ\"ז?\nוביותר תמוה: ר' ירמי' בר אבא הי' תלמידו של רב<sup data-n=\"1469\">*29</sup>, וא\"כ מהו הפירוש בדברי ר' אבא שרב \"כוותך דריש להו\" — לכאורה הול\"ל איפכא, שהוא (ר' ירמי' בר אבא) כיוון לדעת רב (שהוא רבו) ודריש הני קראי כמותו.\nו. ויש לומר הביאור בזה:",[["1460","24","ראה רש\"י פרשתנו (לז, ב): סיבה ראשונה כו'. שם לז, יד: מעצה עמוקה כו'. ועוד."],["1461","25","ב\"ר פט\"ז, ד."],["1462","26","צב, א."],["1463","27","פרשתנו מ, י."],["1463","27","פרשתנו מ, י."],["1465","28","ראה הגהות הב\"ח שם."],["1463","27","פרשתנו מ, י."],["1463","27","פרשתנו מ, י."],["1468","29","ולפנ\"ז מביא גם דרשות כמה אמוראים רק על התיבות \"ובגפן שלשה שריגים\". וראה לקמן הערה 40."],["1469","*29","ברכות כז, ריש ע\"ב (\"תלמיד חבר הוה\")."]]],[1301670229,"מבואר במפרשים<sup data-n=\"1470\">30</sup> הטעם שדרשו רז\"ל פרטי החלום של שר המשקים על \"מעלתם ועניינם ומאורעותיהם\" של ישראל, \"לפי שבאמת נסתבב מחלומו שנתגדל יוסף מזה, וזה הי' תחלת הסיבוב להורדת יש­ראל למצרים אח\"כ והי' הכל ההכנה לה­גאולה הבאה אחריו, א\"כ הי' החלום מרמז בענין ישראל\".\nוהחילוק בין דרשות התנאים לדרשת ר' ירמי' בר אבא הוא, שהם דרשו הכתוב במעלות שונות של ישראל עצמם [ג' אבות, האמהות והשבטים; תורה, משה אהרן ומרים, סנהדרין וצדיקים שבכל דור ודור; ירושלים, מקדש מלך וכה\"ג, פרחי כהונה ונסכים; תורה, באר עמוד ענן ומן, בכורים ונסכים], ואילו ר' ירמי' בר אבא \"מפרש<sup data-n=\"1470\">30</sup> לה לכולא מילתא בעיקר ענין גלות מצרים וגאולתה\".\nועפ\"ז י\"ל, שבדרשתו בא ר' ירמי' בר אבא לרמז גם על העילוי הנפעל ע\"י עבודת בנ\"י בגלות, שהוא לא רק לבטל המיצר של גלות, אלא לפעול שהמצירים עצמם יהפכו לעוזרים ומסייעים את ישר­אל וגאולתם (כנ\"ל ס\"ד).\nוי\"ל שהם שני שלבים בזמן הגאולה עצמו, וכמבואר ברמב\"ם<sup data-n=\"1472\">31</sup> בנוגע לגאולה העתידה, דתחלת הגאולה קשורה עם מל­חמה, שהמלך המשיח \"ילחום מלחמת ה'\", ובתחלה ינצח \"כל האומות שסביביו\"<sup data-n=\"1473\">32</sup> — ביטול המנגד, ואח\"כ בא שלב נעלה יותר, \"לתקן<sup data-n=\"1474\">33</sup> העולם כולו לעבוד את ה' ביחד שנאמר<sup data-n=\"1475\">34</sup> כי אז אהפוך אל עמים גו' לקרוא כולם בשם ה' גו'\", עד ש\"לא יהי' שם כו' ולא מלחמה כו'\"<sup data-n=\"1476\">35</sup>.\nועפ\"ז י\"ל, שזהו התוכן הפנימי בזה ש\"הגיע זמנה של מצרים לשתות כוס התרעלה\", דזה שנמשל לשתיית יין דוקא הוא לפי שאינו ענין של עונש לחוד, אלא בזה נרמזת האתהפכא בעצם מציאותם, ע\"ד \"יין<sup data-n=\"1477\">36</sup> המשכר. . תנו<sup data-n=\"1478\">37</sup> שכר לאובד ויין למרי נפש ישתה וישכח רישו\", שע\"י \"שתי'\" זו נשכח רישו ויכול להתהפך מן הקצה אל הקצה, וכן בעניננו, ששתיית \"כוס התרעלה\" מרמזת על האתהפכא ד­מצרים.\nוזהו שמקדים \"הגיע זמנן של ישראל ליגאל\" לפני \"הגיע זמנה של מצרים לשתות כוס התרעלה\" — כי בתחלה באה גאולתן של ישראל מגלות המלכיות (ע\"י ביטול המיצר כו'); ואח\"כ באים לשלב השני, שמלכיות עצמן מתהפכים (ע\"י \"לש­תות כוס התרעלה\") — ע\"ד שני הטעמים ברש\"י (הנ\"ל) על מעשה שר המשקים ושר האופים<sup data-n=\"1479\">38</sup>: א) ביטול הלעז על יוסף, ב) שתבוא הרווחה לצדיק על ידיהם — שזה כולל לא רק יציאה ממאסר אלא שנעשה משנה למלך.\nז. עפ\"ז יש לבאר הטעם שדרשה זו נאמרה ע\"י ר' ירמי' בר אבא דוקא (ולא ע\"י התנאים):\nידוע, שאצל התנאים לא היתה חשכת הגלות בתוקף, וכמחז\"ל<sup data-n=\"1480\">39</sup> \"ותותר — בימי רבי\",",[["1470","30","עץ יוסף לע\"י שם."],["1470","30","עץ יוסף לע\"י שם."],["1472","31","הל' מלכים ספי\"א."],["1473","32","כ\"ה בכת\"י ודפוסי הרמב\"ם שלא שלטה בהם בקורת הצנזור."],["1474","33","כ\"ה בכת\"י ודפוסים הנ\"ל (לא \"ויתקן\"). ע\"ש."],["1475","34","צפני' ג, ט."],["1476","35","לשון הרמב\"ם שם ספי\"ב (בסיום וחותם ספרו)."],["1477","36","ל' התו\"א ר\"פ מקץ (לא, א). ע\"ש באורך."],["1478","37","משלי לא, ו­ז."],["1479","38","אלא כיון שהרווחה בפועל באה ע\"י שר המשקים, לכן בא הרמז לעילוי זה בחלומו דוקא."],["1480","39","רות ב, יד. שבת קיג, סע\"ב. תו\"א בהוספות קיז, ד."]]],[1301670230,"שעד ימי רבי עדיין היו \"שיריים\" מהתגלות האלקות של זמן הבית [וי\"ל שלכן דרשו התנאים בעיקר במעלותיהן של ישראל, בהיותם במצב של אור וגאו­לה, כנ\"ל];\nמשא\"כ בימי האמוראים התחיל עיקר חושך הגלות, ולכן, דוקא ר' ירמי' בר אבא דריש הכתוב בענין של גלות וגאולת מצרים<sup data-n=\"1481\">40</sup>, ולאידך גיסא — דוקא בדרשתו מודגש העילוי הנפעל ע\"י הירידה בגלות.\nויש לומר, שנרמז גם בשמו — ר' ירמי', מלשון מרירות, וקאי על מרירות הגלות<sup data-n=\"1482\">41</sup>.\nוזהו שמסיים בגמ' \"א\"ל ר' אבא לר' ירמי' בר אבא כי דריש להו רב להני קראי באגדתא כוותך דריש להו\":\nעם היות ש\"רב תנא הוא ופליג\"<sup data-n=\"1483\">42</sup>, מ\"מ, ענינו של רב הי' שהפיץ תורה בבבל דוקא<sup data-n=\"1484\">43</sup> [שלכן נק' רב דוקא (ולא \"רבי\"), כמאמר<sup data-n=\"1485\">44</sup> \"כל רב מבבל וכל רבי מארץ ישראל\", כי בבבל, מקום הגלות, חסר בגילוי אלקות (הנרמז באות יו\"ד)<sup data-n=\"1486\">45</sup>] — ולכן גם רב דריש כר' ירמי' בר אבא דוקא<sup data-n=\"1487\">46</sup>.\nח. ויש לקשר כ\"ז עם חג הגאולה די\"ט כסלו (שחל ברוב השנים בשבוע דפ' וישב):\nידוע<sup data-n=\"1488\">47</sup> שגאולת רבינו הזקן היתה בעת שאמר בתהלים הפסוק<sup data-n=\"1489\">48</sup> \"פדה בשלום נפשי\", ומבואר בכ\"מ<sup data-n=\"1490\">49</sup> הפירוש בכתוב זה, שיש שני אופנים בפדי' — (א) ע\"י מלחמה, שמנצח את האויב, (ב) פדי' בשלום, ובדרך מנוחה, כי \"גם אויביו ישלים אתו\"<sup data-n=\"1491\">50</sup>, וכמחז\"ל<sup data-n=\"1492\">51</sup> (בפירוש המשך הכתוב<sup data-n=\"1489\">48</sup> \"כי ברבים היו עמדי\") שגם אנשי אבשלום התפללו לנצחונו של דוד.\nוהם שני הענינים הנ\"ל — ביטול המנגד, ואח\"כ — \"שתבוא הרווחה לצדיק על ידי­הם\".\n<span data-k=\"q\">(משיחת ש\"פ וישב תשכ\"ו)</span>",[["1481","40","ולהעיר, שגם לפי דרשות האמוראים בתח­לת הסוגיא שם קאי בעניני גלות דוקא — \"שלשה שרי גאים היוצאים מישראל כו'\" (עשירים וקרובים למלכות. רש\"י); \"ג' שרי גוים שמלמדים זכות על ישראל כו'\".\nאלא שבדרשת ר' ירמי' בר אבא \"מפרש לה לכולא מילתא בעיקר ענין גלות מצרים וגאולתה\", ולכן דריש רב כוותי' דוקא. וראה הערה 46."],["1482","41","ובקה\"ר בתחילתו \"ולמה נק' שמו ירמי' שבימיו נעשה ירושלים אירמיאה (חורבה. מת\"כ)\". ולהעיר ממחז\"ל (ב\"ב יד, ב) \"ירמי' כולי' חורבנא\". וראה ס' השיחות תש\"ג (ריש ע' 140). לקו\"ש חי\"ח ע' 343 ואילך. ועוד."],["1483","42","עירובין נ, סע\"ב. וש\"נ."],["1484","43","וראה עירובין (ו, א. וש\"נ) \"רב בקעה מצא וגדר בה גדר\". ועוד."],["1485","44","סדר תנאים ואמוראים בסופו. אגרת רב שרירא גאון, הועתק בערוך ערך אביי (וראה רשב\"ם ב\"ב נב, א ד\"ה אבא בנוגע לרב). הקדמת ספר התי­קונים כת\"י, הובא ונתבאר ע\"ד הקבלה בכתבי האריז\"ל — בתחלת שער מאמרי רשב\"י. עץ חיים שער י\"ט פ\"ג. ונת' ע\"ד החסידות בתו\"א שם."],["1486","45","ראה תו\"א שם."],["1487","46","וזהו דיוק לשון ר' אבא \"רב. . כוותך דריש להו\". דאף שרב תנא כו' (כנ\"ל), מ\"מ דריש כתלמידו (שבדרגת אמוראים), \"כוותך\" דוקא."],["1488","47","כמ\"ש אדה\"ז באגרתו הידועה (נדפסה בס' אגרות קודש שלו סי' לח­לט)."],["1489","48","תהלים נה, יט."],["1490","49","ד\"ה פדה בשלום לאדמו\"ר הזקן (מאמרי אדה\"ז — הקצרים ע' רטז), לאדמו\"ר האמצעי (ב­שע\"ת שלו ח\"א) פי\"א (נה, ד ואילך. וראה שם נא, ג), ועוד."],["1491","50","משלי טז, ז."],["1492","51","ירושלמי סוטה פ\"א סה\"ח."],["1489","48","תהלים נה, יט."]]],[1301670231,"<h3>וישב — חנוכה</h3>\nא. \"ויאמר האיש נסעו מזה כי ש­מעתי אומרים נלכה דתינה גו'\"<sup data-n=\"1494\">1</sup>, ופרש\"י [בהמשך לפירושו הקודם<sup data-n=\"1495\">2</sup> \"וימצאהו איש — זה גבריאל\"] \"נסעו מזה — הסיעו עצמן מן האחוה\"; \"נלכה דותינה — ל­בקש לך נכלי דתות שימיתוך בהם. ולפי פשוטו שם מקום הוא ואין מקרא יוצא מידי פשוטו\".\nהרמב\"ן העתיק לשון רש\"י וכתב \"ו­אין הכוונה לרבותינו שיפרש לו האיש נסעו מזה מן האחוה והלכו לעורר עליך דינין ותרעומות שאם כן הי' נמנע ללכת ולא הי' מסכן בעצמו. אבל הכוונה להם כי האיש גבריאל אשר הגיד לו הגיד אמת ואמר לשון משמש לשני פנים ושני­הם אמת והוא לא הבין הנסתר בו והלך אחר הנגלה ממנו\".\nאבל מפרש\"י משמע, שלפי הדרש \"ה­סיעו עצמן כו' לבקש לך נכלי דתות כו'\", זוהי לשונו של גבריאל אל יוסף. וכן מפורש בפרש\"י בש\"ס<sup data-n=\"1496\">3</sup>, \"משכם גנ­בוהו כדכתיב<sup data-n=\"1497\">4</sup> וישלחהו מעמק חברון ויבא שכמה ושם היו רועין ודותן אינה מקום והאי דכתיב ויאמר האיש נסעו מזה כו' כך אמר לו אתה אומר<sup data-n=\"1498\">5</sup> את אחי אנכי מבקש, סעו מן האחוה הזאת ואין מחזיקין עצמן כאחים לך כי שמעתי אומרים נלכה ונבקש דתות ודינין היאך להמיתו אם יבוא אצלנו\".\nוגם לפי דיוק לשון רש\"י בפירושו עה\"ת כאן, שמסיים \"(ולפי פשוטו שם מקום הוא) ואין מקרא יוצא מידי פשוטו\" — שמזה משמע, שבלימוד ע\"ד הפשט, לא בא הפירוש \"הסיעו עצמן מן ה­אחוה. . לבקש לך נכלי דתות כו'\" לשלול ש\"דותן\" הוא שם מקום, אלא ב' פי' יש בזה —\nמ\"מ נ\"ל, שלכאורה אין כוונת רש\"י בזה כדברי הרמב\"ן [שהמלאך אמר רק \"נסעו מזה. . נלכה דותינה\" אלא שב­תיבות אלו רמז ש\"הסיעו עצמן כו' ל­בקש לך נכלי דתות כו'\" ויוסף \"לא הבין הנסתר בו\"<sup data-n=\"1499\">6</sup>] — כי מסתימת לשון רש\"י \"נסעו מזה — הסיעו כו'; נלכה דותינה — לבקש לך כו'\" (ולא כתב \"רמז לו שהסי­עו כו' לבקש לך כו'\" וכיו\"ב) משמע<sup data-n=\"1500\">7</sup>, שדברים אלו הם בכלל פשט הדברים שנאמרו ליוסף<sup data-n=\"1501\">8</sup>; ומה שמוסיף \"ולפי",[["1494","1","פרשתנו לז, יז."],["1495","2","לז, טו."],["1496","3","סוטה יג, ב ד\"ה משכם גנבוהו. וראה פרש\"י סנהדרין קב, א ד\"ה בשכם שכ' \"ודותן שכתוב בקרא היינו כפר הסמוך לשכם ונקראת ע\"ש שכם, אי נמי כמדרשו שהיו דנים עליו להרגו\"."],["1497","4","לז, יד."],["1498","5","לז, טז."],["1499","6","כמ\"ש במפרשים (אמרי שפר (הובא בדבק טוב בהגהה). הואיל משה (באר היטב), ובאר בשדה ועוד) — בכוונת רש\"י."],["1500","7","וכן לפי המפרשים הנ\"ל — הו\"ל (ראה גם דברי דוד להט\"ז) לרש\"י להקדים \"לפי פשוטו שם מקום הוא\" ואח\"כ להביא הדרש, שבתיבות אלו נרמז גם הענין ד\"הסיעו עצמן כו' לבקש לך נכלי דתות כו'\", ולסיים \"ואין מקרא יוצא מידי פשוטו\"."],["1501","8","ונוסף לזה, אם כדברי הרמב\"ן שיוסף לא הבין הנסתר בו רק הנגלה (ועכצ\"ל לדעתו שכן היתה כוונת השם שלא יבין הנסתר בכדי שתתקיים עצת ה' — ראה רמב\"ן בפסוק טו), א\"כ מהי התועלת בדבריו הנסתרים. ואם יש כוונה, הו\"ל לרש\"י ל­פרשה. ולהעיר מנזר הקודש (הארוך) לב\"ר (פפ\"ד, יג­יד) — מה שתי' לפי' היפה תואר בדברי המדרש."]]]]});
